const OLD_CATEGORIES={Children:'Familia e hijos',Debt:'Deudas e intereses',Education:'Educación',Entertainment:'Entretenimiento',Everyday:'Alimentación',Gifts:'Regalos y donaciones','Health/medical':'Salud',Home:'Vivienda',Insurance:'Seguros',Pets:'Mascotas',Technology:'Tecnología',Transportation:'Transporte',Travel:'Viajes',Utilities:'Servicios básicos',Other:'Otros gastos',Wages:'Salario y nómina',Business:'Negocios y ventas',Investments:'Inversiones',Freelance:'Servicios profesionales'};
const normalizedCategory=(c,t='gasto')=>c==='Other'&&t==='ingreso'?'Otros ingresos':OLD_CATEGORIES[c]||c|| (t==='ingreso'?'Otros ingresos':'Otros gastos');
/* V191: mantener el catálogo original completo; solo ocultar elementos eliminados expresamente. */
const v191Taxonomy=()=>{
  if(!db.hiddenTaxonomy||typeof db.hiddenTaxonomy!=='object')db.hiddenTaxonomy={};
  if(!Array.isArray(db.hiddenTaxonomy.categories))db.hiddenTaxonomy.categories=[];
  if(!Array.isArray(db.hiddenTaxonomy.subcategories))db.hiddenTaxonomy.subcategories=[];
  return db.hiddenTaxonomy;
};
const v191CategoryHidden=(kind,name)=>v191Taxonomy().categories.some(x=>x.kind===kind&&x.name===name);
const v191SubHidden=(kind,cat,name)=>v191Taxonomy().subcategories.some(x=>x.kind===kind&&x.category===cat&&x.name===name);
const v191RemoveCategoryHide=(kind,name)=>{const h=v191Taxonomy();h.categories=h.categories.filter(x=>!(x.kind===kind&&x.name===name))};
const v191RemoveSubHide=(kind,cat,name)=>{const h=v191Taxonomy();h.subcategories=h.subcategories.filter(x=>!(x.kind===kind&&x.category===cat&&x.name===name))};
const categoryMap=kind=>{
 const out=Object.fromEntries(Object.entries(CATALOG[kind]||{}).map(([name,subs])=>[name,[...subs]]));
 for(const c of db.customCategories||[]){if(c.kind!==kind||!c.name)continue;if(!out[c.name])out[c.name]=[];for(const sub of c.subcategories||[])if(!out[c.name].includes(sub))out[c.name].push(sub)}
 for(const name of Object.keys(out)){
   if(v191CategoryHidden(kind,name)){delete out[name];continue}
   out[name]=out[name].filter(sub=>!v191SubHidden(kind,name,sub));
 }
 return out;
};
const categoryOptions=(kind,selected='')=>{
 const options=Object.keys(categoryMap(kind)).map(name=>[name,v255TaxonomyOptionLabel(kind,name)]);
 if(selected&&!options.some(([name])=>name===selected))options.push([selected,v255TaxonomyOptionLabel(kind,selected)+' · histórica']);
 return options;
};
const subcategoryOptions=(kind,category)=>categoryMap(kind)[category]||[];
const subSelect=(kind,cat,value)=>{
 const opts=subcategoryOptions(kind,cat).map(x=>[x,v255TaxonomyOptionLabel(kind,cat,x)]);
 if(value&&!opts.some(([v])=>v===value))opts.push([value,v255TaxonomyOptionLabel(kind,cat,value)+' · histórica']);
 return `<label><span class="filter-label">Subcategoría</span><select class="field" id="subCategory" name="subcategory"><option value="">Sin subcategoría</option>${opts.map(([x,label])=>`<option value="${sanitize(x)}" ${value===x?'selected':''}>${sanitize(label)}</option>`).join('')}</select></label>`;
};

