let db=(()=>{try{const x=JSON.parse(localStorage.getItem(KEY));if(x&&Array.isArray(x.accounts)&&Array.isArray(x.transactions))return {...init(),...x,settings:{...init().settings,...(x.settings||{})}}}catch(e){}return init()})();
let privacyMode=false;
const ui={projectionMenu:false,movementTab:'all',navExpanded:null,showHidden:false,kpiBank:'',kpiEditing:false,page:'overview',expenseRange:'month',bankId:null,bankScope:'all',month:today().slice(0,7),year:new Date().getFullYear(),search:'',transType:'all',txPeriod:'all',reviewFilter:'all',cardId:null,cardDetailTab:'status',cardHistoryCurrency:'DOP',cardHistoryYear:new Date().getFullYear(),accountId:null,loanId:null,annualDetails:true,annualCurrency:'DOP',forecastScenario:'base',forecastHorizon:12,mobile:false};
function migrateData(d){d.banks=Array.isArray(d.banks)?d.banks:[];d.customCategories=Array.isArray(d.customCategories)?d.customCategories:[];
  d.hiddenTaxonomy=(d.hiddenTaxonomy&&typeof d.hiddenTaxonomy==='object'&&!Array.isArray(d.hiddenTaxonomy))?d.hiddenTaxonomy:{};
  d.hiddenTaxonomy.categories=Array.isArray(d.hiddenTaxonomy.categories)?d.hiddenTaxonomy.categories:[];
  d.hiddenTaxonomy.subcategories=Array.isArray(d.hiddenTaxonomy.subcategories)?d.hiddenTaxonomy.subcategories:[];d.certificates=Array.isArray(d.certificates)?d.certificates:[];d.perkUses=Array.isArray(d.perkUses)?d.perkUses:[];d.txRevisions=Array.isArray(d.txRevisions)?d.txRevisions:[];d.rewardBalances=Array.isArray(d.rewardBalances)?d.rewardBalances:[];d.personalLoans=Array.isArray(d.personalLoans)?d.personalLoans:[];d.personalContacts=Array.isArray(d.personalContacts)?d.personalContacts:[];
  const personKey=n=>String(n||'').trim().replace(/\s+/g,' ').toLocaleLowerCase('es');
  for(const l of d.personalLoans){if(l.contactId&&d.personalContacts.some(c=>c.id===l.contactId))continue;const name=String(l.person||'').trim();if(!name)continue;let contact=d.personalContacts.find(c=>personKey([c.firstName,c.lastName].filter(Boolean).join(' '))===personKey(name));if(!contact){const parts=name.split(/\s+/);contact={id:uuid(),firstName:parts.shift()||name,lastName:parts.join(' ')||'Sin apellido',alias:'',phone:'',email:'',notes:'Importado de una relación anterior',createdAt:new Date().toISOString()};d.personalContacts.push(contact)}l.contactId=contact.id;}
  for(const c of d.cards||[]){c.benefitRules=Array.isArray(c.benefitRules)?c.benefitRules:[];c.annualFeeDOP=num(c.annualFeeDOP||0);c.annualFeeUSD=num(c.annualFeeUSD||0);c.rewardsProgram=c.rewardsProgram||'cashback';c.rewardsName=c.rewardsName||''}
  for(let collection of [d.accounts,d.cards,d.loans,d.certificates])for(let item of collection){let raw=String(item.bank||'').trim();if(item.bankId&&d.banks.some(b=>b.id===item.bankId))continue;if(raw){let b=d.banks.find(b=>b.name.toLocaleLowerCase('es')===raw.toLocaleLowerCase('es'));if(!b){b={id:uuid(),name:raw,kind:'Banco',notes:'Importado de la versión anterior',color:'#3868e8'};d.banks.push(b)}item.bankId=b.id}else item.bankId=''}
  for(let t of d.transactions){let kind=t.type==='income'?'ingreso':'gasto';if(t.category)t.category=normalizedCategory(t.category,kind);t.subcategory=t.subcategory||''}
  for(let r of d.recurring){r.category=normalizedCategory(r.category,'gasto');r.subcategory=r.subcategory||''}
  for(let b of d.budgets){b.category=normalizedCategory(b.category,'gasto');b.subcategory=b.subcategory||''}
  ensureDefaultCashAccounts(d);d.version=4;return d;
}
