if(t.type==='adjustment'&&t.accountId===a.id)bal+=amt;
 if(t.type==='certificate_funding'&&t.accountId===a.id)bal-=amt;
 if(t.type==='certificate_redemption'&&t.accountId===a.id)bal+=amt;
