const cutFor=(s,day)=>{let d=dateObj(s),y=d.getFullYear(),m=d.getMonth()+1,cut=monthDay(y,m,day);return s<=cut?cut:monthDay(y,m+1,day)};
const lastCutAt=(s,day)=>{let d=dateObj(s),y=d.getFullYear(),m=d.getMonth()+1,c=monthDay(y,m,day);return c<=s?c:monthDay(y,m-1,day)};
 const lastCut=day=>lastCutAt(today(),day);
const nextCut=day=>{let c=lastCut(day);return monthDay(dateObj(c).getFullYear(),dateObj(c).getMonth()+2,day)};
const cardDue=(cut,day)=>{let d=dateObj(cut),y=d.getFullYear(),m=d.getMonth()+1;let same=monthDay(y,m,day);return same>cut?same:monthDay(y,m+1,day)};
/* V169 · Corte automático, puro y determinista por tarjeta y moneda.
  No registra movimientos, no crea copias de estados en db.statements y se
  recalcula desde el libro al abrir cualquier pantalla (también en móvil).
  Las fechas futuras son orientativas, no se facturan por anticipado. */
function v169CardCycleLedger(c,ccy,asOf=today()){
 const dateOK=value=>/^\d{4}-\d{2}-\d{2}$/.test(String(value||''));
 const cutDay=Math.min(31,Math.max(1,Math.trunc(num(c.cutDay)||1)));
 const dueDay=Math.min(31,Math.max(1,Math.trunc(num(c.dueDay)||1)));
 const startDate=dateOK(c.opened)?c.opened:asOf;
 const opening=ccy==='USD'?num(c.openingUSD):num(c.openingDOP);
 const imported=ccy==='USD'?c.openingBilledUSD:c.openingBilledDOP;
 const events=[];
 const push=(id,date,cut,type,amount,kind)=>{
  if(!dateOK(date)||date>asOf||!(num(amount)>.005))return;
  events.push({id,date,cut,type,amount:rnd(Math.max(0,num(amount))),kind});
 };
 if(opening>.005){
  const billed=imported==null?0:Math.min(opening,Math.max(0,num(imported)));
  if(billed>.005){const previous=lastCutAt(startDate,cutDay);push('opening-billed',previous,previous,'charge',billed,'opening')}
  if(opening-billed>.005)push('opening-unbilled',startDate,cutFor(startDate,cutDay),'charge',rnd(opening-billed),'opening');
 }
 for(const t of v115CardTransactions(c.id,ccy)){
  if(!dateOK(t.date)||t.date>asOf)continue;
  let type='';
  if(t.type==='card_charge')type='charge';
  if(['card_payment','card_refund','card_reward'].includes(t.type))type='credit';
  if(['personal_issue','personal_settlement'].includes(t.type)){
   const relation=personalLoan(t.personalLoanId);
   if(!relation)continue;
   const incoming=(t.type==='personal_issue'&&relation.direction==='borrowed')||(t.type==='personal_settlement'&&relation.direction==='lent');
   type=incoming?'credit':'charge';
  }
  if(type)push(t.id,t.date,cutFor(t.date,cutDay),type,t.amount,t.type);
 }
 events.sort((a,b)=>a.date.localeCompare(b.date)||(a.type===b.type?0:a.type==='charge'?-1:1)||String(a.id).localeCompare(String(b.id)));
 const last=lastCutAt(asOf,cutDay);
 const earliest=events.length?events[0].cut:startDate;
 const first=lastCutAt(earliest,cutDay)===earliest?earliest:cutFor(earliest,cutDay);
 const firstMonth=Number(first.slice(0,4))*12+Number(first.slice(5,7))-1;
 const lastMonth=Number(last.slice(0,4))*12+Number(last.slice(5,7))-1;
 let lots=[],advanceCredit=0,index=0,cycles=[];
 const apply=e=>{
  if(e.type==='charge'){
   let due=e.amount;
   if(advanceCredit>.005){const used=Math.min(due,advanceCredit);due=rnd(due-used);advanceCredit=rnd(advanceCredit-used)}
   if(due>.005)lots.push({cut:e.cut,amount:e.amount,remaining:due,date:e.date});
  }else{
   let amount=e.amount;
   for(const lot of lots){if(amount<=.005)break;const used=Math.min(lot.remaining,amount);lot.remaining=rnd(lot.remaining-used);amount=rnd(amount-used)}
   if(amount>.005)advanceCredit=rnd(advanceCredit+amount);
  }
 };
 // Guardar 240 meses como máximo para limitar trabajo de migraciones con fechas mal importadas.
 const cycleStart=Math.max(firstMonth,lastMonth-239);
 for(let ym=cycleStart;ym<=lastMonth;ym++){
  const year=Math.floor(ym/12),month=ym%12+1,cut=monthDay(year,month,cutDay);
  let newCharges=0,paidInPeriod=0;
  while(index<events.length&&events[index].date<=cut){
   const e=events[index++];
   if(e.type==='charge'&&e.cut===cut)newCharges+=e.amount;
   if(e.type==='credit')paidInPeriod+=e.amount;
   apply(e);
  }
  const pending=rnd(lots.filter(x=>x.cut===cut).reduce((n,x)=>n+x.remaining,0));
  const billed=rnd(lots.filter(x=>x.cut<=cut).reduce((n,x)=>n+x.remaining,0));
  cycles.push({id:String(c.id)+'|'+ccy+'|'+cut,cardId:c.id,currency:ccy,cutDate:cut,dueDate:cardDue(cut,dueDay),
   amount:billed,minimum:rnd(billed*Math.max(0,num(c.minPct||5))/100),newCharges:rnd(newCharges),
   paidInPeriod:rnd(paidInPeriod),pending,closed:true,estimated:true,status:pending>.005?'Pendiente':'Sin deuda pendiente'});
 }
 // Aplicar consumos posteriores al último corte para presentar el ciclo en curso, sin facturarlos.
 for(;index<events.length;index++)apply(events[index]);
 const next=nextCut(cutDay);
 const openAmount=rnd(lots.filter(x=>x.cut>last).reduce((sum,x)=>sum+x.remaining,0));
 const nextCycle={id:String(c.id)+'|'+ccy+'|'+next,cardId:c.id,currency:ccy,cutDate:next,
  dueDate:cardDue(next,dueDay),amount:0,minimum:0,newCharges:openAmount,pending:0,
  closed:false,estimated:true,status:'Ciclo abierto, aún sin facturar'};
 const beyond=monthDay(dateObj(next).getFullYear(),dateObj(next).getMonth()+2,cutDay);
 const futureCycle={id:String(c.id)+'|'+ccy+'|'+beyond,cardId:c.id,currency:ccy,cutDate:beyond,
  dueDate:cardDue(beyond,dueDay),amount:0,minimum:0,newCharges:0,pending:0,
  closed:false,estimated:true,status:'Corte futuro sin importe confirmado'};
 return {cycles,latest:cycles[cycles.length-1]||null,next:nextCycle,future:futureCycle,openAmount};
}

