/* V36 · Notificaciones internas, basadas exclusivamente en vencimientos registrados. */
function v36DueItems(){
 return upcoming().filter(o=>o.kind!=='personal_recv'&&Number(o.amount)>0&&/^\d{4}-\d{2}-\d{2}$/.test(String(o.date||'')));
}
function v36Bell(){
 const todayISO=today();
 const all=v36DueItems().sort((a,b)=>a.date.localeCompare(b.date));
 const notices=all.filter(o=>diffDays(o.date,todayISO)<=14);
 const urgent=all.filter(o=>diffDays(o.date,todayISO)<=7).length;
 const spendAlerts=v123CategoryAlerts();
 const svg=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/></svg>`;
 const items=notices.slice(0,9).map(o=>{
   const d=diffDays(o.date,todayISO),kind=o.kind==='card'?'Tarjeta':o.kind==='loan'?'Préstamo':o.kind==='personal'?'Entre personas':'Suscripción';
   const state=d<0?'Vencido · revisar':d===0?'Vence hoy':d===1?'Mañana':`En ${d} días`;
   return `<article class="v36-notice ${d<0?'v36-expired':d<=3?'v36-urgent':''}"><span class="v36-notice-dot"></span><div><strong>${sanitize(o.name)}</strong><small>${kind} · ${state} · ${prettyDate(o.date)}</small></div><b>${money(o.amount,o.currency,2)}</b></article>`;
 }).join('');
 const spendingItems=spendAlerts.map(a=>`<article class="v36-notice v123-bell-alert"><span class="v36-notice-dot"></span><div><strong>${sanitize(a.category)} · ${a.kind==='trend'?'Tendencia al alza':'Gasto elevado'}</strong><small>${sanitize(v123AlertText(a))}</small></div></article>`).join('');
 const totalAlerts=urgent+spendAlerts.length+v246UnreadReportCount();
 return `<details class="v36-notifications"><summary aria-label="Notificaciones: ${totalAlerts} avisos">${svg}${totalAlerts?`<span class="v36-notification-count">${totalAlerts>99?'99+':totalAlerts}</span>`:''}</summary><div class="v36-notice-pop"><div class="v36-notice-head"><strong>Notificaciones</strong><small>Los informes aparecen a medida que cierra cada período</small></div>${v216BellItems()}${spendingItems}${items}<button type="button" class="v36-notice-footer" data-act="navigate" data-id="payments">Ver todos los compromisos →</button><p class="v36-notice-disclaimer">Los informes de la campanita se habilitan por fecha y hora; no equivalen a notificaciones push cuando la app está cerrada. Los recordatorios de vencimientos se configuran por separado.</p></div></details>`;
}
