  const principal=Math.max(0,num(l.principal)),r=Math.max(0,num(l.rate))/1200/v49LoanPeriodsPerMonth(l),months=Math.min(1200,v49LoanPeriodCount(l));
  const payment=r===0?principal/months:principal*r/(1-Math.pow(1+r,-months));
  let balance=principal,rows=[];
  for(let i=0;i<months&&balance>.005;i++){
    const interest=rnd(balance*r),capital=i===months-1?rnd(balance):rnd(Math.min(balance,Math.max(0,payment-interest)));
    balance=rnd(Math.max(0,balance-capital));
    rows.push({period:i+1,date:v49LoanPeriodDate(l,i),opening:rnd(balance+capital),principal:capital,interest,insurance:v49LoanPeriodInsurance(l,i),fee:v49LoanPeriodFee(l,i),extra:0,payment:rnd(capital+interest+v49LoanPeriodInsurance(l,i)+v49LoanPeriodFee(l,i)),balance,kind:'Original'});
  }
  return {rows,installment:rnd(payment),interest:rnd(rows.reduce((a,b)=>a+b.interest,0)),insurance:rnd(rows.reduce((a,b)=>a+b.insurance,0)),fees:rnd(rows.reduce((a,b)=>a+b.fee,0)),end:rows.at(-1)?.date||l.firstDue};
