function refreshTransferFee(){
 const node=document.getElementById('transferLiveFee'),f=document.getElementById('transactionForm');if(!node||!f)return;
 const a=account(f.elements.accountId?.value),b=account(f.elements.toAccountId?.value),amount=Math.max(0,num(f.elements.amount?.value)),cur=a?.currency||'DOP';
 const pct=num(db.settings.transferTaxPct),fixed=num(cur==='USD'?db.settings.transferFeeUSD:db.settings.transferFeeDOP),rate=num(f.elements.fxRate?.value||db.settings.fx);
 const variable=rnd(amount*pct/100),cost=rnd(variable+fixed);
 const target=rnd(a&&b?(a.currency===b.currency?amount:(a.currency==='USD'?amount*rate:amount/rate)):0);
 node.innerHTML=`<div><strong>Conversión y costos de la transferencia</strong><small>${pct}% + cargo fijo ${money(fixed,cur,2)}. Tasa ${rate.toFixed(4)} RD$ por US$</small></div><div class="v12-fee-breakdown"><span>Envías <b>${money(amount,cur,2)}</b></span><span>Recibe el destino <b>${money(target,b?.currency||cur,2)}</b></span><span>Impuesto <b>${money(variable,cur,2)}</b></span><span>Otro cargo, si aplica <b>${money(fixed,cur,2)}</b></span><span>Cargos <b>${money(cost,cur,2)}</b></span><span>Total debitado <b>${money(amount+cost,cur,2)}</b></span></div><small>Si el banco depositó otra cantidad, introduce el importe real en «Monto recibido». Solo los cargos son gasto; el capital convertido no.</small>`;
}
function refreshCardPaymentPreview(auto=false){
 const f=document.getElementById('transactionForm'),node=document.getElementById('cardPaymentPreview');if(!f||!node)return;
 const c=card(f.elements.cardId?.value),ccy=f.elements.currency?.value||'DOP',st=c?cardStatus(c,ccy):null;
 const billed=Math.max(0,st?.billed??0),total=Math.max(0,st?.debt??0),mode=f.elements.cardPaymentMode?.value||'custom';
 let amt=mode==='cut'?Math.min(billed,total):mode==='total'?total:num(f.elements.amount?.value);
 if(auto&&mode!=='custom'&&f.elements.amount)f.elements.amount.value=rnd(amt).toFixed(2);
 if(f.elements.amount)f.elements.amount.readOnly=mode!=='custom';
 if(mode==='custom')amt=num(f.elements.amount?.value);
 const ac=account(f.elements.accountId?.value),rate=num(f.elements.paymentFxRate?.value||db.settings.fx);
 const debit=f.elements.actualDebitMode?.value==='manual'&&f.elements.sourceAmount?.value!==''?num(f.elements.sourceAmount.value):(ac&&rate>0?v120CardDebit(amt,ccy,ac.currency,rate):amt);
 const channel=normalizePaymentChannel(f.elements.paymentChannel?.value)||'presencial';
 const eligible=isTaxableBankPayment(ac,channel);
 const taxable=eligible&&f.elements.paymentTaxable?.value==='yes';
 const pct=taxable?(f.dataset.id?num(f.elements.paymentTaxPct?.value):cardPaymentSettingsTaxPct()):0;
 const paymentTax=rnd(debit*pct/100);
 const extraCharge=eligible&&f.elements.extraChargeMode?.value==='custom'?Math.max(0,num(f.elements.extraBankFee?.value)):0;
 const totalDebit=rnd(debit+paymentTax+extraCharge);
 const sourceCurrency=ac?.currency||ccy;
 node.innerHTML=`<strong>Deuda de la tarjeta · ${ccy}</strong><div class="v12-fee-breakdown"><span>Al corte <b>${money(billed,ccy,2)}</b></span><span>Saldo total <b>${money(total,ccy,2)}</b></span><span>Modalidad elegida <b>${money(amt,ccy,2)}</b></span>${ac?.currency!==ccy?`<span>Equivalente en ${sourceCurrency} <b>${money(debit,sourceCurrency,2)}</b></span>`:''}<span>Canal de pago <b>${channel==='internet_banking'?'Internet Banking':'Presencial'}</b></span><span>Impuesto bancario ${taxable?`(${pct.toFixed(3)}%)`:''} <b>${money(paymentTax,sourceCurrency,2)}</b></span><span>Total que sale de la cuenta <b>${money(totalDebit,sourceCurrency,2)}</b></span></div><small>${mode==='custom'?'Puedes introducir el abono específico que deseas realizar.':'Importe determinado por la modalidad de pago elegida.'}</small>`;
}
function refreshCardOverdraft(){const f=document.getElementById('cardForm'),node=document.getElementById('cardOverdraftPreview');if(!f||!node)return;
 let d=num(f.elements.limitDOP?.value)*num(f.elements.overdraftPctDOP?.value)/100,u=num(f.elements.limitUSD?.value)*num(f.elements.overdraftPctUSD?.value)/100;
 node.innerHTML=`<strong>Sobregiro adicional autorizado</strong><div class="v12-fee-breakdown"><span>RD$ <b>${money(d,'DOP',2)}</b></span><span>US$ <b>${money(u,'USD',2)}</b></span></div><small>Se suma a cada límite ordinario; no aumenta el límite utilizado para calcular la utilización porcentual del crédito.</small>`;
}

