/* V134 — Patrimonio: cierre por fecha y composición configurable.
   Sin solicitudes remotas ni escrituras en datos financieros. */
const V134_WEALTH_OPTIONS=[
 {id:'history',label:'Evolución histórica',hint:'Cierres mensuales reales por fecha'},
 {id:'breakdown',label:'Activos y obligaciones',hint:'Desglose de cuentas, tarjetas y préstamos'},
 {id:'balance',label:'Balance visual',hint:'Relación entre activos y pasivos'},
 {id:'forecast',label:'Proyección orientativa',hint:'Estimación separada del historial'}
];
let v134WealthSelected=null;
function v134WealthWidgets(){
 if(v134WealthSelected!==null)return v134WealthSelected;
 try{let saved=JSON.parse(localStorage.getItem('vive.el.hoy.patrimony.widgets.v134')||'[]');v134WealthSelected=Array.isArray(saved)?saved.filter(x=>V134_WEALTH_OPTIONS.some(o=>o.id===x)):[]}
 catch(_){v134WealthSelected=[]}
 return v134WealthSelected;
}
function v134WealthSetWidgets(ids){
 v134WealthSelected=[...new Set(ids)].filter(x=>V134_WEALTH_OPTIONS.some(o=>o.id===x));
 try{localStorage.setItem('vive.el.hoy.patrimony.widgets.v134',JSON.stringify(v134WealthSelected))}catch(_){}
}
function v134WealthLoanAsOf(l,cut){
 const started=l.startDate||l.contractDate||(l.firstDue?plusMonths(l.firstDue,-1):l.openingBalanceDate)||today();
 if(started>cut)return {balance:0,estimated:false};
 const original=Math.max(0,num(l.principal));
 const known=l.openingMode==='existing'&&l.openingDebt!==undefined&&l.openingDebt!==null&&l.openingDebt!=='';
 const snapshot=String(l.openingBalanceDate||'').slice(0,10);
 if(known&&snapshot&&cut>=snapshot){
  const after=db.transactions.filter(t=>t.type==='loan_payment'&&t.loanId===l.id&&t.date>snapshot&&t.date<=cut).reduce((sum,t)=>sum+Math.max(0,num(t.principal)),0);
  return {balance:rnd(Math.max(0,num(l.openingDebt)-after)),estimated:false};
 }
 if(known&&snapshot&&cut<snapshot&&l.firstDue){
  let balance=original;
  const reconstructed=v88LoanReconstruction(l);
  for(const r of reconstructed.rows||[]){
   if(r.date>cut)break;
   if(r.kind==='Cuota contractual calculada')balance=Math.max(0,num(r.balance));
  }
  return {balance:rnd(balance),estimated:true};
 }
 const paid=db.transactions.filter(t=>t.type==='loan_payment'&&t.loanId===l.id&&t.date<=cut).reduce((sum,t)=>sum+Math.max(0,num(t.principal)),0);
 return {balance:rnd(Math.max(0,original-paid)),estimated:false};
}
function v134WealthSnapshot(cut){
 return v99Memo('wealth-v134:'+cut,()=>{
  const liquid=db.accounts.reduce((sum,a)=>sum+(a.opened&&a.opened>cut?0:fx(getAccountBalance(a,cut),a.currency)),0);
  const cardDebt=db.cards.reduce((sum,c)=>sum+(c.opened&&c.opened>cut?0:fx(v12CardHistorical(c,'DOP',cut),'DOP')+fx(v12CardHistorical(c,'USD',cut),'USD')),0);
  let estimatedLoan=false;
  const loanDebt=db.loans.reduce((sum,l)=>{const res=v134WealthLoanAsOf(l,cut);estimatedLoan=estimatedLoan||res.estimated;return sum+fx(res.balance,l.currency)},0);
  const certificates=db.certificates.reduce((sum,c)=>{
   if(c.startDate&&c.startDate>cut)return sum;
   const initial=c.capitalMode==='pending'?db.transactions.filter(t=>t.type==='certificate_funding'&&t.certificateId===c.id&&t.date<=cut).reduce((n,t)=>n+num(t.amount),0):num(c.principal);
   const withdrawn=db.transactions.filter(t=>t.type==='certificate_redemption'&&t.certificateId===c.id&&t.date<=cut).reduce((n,t)=>n+num(t.amount),0);
   return sum+fx(Math.max(0,initial-withdrawn),c.currency);
  },0);
  const people=db.personalLoans.reduce((acc,l)=>{
   if(l.date&&l.date>cut)return acc;
   const paid=db.transactions.filter(t=>t.type==='personal_settlement'&&t.personalLoanId===l.id&&t.date<=cut).reduce((n,t)=>n+Math.max(0,num(t.principal)),0);
   const forgiven=l.forgiveness?.date&&l.forgiveness.date<=cut?num(l.forgiveness.amount):0;
   const remaining=fx(Math.max(0,num(l.principal)-paid-forgiven),l.currency);
   if(l.direction==='lent')acc.receivable+=remaining;else acc.payable+=remaining;
   return acc;
  },{receivable:0,payable:0});
  const assets=rnd(liquid+certificates+people.receivable);
  const liabilities=rnd(cardDebt+loanDebt+people.payable);
  return {date:cut,assets,liabilities,net:rnd(assets-liabilities),liquid:rnd(liquid),certificates:rnd(certificates),receivable:rnd(people.receivable),cards:rnd(cardDebt),loans:rnd(loanDebt),payable:rnd(people.payable),estimatedLoan};
 });
}
function v134WealthMonth(period){
 const p=/^\d{4}-(0[1-9]|1[0-2])$/.test(String(period))?String(period):today().slice(0,7);
 const future=p>today().slice(0,7);
 const cut=future?null:(p===today().slice(0,7)?today():periodEnd(+p.slice(0,4),+p.slice(5,7)));
 return {period:p,cut,snapshot:cut&&v14HistoricalAvailable(cut)?v134WealthSnapshot(cut):null,future};
}
function v134WealthChange(now,prev){
 if(!now||!prev)return '<span class="v134-muted">Sin comparación disponible</span>';
 const delta=rnd(now.net-prev.net),denom=Math.abs(prev.net);
 if(denom<.01)return `<span class="v134-muted">Cambio: ${signedCompactAmount(delta,'DOP',true)} · sin base porcentual</span>`;
 const pct=delta/denom*100;
 const label=(pct>0?'+':'')+new Intl.NumberFormat('es-DO',{maximumFractionDigits:1,minimumFractionDigits:1}).format(pct)+'%';
 return `<span class="v134-change ${delta<-.005?'v134-change-down':delta>.005?'v134-change-up':''}" title="Variación exacta: ${label}; diferencia ${money(delta,'DOP',2)}">${label}</span><span class="v134-delta">${signedCompactAmount(delta,'DOP',true)}</span>`;
}
function v134WealthHistory(period){
 const selectedYear=+period.slice(0,4);
 const labels=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
 const data=(year)=>labels.map((_,i)=>{const x=v134WealthMonth(year+'-'+String(i+1).padStart(2,'0'));return x.snapshot?.net??null});
 return v14ChartSvg(labels,[
  {name:String(selectedYear-1)+' · histórico',color:'#9eafcd',values:data(selectedYear-1),width:2.6},
  {name:String(selectedYear)+' · histórico',color:'#6366ef',values:data(selectedYear),width:3.7}
 ]);
}
/* V187: Patrimonio — un solo KPI principal y tres gráficos simultáneos. */
function v187CompositionChart(items,total,variant){
 const max=Math.max(1,...items.map(x=>Math.max(0,Number(x.value)||0)));
 return `<div class="v187-composition" role="group" aria-label="${variant==='assets'?'Distribución de activos':'Distribución de obligaciones'}">${items.map((item,i)=>{
  const pct=Math.max(0,Math.min(100,(Number(item.value)||0)/max*100));
  const share=total>0?((Number(item.value)||0)/total*100):0;
  return `<button type="button" class="v187-composition-item" data-act="v187WealthDetail" data-id="${sanitize(item.id)}" title="${sanitize(item.label)}: ${money(item.value,'DOP',2)}" aria-label="Ver composición de ${sanitize(item.label)}"><span class="v187-composition-top"><span class="v187-comp-number">0${i+1}</span><span class="v187-comp-label">${sanitize(item.label)}</span><b>${money(item.value)}</b></span><span class="v187-comp-track"><i style="width:${pct.toFixed(3)}%;--comp-color:${item.color}"></i></span><span class="v187-composition-foot"><span>${total>0?share.toFixed(1)+'%':'Sin participación'}</span><span aria-hidden="true">↗</span></span></button>`;
 }).join('')}</div>`;
}
function v134WealthWorld(){
 const m=v134WealthMonth(ui.month),s=m.snapshot,cut=m.cut,p=m.period;
 const pastEnd=new Date(Number(p.slice(0,4)),Number(p.slice(5,7))-1,0);
 const prevPeriod=`${pastEnd.getFullYear()}-${String(pastEnd.getMonth()+1).padStart(2,'0')}`;
 const previous=v134WealthMonth(prevPeriod).snapshot;
 const year=Number(p.slice(0,4));
 const val=x=>s?money(x,'DOP',2):'—';
 const assets=[{label:'Cuentas y efectivo',value:s?.liquid||0,id:'liquidity',color:'#587ce6'},
  {label:'Certificados',value:s?.certificates||0,id:'certificates',color:'#76a2e5'},
  {label:'Por cobrar',value:s?.receivable||0,id:'receivable',color:'#6bbaab'}];
 const debts=[{label:'Tarjetas',value:s?.cards||0,id:'cards',color:'#d3917b'},
  {label:'Préstamos',value:s?.loans||0,id:'loans',color:'#a28adf'},
  {label:'Entre personas',value:s?.payable||0,id:'payable',color:'#e1b37e'}];
 const metric=(id,label,value,sub)=>`<button type="button" class="v187-wealth-part v187-wealth-${id}" data-act="v187WealthDetail" data-id="${id}" aria-label="Abrir desglose de ${label}"><span>${label}</span><strong>${val(value)}</strong><small>${sub}</small></button>`;
 return `<div class="v134-patrimony v142-wealth-complete v187-patrimony" id="v134Patrimony">
  <header class="v134-top v187-wealth-top"><div><span class="v134-eyebrow">vive el hoy · PATRIMONIO</span><h2>Lo que tienes. Lo que debes.<br><em>Lo que realmente es tuyo.</em></h2><p>Tu patrimonio al cierre y su evolución, sin sumar crédito disponible como activo.</p></div><div class="v137-wealth-top-tools"><label class="v137-wealth-month-control"><span>Consultar cierre</span><input type="month" data-v137-wealth-month="1" aria-label="Seleccionar mes de patrimonio" value="${p}" max="${today().slice(0,7)}"></label></div></header>
  <section class="v134-hero v187-wealth-hero" aria-label="Balance patrimonial principal">
   <div class="v187-hero-layout"><button type="button" class="v187-hero-primary" data-act="v187WealthDetail" data-id="net" aria-label="Abrir desglose del patrimonio neto"><span class="v187-hero-eyebrow">PATRIMONIO NETO</span><strong>${val(s?.net)}</strong><span class="v187-hero-explain">Lo que realmente es tuyo, después de tus obligaciones</span><span class="v187-hero-change">${s?'Frente al mes anterior: '+(previous?v134WealthChange(s,previous):'sin comparación registrada'):'Sin historial suficiente para este cierre'}</span></button>
   <div class="v187-hero-sides">${metric('assets','Activos',s?.assets,'Dinero en cuentas, certificados y por cobrar')}${metric('liabilities','Pasivos',s?.liabilities,'Tarjetas, préstamos y cuentas por pagar')}</div></div>
   <div class="v187-hero-meta"><span>${s?'Cifras al '+prettyDate(cut):'Período sin corte confirmado'}${s?.estimatedLoan?' · Préstamo histórico parcialmente estimado':''}</span><span>RD$ equivalentes · Pulsa cada cifra para profundizar</span></div>
  </section>
  <section class="v187-charts" aria-label="Tres gráficos del patrimonio">
   <article class="v134-panel v187-chart-card v187-timeline"><header><div><span>01 / EVOLUCIÓN</span><h3>Tu patrimonio en el tiempo</h3><p>${year} frente a ${year-1} · cierres registrados</p></div><button type="button" class="v187-history-launch" data-act="v187History">${icon('chart')} Histórico ${icon('arrow')}</button></header><div class="v187-mini-chart">${v134WealthHistory(p)}</div><p class="v187-graph-foot">Sin valores futuros simulados</p></article>
   <article class="v134-panel v187-chart-card v187-assets"><header><div><span>02 / ACTIVOS</span><h3>De dónde viene</h3><p>Composición al cierre elegido</p></div></header><div class="v187-chart-total">${val(s?.assets)}</div>${v187CompositionChart(assets,s?.assets||0,'assets')}</article>
   <article class="v134-panel v187-chart-card v187-liabilities"><header><div><span>03 / PASIVOS</span><h3>Dónde están las deudas</h3><p>Distribución de obligaciones</p></div></header><div class="v187-chart-total">${val(s?.liabilities)}</div>${v187CompositionChart(debts,s?.liabilities||0,'liabilities')}</article>
  </section>
  <p class="v134-disclaimer v187-footnote">Los datos proceden de productos y movimientos registrados. Los cierres anteriores pueden incorporar préstamos reconstruidos y conversiones de US$ usando la tasa configurada hoy; no representan consultas bancarias históricas en tiempo real.</p>
 </div>`;
}
function v187HistoricRange(range='60'){
 const current=ui.month<=today().slice(0,7)?ui.month:today().slice(0,7);
 const [ey,em]=current.split('-').map(Number),numMonths=range==='all'?240:Math.max(12,Number(range)||60);
 const firstCandidates=[...db.accounts.map(x=>x.opened),...db.cards.map(x=>x.opened),...db.loans.map(x=>x.startDate||x.contractDate||x.firstDue),...db.certificates.map(x=>x.startDate),...db.personalLoans.map(x=>x.date),...db.transactions.map(x=>x.date)].filter(x=>/^\d{4}-\d{2}/.test(String(x))).sort();
 const first=firstCandidates[0]||current;
 const data=[];
 for(let n=numMonths-1;n>=0;n--){const d=new Date(ey,em-1-n,1),p=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;if(p<first.slice(0,7))continue;
  const snap=v134WealthMonth(p).snapshot;data.push({label:p,net:snap?.net??null,assets:snap?.assets??null,liabilities:snap?.liabilities??null});}
 return data;
}
function v187HistorySvg(data){
 const W=Math.max(840,data.length*55),H=345,L=95,R=24,T=24,B=58,values=data.flatMap(x=>[x.net,x.assets,x.liabilities]).filter(x=>Number.isFinite(x));
 if(!values.length)return '<p class="v142-empty-state">No hay cierres suficientes para graficar el rango elegido.</p>';
 const mn=Math.min(0,...values),mx=Math.max(0,...values),span=Math.max(1,mx-mn),x=i=>L+(W-L-R)*i/Math.max(1,data.length-1),y=n=>T+(H-T-B)*(mx-n)/span;
 const guides=Array.from({length:5},(_,i)=>{const v=mn+span*i/4,Y=y(v);return `<line x1="${L}" x2="${W-R}" y1="${Y}" y2="${Y}" stroke="#d6e2f1" stroke-dasharray="4 7"/><text x="${L-10}" y="${Y+4}" text-anchor="end" fill="#6980a2" font-size="12">${(v/1000).toFixed(0)}K</text>`}).join('');
 const series=[['net','#6664ea',3.7,'Patrimonio neto'],['assets','#368ab2',2.5,'Activos'],['liabilities','#dd936b',2.5,'Pasivos']];
 const paths=series.map(([key,color,width,name])=>{
  let d='',live=false;
  const dots=data.map((m,i)=>{const v=m[key];if(v===null){live=false;return ''}d+=(live?' L':' M')+x(i).toFixed(1)+' '+y(v).toFixed(1);live=true;
   return `<circle cx="${x(i)}" cy="${y(v)}" r="3.2" fill="${color}"><title>${name} · ${m.label}: ${money(v,'DOP',2)}</title></circle>`;}).join('');
  return `<path d="${d}" fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round" stroke-linejoin="round"/>${dots}`;
 }).join('');
 const labels=data.map((m,i)=>i%Math.max(1,Math.ceil(data.length/18))===0||i===data.length-1?`<text x="${x(i)}" y="${H-22}" text-anchor="middle" font-size="11" fill="#7388a4">${m.label.slice(2)}</text>`:'').join('');
 return `<div class="v187-history-scroll" tabindex="0"><svg width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" role="img" aria-label="Histórico real de patrimonio, activos y pasivos por mes">${guides}${paths}${labels}</svg></div><div class="v187-history-legend"><span><i style="background:#6664ea"></i> Patrimonio neto</span><span><i style="background:#368ab2"></i> Activos</span><span><i style="background:#dd936b"></i> Pasivos</span></div>`;
}
function v187OpenHistory(range='60'){
 const data=v187HistoricRange(range),first=data[0]?.label||'—',last=data.at(-1)?.label||'—';
 const buttons=[['24','2 años'],['60','5 años'],['120','10 años'],['all','Todo el historial']].map(([id,label])=>`<button type="button" class="${id===range?'selected':''}" data-act="v187HistoryRange" data-id="${id}" aria-pressed="${id===range}">${label}</button>`).join('');
 document.getElementById('modal-root').innerHTML=`<div class="v187-modal-overlay"><section class="v187-history-dialog" role="dialog" aria-modal="true" aria-labelledby="v187HistoryTitle"><header><div><span>HISTÓRICO PATRIMONIAL</span><h2 id="v187HistoryTitle">Evolución registrada</h2><p>${first} → ${last} · ${data.filter(x=>x.net!==null).length} cierres con información</p></div><button type="button" data-act="closeModal" aria-label="Cerrar histórico" class="v187-modal-close">×</button></header><div class="v187-range-controls">${buttons}</div>${v187HistorySvg(data)}<p class="v187-history-caveat">Los meses sin información no se sustituyen por cero. Las cifras históricas son reconstrucciones de tus productos registrados con las tasas de cambio actuales.</p></section></div>`;
 document.querySelector('.v187-modal-close')?.focus({preventScroll:true});
}
function v187WealthRows(cut,kind){
 const items=[];const push=(name,route,amount,currency='DOP',detail='')=>items.push({name,route,amount:fx(amount,currency),original:money(amount,currency,2),detail});
 if(kind==='net'||kind==='assets'||kind==='liquidity')db.accounts.forEach(a=>{if(a.opened&&a.opened>cut)return;push(a.name,'accounts',getAccountBalance(a,cut),a.currency,'Cuenta / efectivo')});
 if(kind==='net'||kind==='assets'||kind==='certificates')db.certificates.forEach(c=>{if(c.startDate&&c.startDate>cut)return;const initial=c.capitalMode==='pending'?db.transactions.filter(t=>t.certificateId===c.id&&t.type==='certificate_funding'&&t.date<=cut).reduce((n,t)=>n+num(t.amount),0):num(c.principal);const redeemed=db.transactions.filter(t=>t.certificateId===c.id&&t.type==='certificate_redemption'&&t.date<=cut).reduce((n,t)=>n+num(t.amount),0);push(c.name,'certificates',Math.max(0,initial-redeemed),c.currency,'Certificado')});
 if(kind==='net'||kind==='liabilities'||kind==='cards')db.cards.forEach(c=>{if(c.opened&&c.opened>cut)return;const rd=v12CardHistorical(c,'DOP',cut),us=v12CardHistorical(c,'USD',cut);push(c.name,'cards',fx(rd,'DOP')+fx(us,'USD'),'DOP',`Deuda RD$ ${money(rd,'DOP',2)} / US$ ${money(us,'USD',2)}`)});
 if(kind==='net'||kind==='liabilities'||kind==='loans')db.loans.forEach(l=>{const v=v134WealthLoanAsOf(l,cut);if(v.balance>.005)push(l.name,'loans',v.balance,l.currency,v.estimated?'Saldo reconstruido':'Capital pendiente')});
 if(['net','assets','liabilities','receivable','payable'].includes(kind))db.personalLoans.forEach(l=>{if(l.date&&l.date>cut)return;const settled=db.transactions.filter(t=>t.type==='personal_settlement'&&t.personalLoanId===l.id&&t.date<=cut).reduce((n,t)=>n+Math.max(0,num(t.principal)),0);const forgiven=l.forgiveness?.date&&l.forgiveness.date<=cut?num(l.forgiveness.amount):0;const remaining=Math.max(0,num(l.principal)-settled-forgiven);if(l.direction==='lent'&&['net','assets','receivable'].includes(kind)||l.direction==='borrowed'&&['net','liabilities','payable'].includes(kind))push(l.person||'Relación personal','personal',remaining,l.currency,l.direction==='lent'?'Por cobrar':'Por pagar')});
 return items.filter(x=>Math.abs(x.amount)>.005).sort((a,b)=>Math.abs(b.amount)-Math.abs(a.amount));
}
function v187OpenWealthDetail(kind){
 const selected=v134WealthMonth(ui.month),snap=selected.snapshot,cut=selected.cut;
 const title=({net:'Patrimonio neto',assets:'Composición de activos',liabilities:'Composición de pasivos',liquidity:'Cuentas y efectivo',certificates:'Certificados financieros',receivable:'Préstamos por cobrar',cards:'Deuda de tarjetas',loans:'Préstamos bancarios',payable:'Deudas entre personas'})[kind]||'Patrimonio';
 if(!snap||!cut)return toast('Este período todavía no tiene datos patrimoniales registrados.');
 const main=({net:snap.net,assets:snap.assets,liabilities:snap.liabilities,liquidity:snap.liquid,certificates:snap.certificates,receivable:snap.receivable,cards:snap.cards,loans:snap.loans,payable:snap.payable})[kind];
 const rows=v187WealthRows(cut,kind),body=rows.map(x=>`<button type="button" class="v187-detail-line" data-act="v187WealthGo" data-id="${sanitize(x.route)}"><span><strong>${sanitize(x.name)}</strong><small>${sanitize(x.detail)}${x.original?` · ${sanitize(x.original)}`:''}</small></span><b>${money(x.amount,'DOP',2)}</b>${icon('arrow')}</button>`).join('');
 document.getElementById('modal-root').innerHTML=`<div class="v187-modal-overlay"><section class="v187-detail-dialog" role="dialog" aria-modal="true" aria-labelledby="v187DetailTitle"><header><div><span>DESGLOSE PATRIMONIAL · ${sanitize(cut)}</span><h2 id="v187DetailTitle">${sanitize(title)}</h2><p>Saldo reconstruido al ${prettyDate(cut)}, expresado en RD$ equivalentes.</p></div><button type="button" data-act="closeModal" aria-label="Cerrar detalle" class="v187-modal-close">×</button></header><div class="v187-detail-big">${money(main,'DOP',2)}</div><div class="v187-detail-list">${body||'<p class="v187-detail-empty">No hay productos registrados en este desglose para el corte elegido.</p>'}</div><p class="v187-history-caveat">Abre un producto para ver su módulo actual. Los valores aquí reflejan el corte elegido; los del módulo pueden corresponder a otro período.</p></section></div>`;
 document.querySelector('.v187-modal-close')?.focus({preventScroll:true});
}

// Selector de corte, exclusivo de Patrimonio; no modifica saldos ni movimientos.
document.addEventListener('change', event=>{
 const element=event.target?.closest?.('[data-v137-wealth-month]');
 if(!element)return;
 const p=String(element.value||'');
 if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(p)||p>today().slice(0,7))return;
 ui.month=p;ui.year=Number(p.slice(0,4));render();
});

const pages={wallet:v68Wallet,projection:patrimonyWorld,patrimony:v134WealthWorld,kpis:kpiStudio,register:moneyRegister,income:incomeAnalysis,expenses:expensesAnalysis,banks,categories,overview,accounts,cards,benefits,personal,payments,loans,certificates,advanced,transactions,recurring,budget,annual,analytics,settings};
const formItem=(name,label,value='',type='text',attrs='')=>`<label><span class="filter-label">${label}</span><input class="field" type="${type}" name="${name}" value="${sanitize(value)}" ${attrs}/></label>`;
const formSelect=(name,label,opts,val='',attrs='')=>`<label><span class="filter-label">${label}</span><select class="field" name="${name}" ${attrs}>${opts.map(o=>{let [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${sanitize(v)}" ${String(v)===String(val)?'selected':''}>${sanitize(l)}</option>`}).join('')}</select></label>`;
const para=(s)=>`<p class="form-note form-full">${s}</p>`;
function modal(title,body,formid,wide=false){document.querySelectorAll('.v36-notifications[open]').forEach(n=>n.open=false);const support=['transactionForm','personalPaymentForm','annualFeeForm','rewardReceivedForm','benefitLedgerForm','recurringPaymentConfirmForm'].includes(formid);const mobileNative=['transactionForm','accountForm','cardForm','loanForm','certificateForm','personalLoanForm','personalPaymentForm','manualBenefitForm','benefitLedgerForm','benefitRuleForm','annualFeeForm','rewardReceivedForm','perkUsageForm','cashWalletForm'].includes(formid);const submitLabel=mobileNative&&isMobileViewport()?'Completar':'Guardar registro';const statusBlock=support?`<div class="form-full confirm-status"><label for="postingStatus">ESTADO DEL REGISTRO</label><select class="field" id="postingStatus" name="postingStatus"><option value="confirmed">Confirmado · contabilizar ahora</option><option value="pending">Pendiente de confirmar · no afectar saldos</option></select><small>Los pendientes permanecerán en Movimientos / Por confirmar. No reducen cuentas ni deudas hasta su confirmación.</small></div>`:'';document.getElementById('modal-root').innerHTML=`<div class="modal-layer" data-backdrop="true"><div class="modal v204-form-dialog ${wide?'wide':''} ${mobileNative?'mobile-native-modal':''}" data-v204-form="${sanitize(formid)}" role="dialog" aria-modal="true" aria-label="${sanitize(title)}"><div class="modal-head"><h2>${sanitize(title)}</h2><button class="close" data-act="closeModal" type="button" aria-label="Cerrar">×</button></div><form id="${formid}"><div class="form-grid">${body}${statusBlock}</div><div id="formError" class="input-error"></div><div class="form-foot"><button class="btn ghost" type="button" data-act="closeModal">Cancelar</button><button class="btn" type="submit">${icon('check')} ${submitLabel}</button></div></form></div></div>`}
