function certificates(){let ordered=db.certificates.filter(c=>ui.showHidden||!isHidden(c)).sort((a,b)=>a.maturityDate.localeCompare(b.maturityDate));return `<div class="section-title"><div><h2>Certificados financieros</h2><p>Capital invertido, intereses estimados, fecha de vencimiento y rendimientos realmente cobrados, por banco.</p></div></div><div class="certificate-grid section v257-cert-grid">${ordered.length?ordered.map(c=>{let p=certProjection(c),days=p.expiry;return `<article class="cert-card glass-loan"><div class="cert-top"><span class="cert-emblem">${icon('building')}</span><div><span class="cert-bank">${sanitize(bankOf(c))}</span><h3>${sanitize(c.name)}</h3></div><span class="pill ${days<0?'orange':days<=30?'blue':'green'}">${days<0?'Vencido':days===0?'Hoy':days+' días'}</span></div><div class="cert-amount">${money(p.capital,c.currency,2)}</div><div class="cert-metrics"><div><span>TASA ANUAL</span><strong>${num(c.rate).toFixed(2)}%</strong></div><div><span>GANANCIA NETA ORIENTATIVA</span><strong>${money(p.net,c.currency,2)}</strong></div><div><span>INTERÉS COBRADO</span><strong>${money(p.collected,c.currency,2)}</strong></div><div><span>VENCE</span><strong>${prettyDate(c.maturityDate)}</strong></div></div><div class="product-mini-actions">${productControls('certificate',c.id,c.archived)}</div><div class="cert-actions"><button class="btn sm ghost" data-act="editCertificate" data-id="${c.id}">Editar</button>${c.capitalMode==='pending'?`<button class="btn sm ghost" data-act="certificateFund" data-id="${c.id}">Constitución</button>`:''}<button class="btn sm ghost" data-act="certificateInterest" data-id="${c.id}">Cobrar interés</button><button class="btn sm soft" data-act="certificateRedeem" data-id="${c.id}">Rescatar capital</button></div></article>`}).join(''):`<div class="panel empty">${db.certificates.some(c=>c.archived)&&!ui.showHidden?`No hay certificados visibles. Tienes ${db.certificates.filter(c=>c.archived).length} archivado(s); utiliza «Archivados» dentro del KPI principal para consultarlos.`:`No tienes certificados registrados. Añade un instrumento vinculado a su banco, moneda, plazo, tasa y retención aplicable.`}</div>`}</div><div class="panel section"><div class="panel-head"><h3>Cómo se contabilizan los certificados</h3></div><div class="grid columns equal"><div class="mini-row"><span>Constitución</span><strong>Cuenta → activo invertido</strong></div><div class="mini-row"><span>Rescate</span><strong>Activo → cuenta</strong></div><div class="mini-row"><span>Intereses</span><strong>Ingreso real cuando se cobra</strong></div><div class="mini-row"><span>Proyecciones</span><strong>No alteran saldos</strong></div></div><p class="footnote">El formulario diferencia certificados ya existentes de capital pendiente de transferir. Si el saldo inicial de una cuenta ya descuenta la constitución del certificado, no registres otra salida: evitarías el doble descuento. La tasa impositiva es editable y debe corresponder a tus condiciones reales.</p></div>`}
function certificateForm(id,preBank){if(!ensureBanks())return;let c=certificate(id)||{},o={name:'',bankId:preBank||'',currency:'DOP',principal:0,rate:0,startDate:today(),maturityDate:plusMonths(today(),12),taxPct:0,payoutFrequency:'maturity',capitalMode:'already',note:'',...c};modal(id?'Editar certificado':'Nuevo certificado financiero',`${formItem('name','Nombre del certificado',o.name,'text','required maxlength="80"')}${formSelect('bankId','Banco emisor',v40FinancialOpts(),preBank||o.bankId,'required')}${formSelect('currency','Moneda',['DOP','USD'],o.currency)}${formItem('principal','Capital original',o.principal,'number','min="0.01" step="0.01" required')}${formSelect('capitalMode','Situación del capital',[['already','Ya estaba constituido y descontado de mis cuentas'],['pending','Todavía debo trasladarlo desde una cuenta']],o.capitalMode||'already')}${formItem('rate','Tasa anual nominal (%)',o.rate,'number','min="0" max="100" step="0.001" required')}${formItem('startDate','Fecha de constitución',o.startDate,'date','required')}${formItem('maturityDate','Fecha de vencimiento',o.maturityDate,'date','required')}${formSelect('payoutFrequency','Pago de interés',[['monthly','Mensual'],['quarterly','Trimestral'],['maturity','Al vencimiento'],['other','Según contrato']],o.payoutFrequency)}${formItem('taxPct','Retención aplicada a intereses (%)',o.taxPct,'number','min="0" max="100" step="0.01"')}${formItem('note','Referencia opcional',o.note||'','text','maxlength="140"')}${para('El saldo invertido se registra como activo distinto del efectivo. Para disminuir una cuenta al constituirlo, usa «Constitución» después de crearlo. Nunca registres de nuevo la salida si ya está reflejada en el saldo inicial.')}`,'certificateForm',true);document.getElementById('certificateForm').dataset.id=id||''}
function certificateTransfer(kind,id){let c=certificate(id);if(!c)return;let ac=db.accounts.filter(a=>a.currency===c.currency);if(!ac.length){toast('Primero crea una cuenta bancaria en '+c.currency);return}if(kind==='certificate_funding'&&c.capitalMode!=='pending'){toast('Capital ya constituido: no lo descuentes dos veces de la cuenta.');return}let already=db.transactions.filter(t=>t.type==='certificate_funding'&&t.certificateId===c.id).reduce((x,t)=>x+num(t.amount),0);let amount=kind==='certificate_funding'?Math.max(0,num(c.principal)-already):certificateCapital(c);transactionForm({type:kind,certificateId:id,accountId:ac[0].id,currency:c.currency,amount:amount,note:kind==='certificate_funding'?'Constitución de certificado':'Rescate de capital del certificado'})}
function annualExpenseInsight(monthly){
 const cat={};monthly.forEach(m=>Object.entries(m.expenseBy||{}).forEach(([name,amount])=>cat[name]=(cat[name]||0)+num(amount)));
 const list=Object.entries(cat).filter(([,value])=>value>0).sort((a,b)=>b[1]-a[1]);
 const total=list.reduce((sum,[,value])=>sum+value,0);
 if(!list.length||total<=0)return '';
 const primary=list[0];const top3=list.slice(0,3).reduce((sum,[,value])=>sum+value,0);const share=100*top3/total;
 return `<aside class="annual-focus-insight" aria-label="Lectura ejecutiva del gasto"><span class="annual-focus-icon">${icon('chart')}</span><div><strong>Lectura rápida del gasto</strong><p>La categoría de mayor importe es <b>${sanitize(primary[0])}</b> (${money(primary[1])}). Tus tres categorías principales concentran <b>${share.toFixed(1)}%</b> de los egresos registrados en el período.</p></div><button class="btn sm ghost" data-act="navigate" data-id="budget">Revisar presupuesto ↗</button></aside>`;
}
function annualGap(current,prior,priorYear,incomeIsGood=true){
 const delta=rnd(current-prior),percentage=Math.abs(prior)>.005?delta/Math.abs(prior)*100:null;
 const tone=Math.abs(delta)<.005?'neutral':delta>0?'good':'warn';
 const pctLabel=percentage===null?'Sin base de comparación':`${percentage>0?'+':''}${new Intl.NumberFormat('es-DO',{maximumFractionDigits:1}).format(percentage)}%`;
 const amountLabel=`${delta>0?'+':''}${money(delta)}`;
 return `<small class="advanced-gap ${tone}" tabindex="0" data-chart-tip="Comparación vs. ${priorYear}|Año seleccionado: ${money(current)}|Año ${priorYear}: ${money(prior)}|Diferencia: ${amountLabel}|Cambio: ${pctLabel}"><span class="comparison-year">vs. ${priorYear}</span>${percentage===null?'<span class="comparison-nobase">Sin referencia</span>':comparisonInline(percentage,delta)}</small>`;
}
function v142AdvancedMonthlyChart(monthly,observed){
 const months=['ENE','FEB','MAR','ABR','MAY','JUN','JUL','AGO','SEP','OCT','NOV','DIC'];
 if(!observed)return '<div class="v142-empty-state">No hay meses observados en el año seleccionado.</div>';
 const data=monthly.slice(0,observed),maximum=Math.max(1,...data.flatMap(m=>[num(m.income),num(m.expense)]));
 const bars=data.map((month,i)=>{
  const inc=num(month.income),exp=num(month.expense),h=n=>Math.max(3,Math.min(100,100*Math.max(0,n)/maximum));
  const description=`${months[i]}: Ingresos ${money(inc,'DOP',2)}; egresos ${money(exp,'DOP',2)}; neto ${money(num(month.net),'DOP',2)}`;
  return `<div class="v142-adv-month" role="img" aria-label="${sanitize(description)}" title="${sanitize(description)}"><div class="v142-adv-bars"><i class="v142-adv-income" style="height:${h(inc)}%"></i><i class="v142-adv-expense" style="height:${h(exp)}%"></i></div><small>${months[i]}</small></div>`;
 }).join('');
 return `<div class="v142-adv-chart" aria-label="Ingresos y gastos por mes en RD$">${bars}</div><div class="v142-adv-legend"><span><i class="v142-adv-income"></i>Ingresos</span><span><i class="v142-adv-expense"></i>Egresos</span><small>Posa el cursor o toca una barra para consultar los importes</small></div>`;
}
function advanced(){
 const y=ui.year,monthly=Array.from({length:12},(_,i)=>monthlyTotals(y,i+1));
 const observed=y===new Date().getFullYear()?new Date().getMonth()+1:y<new Date().getFullYear()?12:0;
 const valid=monthly.slice(0,observed),tot=(arr,key)=>arr.reduce((a,v)=>a+v[key],0);
 const income=tot(valid,'income'),expense=tot(valid,'expense'),net=income-expense;
 const previous=Array.from({length:observed},(_,i)=>monthlyTotals(y-1,i+1));
 const priorIncome=tot(previous,'income'),priorExpense=tot(previous,'expense'),priorNet=priorIncome-priorExpense;
 const indicator=(label,value,earlier,favorable,tone)=>`<div class="advanced-stat v16-annual-clean ${tone}"><span>${label}</span><strong>${money(value)}</strong>${observed?annualGap(value,earlier,y-1,favorable):'<small class="advanced-gap neutral">Sin meses registrados</small>'}</div>`;
 const period=observed===12?'Enero–diciembre':observed>0?`Enero–${new Date(y,observed-1,1).toLocaleDateString('es-DO',{month:'long'})}`:'Sin meses cerrados';
 return `<div class="v142-advanced" id="v142Advanced">
  <header class="advanced-hero v142-advanced-hero"><div><span class="hero-eyebrow">ANALÍTICA AVANZADA · ${y}</span><h2>Tu año, con otra perspectiva.</h2><p>Ingresos, egresos y neto. Comparación ${period.toLowerCase()} ${y} frente al mismo tramo de ${y-1}.</p></div><button class="btn light" data-act="advancedCsv">Exportar CSV ${icon('download')}</button></header>
  <div class="advanced-quick advanced-gaps v14-advanced-three v142-advanced-stats">${indicator('Ingresos del año',income,priorIncome,true,'v14-income')}${indicator('Egresos del año',expense,priorExpense,false,'v14-expense')}${indicator('Neto del año',net,priorNet,true,'v14-net')}</div>
  <div class="v142-advanced-section-title v142-advanced-table-heading"><div><span>01 / BALANCE ANUAL</span><h3>Cuatro cifras. Una lectura del año completo.</h3></div></div>
  ${compactAnnualSummary({inAdvanced:true})}
  <div class="v142-advanced-section-title v142-advanced-table-heading"><div><span>02 / DETALLE POR CATEGORÍA</span><h3>De dónde viene y adónde va el dinero</h3><p>Matriz mensual con categorías y subcategorías, totalmente disponible.</p></div></div>
  ${annualSplitTables()}
  ${annualExpenseInsight(valid)}
  <p class="footnote v14-comparison-foot">Comparación: ${period.toLowerCase()} de ${y} frente al mismo período de ${y-1}. El pago de capital no vuelve a contabilizarse como gasto. Si ${y-1} no tiene datos registrados, se indica «Sin base».</p>
 </div>`;
}

function advancedCsv(){let data=Array.from({length:12},(_,i)=>monthlyTotals(ui.year,i+1)),cats=[...new Set([...EXP,...data.flatMap(m=>Object.keys(m.expenseBy))])],inc=[...new Set([...INC,...data.flatMap(m=>Object.keys(m.incomeBy))])],rows=[['Concepto',...MON,'Total','Promedio']];const push=(label,values,stock=false)=>{let total=values.reduce((a,b)=>a+b,0);rows.push([label,...values.map(v=>rnd(v)),stock?'':rnd(total),rnd(total/12)])};for(let k of inc){push('Ingreso · '+k,data.map(x=>num(x.incomeBy[k])));for(let sub of [...new Set(data.flatMap(x=>Object.keys(x.incomeSubBy).filter(s=>s.startsWith(k+'||')).map(s=>s.split('||')[1])))] )push('  ↳ '+sub,data.map(x=>num(x.incomeSubBy[k+'||'+sub])))}push('TOTAL INGRESOS',data.map(x=>x.income));for(let k of cats){push('Gasto · '+k,data.map(x=>num(x.expenseBy[k])));for(let sub of [...new Set(data.flatMap(x=>Object.keys(x.expenseSubBy).filter(s=>s.startsWith(k+'||')).map(s=>s.split('||')[1])))] )push('  ↳ '+sub,data.map(x=>num(x.expenseSubBy[k+'||'+sub])))}push('TOTAL GASTOS',data.map(x=>x.expense));push('NETO',data.map(x=>x.net));push('SALDO FINAL',data.map(x=>x.ending),true);download('\uFEFF'+rows.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(';')).join('\r\n'),`analitica_avanzada_${ui.year}.csv`,'text/csv;charset=utf-8')}

function loanForm(id,preBank){
 if(!ensureBanks())return;
 const l=loan(id)||{},exists=Boolean(id&&loanTransactions(id).length);
 const o={name:'',bankId:'',currency:'DOP',principal:0,rate:15,months:36,paymentFrequency:'monthly',insuranceKind:'vida',firstDue:plusMonths(today(),1),insuranceMonthly:0,monthlyFee:0,currentInstallment:0,reportedBalance:'',balanceAsOf:today(),...l};
 const lock=exists?'readonly title="El contrato original está protegido porque existen pagos"':'';
 const body=`<div class="form-full smart-sub-intro"><span class="smart-kicker">PRÉSTAMOS · DATOS DEL CONTRATO</span><strong>${id?'Editar préstamo':'Añadir préstamo'}</strong><small>Primero registra el contrato. Ajustes y conciliación abajo.</small></div>
 ${formItem('name','Nombre del préstamo',o.name,'text','required maxlength="80"')}
 ${formSelect('bankId','Institución o entidad',bankOpts(),preBank||o.bankId||'','required')}
 ${formSelect('currency','Moneda',[['DOP','Pesos · RD$'],['USD','Dólares · US$']],o.currency)}
 ${formItem('principal','Capital original',o.principal,'number',`min="0.01" step="0.01" required ${lock}`)}
 ${formItem('rate','Interés anual (%)',o.rate,'number',`min="0" max="300" step="0.001" required ${lock}`)}
 <div class="v49-term-switch form-full"><div class="v49-section-label"><span>02</span><strong>Plazo del contrato</strong><small>Meses, años o número de quincenas</small></div><div class="v49-inline-fields">${formItem('termCount','Duración',o.termUnit==='fortnights'&&num(o.termQuincenas)>0?o.termQuincenas:o.termUnit==='years'?Math.max(1,Math.round(num(o.months)/12)):o.months>0?o.months:36,'number',`min="1" max="1200" step="1" required ${lock}`)}${formSelect('termUnit','Unidad',[['months','Meses'],['years','Años'],['fortnights','Quincenas']],o.termUnit||'months',`id="v49TermUnit" ${exists?'disabled':''}`)}</div><label class="v49-underlying-months" hidden><span>Meses del contrato</span><input type="number" name="months" value="${o.months}" min="1" max="600" required></label></div>
 ${formSelect('paymentFrequency','¿Cada cuánto se paga?',[['monthly','Mensual · una cuota al mes'],['semi_monthly','Quincenal · dos cuotas por mes']],o.paymentFrequency||'monthly',`id="v49LoanFrequency" ${exists?'disabled':''}`)}
  ${formItem('firstDue','Fecha de la primera cuota',o.firstDue,'date',`required ${lock}`)}

 ${v40ModeField(o,'loan')}
 ${formSelect('autoAccountId','Cuenta de débito programado', [['','Selecciona cuenta (obligatorio si es automático)'],...db.accounts.filter(a=>a.currency===o.currency).map(a=>[a.id,a.name+' · '+a.currency])],o.autoAccountId||'')}
 <p class="form-full v40-help">Automático = asiento de pago en vive el hoy al abrir o sincronizar, desde el vencimiento. No ejecuta un débito en el banco. Manual = no modifica saldo hasta que registres el pago.</p>
 <details class="form-full smart-fold"><summary><span class="smart-fold-icon">＋</span><span><strong>Condiciones y conciliación</strong><small>Tasa vigente, seguro, cuota y saldo del banco</small></span><span class="smart-chevron">⌄</span></summary><div class="smart-fold-grid">
 ${formItem('currentRate','Interés anual vigente (%)',o.currentRate??o.rate,'number','min="0" max="300" step="0.001" required')}
 ${formItem('rateEffectiveFrom','Tasa vigente desde (opcional)',o.rateEffectiveFrom||today(),'date','')}
 <div class="v49-insurance-title form-full"><span>03</span><strong>Seguro vinculado al préstamo</strong><small>Este seguro se suma al pago, no al capital amortizado</small></div>
  ${formSelect('insuranceKind','Tipo de cobertura',[['none','Sin seguro'],['vida','Seguro de vida / saldo deudor'],['desgravamen','Desgravamen'],['desempleo','Protección de pagos / desempleo'],['otro','Otro seguro']],o.insuranceKind||'vida','id="v49LoanInsuranceKind"')}
  ${formItem('insuranceMonthly','Costo mensual del seguro',o.insuranceMonthly||0,'number','min="0" step="0.01" id="v49LoanInsuranceAmount"')}
 ${formItem('monthlyFee','Otros cargos mensuales',o.monthlyFee||0,'number','min="0" step="0.01"')}
 ${formItem('currentInstallment','Cuota actual capital + interés',o.currentInstallment||0,'number','min="0" step="0.01"')}
 ${formItem('reportedBalance','Capital confirmado por el banco',o.reportedBalance??'','number','min="0" step="0.01" placeholder="Opcional"')}
 ${formItem('balanceAsOf','Fecha del capital confirmado',o.balanceAsOf||today(),'date','')}
 </div></details>
 <p class="form-full smart-quiet-help">${exists?'El capital y las condiciones del contrato original están protegidos porque ya existen pagos.':'Las cuotas son orientativas; puedes agregar seguro y cargos desde las opciones adicionales.'}</p>`;
 modal(id?'Editar préstamo':'Nuevo préstamo',body,'loanForm',true);
 const f=document.getElementById('loanForm');if(!f)return;f.dataset.id=id||'';f.classList.add('smart-sub-form');
 // En préstamos nuevos, la tasa vigente sigue al contrato mientras no se edite aparte.
 if(!id){let altered=false;f.elements.currentRate.addEventListener('input',()=>{altered=true});f.elements.rate.addEventListener('input',()=>{if(!altered)f.elements.currentRate.value=f.elements.rate.value})}
}


