function v41ServicePicker(id){
 const selected=v41ValidIcon(id);
 return `<section class="v41-icon-selector" aria-label="Ícono de la suscripción"><div class="v41-icon-top"><div><strong>Ícono del servicio</strong><small>Selecciona una identidad o escribe el nombre para obtener una sugerencia.</small></div><div class="v41-sub-preview" id="v41IconPreview">${v41ServiceIcon(selected)}<small>Elegido</small></div></div><input type="hidden" name="serviceIcon" value="${selected}"><input type="search" class="field v41-service-filter" id="v41IconSearch" autocomplete="off" aria-label="Buscar ícono por servicio" placeholder="Buscar: Netflix, internet, iCloud…"><div class="v41-service-grid" id="v41IconGrid">${V41_SERVICES.map(o=>`<button type="button" class="v41-service-choice" data-act="v41PickServiceIcon" data-id="${o.id}" data-icon-label="${sanitize(o.label.toLowerCase())}" aria-pressed="${o.id===selected}">${v41ServiceIcon(o.id)}<span class="v41-choice-label">${sanitize(o.label)}</span></button>`).join('')}</div><div class="v41-service-empty" id="v41IconEmpty" hidden>No hay íconos con ese nombre.</div></section>`;
}
function v41SetServiceIcon(form,id){
 const key=v41ValidIcon(id);
 const input=form?.querySelector('[name="serviceIcon"]');if(!input)return;
 input.value=key;
 form.querySelectorAll('.v41-service-choice').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.id===key)));
 const p=form.querySelector('#v41IconPreview');if(p)p.innerHTML=v41ServiceIcon(key)+'<small>Elegido</small>';
}
function v41WireServicePicker(form){
 if(!form)return;
 const search=form.querySelector('#v41IconSearch');
 search?.addEventListener('input',()=>{
  const term=search.value.trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();let count=0;
  form.querySelectorAll('.v41-service-choice').forEach(el=>{const opt=V41_SVC_BY_ID[el.dataset.id];const label=opt?.label.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()||'';el.hidden=Boolean(term)&&!label.includes(term);if(!el.hidden)count++;});
  const empty=form.querySelector('#v41IconEmpty');if(empty)empty.hidden=!!count;
 });
 const name=form.querySelector('[name="name"]');
 name?.addEventListener('input',()=>{if(form.dataset.v41IconManual==='1')return;const guess=v41GuessIcon(name.value);if(guess!=='general')v41SetServiceIcon(form,guess);});
}

function v147CostPreview(form){
 if(!form)return;
 const text=(id,value)=>{const e=form.querySelector(id);if(e)e.textContent=value};
 const number=Math.max(0,Number(form.elements.amount?.value||0));
 const currency=form.elements.currency?.value||'DOP';
 const symbol=currency==='USD'?'US$':'RD$';
 const freq=form.elements.frequency?.value||'monthly';
 const labels={monthly:'Cada mes',weekly:'Cada semana',quarterly:'Cada 3 meses',annual:'Una vez al año'};
 const monthly=number*({monthly:1,weekly:52/12,quarterly:1/3,annual:1/12}[freq]||1);
 const fmt=n=>symbol+new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
 text('[data-v147-amount]',fmt(number));
 text('[data-v147-monthly]',fmt(monthly));
 text('[data-v147-cycle]',labels[freq]||'Recurrente');
 const due=form.elements.nextDue?.value||'';
 let dueLabel=due; if(/^\d{4}-\d{2}-\d{2}$/.test(due)){try{dueLabel=new Date(due+'T12:00:00').toLocaleDateString('es-DO',{day:'numeric',month:'short',year:'numeric'})}catch(e){}}
 text('[data-v147-due]',dueLabel||'Por definir');
 const name=form.elements.name?.value?.trim()||'Tu próximo pago';
 text('[data-v147-name]',name);
 const sel=form.elements.source;
 text('[data-v147-account]',sel?.selectedOptions?.[0]?.text?.trim()||'Selecciona cuenta o tarjeta');
 const ico=form.querySelector('[name="serviceIcon"]')?.value||'general';
 const mark=form.querySelector('[data-v147-mark]');if(mark)mark.innerHTML=v41ServiceIcon(ico);
 form.querySelectorAll('[data-v147-frequency]').forEach(btn=>{let active=btn.dataset.v147Frequency===freq;btn.setAttribute('aria-pressed',String(active))});
}
function v147WireRecurring(form){
 if(!form)return;
 const update=()=>v147CostPreview(form);
 form.addEventListener('input',update);
 form.addEventListener('change',event=>{
  if(event.isTrusted&&(event.target.id==='recCategory'||event.target.id==='subCategory'))form.dataset.v160CategoryManual='1';
  update();
 });
 form.addEventListener('click',event=>{
  const freq=event.target.closest('[data-v147-frequency]');
  if(freq){event.preventDefault();form.elements.frequency.value=freq.dataset.v147Frequency;form.elements.frequency.dispatchEvent(new Event('change',{bubbles:true}));update();return}
  const preset=event.target.closest('[data-v147-preset]');
  if(preset){event.preventDefault();const k=preset.dataset.v147Preset;const names={netflix:'Netflix',spotify:'Spotify',internet:'Internet hogar',utilities:'Servicios básicos',gym:'Gimnasio',insurance:'Seguro'};
   if(!form.elements.name?.value?.trim())form.elements.name.value=names[k]||'';
   // Un acceso rápido nuevo propone una clasificación válida del catálogo de Gastos.
   // No reemplaza la clasificación histórica ni las elecciones manuales del usuario.
   if(!form.dataset.id&&form.dataset.v160CategoryManual!=='1'){
    const taxonomy={netflix:['Entretenimiento','Streaming'],spotify:['Suscripciones','Música'],internet:['Servicios básicos','Internet hogar'],utilities:['Servicios básicos','Otros servicios'],gym:['Salud','Gimnasio'],insurance:['Seguros','Pago de seguro']};
    const pair=taxonomy[k];
    if(pair&&subcategoryOptions('gasto',pair[0]).includes(pair[1])){
     const category=form.querySelector('#recCategory'),sub=form.querySelector('#subCategory');
     if(category&&sub){category.value=pair[0];category.dispatchEvent(new Event('change',{bubbles:true}));sub.value=pair[1];}
    }
   }
   v41SetServiceIcon(form,k);form.dataset.v41IconManual='1';update();return}
  if(event.target.closest('[data-act="v41PickServiceIcon"]'))requestAnimationFrame(update);
 });
 update();
}
function recurringForm(id){
 const r=db.recurring.find(r=>r.id===id)||{},o={name:'',category:Object.keys(categoryMap('gasto'))[0]||'',frequency:'monthly',amount:0,currency:'DOP',source:'',nextDue:today(),active:true,...r};
 const sources=[['','Selecciona la cuenta o tarjeta'],...db.accounts.map(a=>[`account:${a.id}`,`${a.name} · ${a.currency}`]),...db.cards.map(c=>[`card:${c.id}`,`${c.name} · RD$ / US$`])];
 const cycle=[['monthly','Mensual'],['weekly','Semanal'],['quarterly','Trimestral'],['annual','Anual']];
 // La suscripción reutiliza el MISMO catálogo de Gastos (incluidas categorías personalizadas).
 // Si una categoría histórica ya no existe en el catálogo, preservarla al editar.
 const expenseCategories=categoryOptions('gasto');
 if(id&&o.category&&!expenseCategories.some(([key])=>key===o.category))expenseCategories.push([o.category,o.category+' · histórica']);
 const mark=v41ServiceIcon(o.iconId||v41GuessIcon(o.name));
 const body=`<div class="v147-rec-shell form-full">
  <div class="v147-rec-hero"><div class="v147-hero-copy"><span class="v147-eyebrow">vive el hoy · COMPROMISOS</span><strong>${id?'Perfecciona tu pago':'Un pago menos que recordar.'}</strong><p>Configura el compromiso una vez. Tu agenda sabrá cuándo vuelve a vencer.</p></div><div class="v147-hero-stamp" aria-hidden="true">${icon('cycle')}</div></div>
  <div class="v147-rec-layout"><div class="v147-rec-editor">
   <section class="v147-rec-section" aria-label="Identidad del pago"><div class="v147-sec-head"><span class="v147-step">01</span><div><strong>¿Qué vas a pagar?</strong><small>Identifica el servicio y clasifícalo como cualquier gasto.</small></div></div>
    <div class="v147-form-duo">${formItem('name','Nombre del servicio',o.name,'text','required maxlength="90" placeholder="Ej. Internet hogar"')}
    ${formItem('amount','Importe por cobro',o.amount,'number','min="0.01" step="0.01" required')}</div>
    <div class="v160-rec-taxonomy" role="group" aria-label="Clasificación del pago">
      <div class="v160-rec-taxonomy-heading"><strong>Categoría y subcategoría</strong><small>Catálogo compartido con Gastos</small></div>
      <div class="v147-form-duo v160-taxonomy-fields">${formSelect('category','Categoría',expenseCategories,o.category,'id="recCategory"')}${subSelect('gasto',o.category,id?o.subcategory||'':'')}</div>
    </div>
    <div class="v147-popular-head">Accesos visuales rápidos <span>Opcional</span></div>
    <div class="v147-quick-icons">${[['netflix','Netflix'],['spotify','Spotify'],['internet','Internet'],['utilities','Servicios'],['gym','Gimnasio'],['insurance','Seguro']].map(([key,label])=>`<button type="button" class="v147-preset" data-v147-preset="${key}">${v41ServiceIcon(key,'tiny')}<span>${label}</span></button>`).join('')}</div>
    <details class="v147-icon-drawer"><summary>${icon('palette')} <span>Personalizar icono</span><small>Catálogo ampliado · buscar</small>${icon('chevron-down')}</summary><div class="v147-icon-content">${v41ServicePicker(o.iconId||v41GuessIcon(o.name))}</div></details>
   </section>
   <section class="v147-rec-section" aria-label="Pago y calendario"><div class="v147-sec-head"><span class="v147-step">02</span><div><strong>¿Cómo y cuándo se cobra?</strong><small>Define la cuenta, el ciclo y la fecha que verá Próximos pagos.</small></div></div>
    <div class="v147-form-duo">${formSelect('currency','Moneda',[['DOP','Pesos · RD$'],['USD','Dólares · US$']],o.currency)}${formSelect('source','Cuenta o tarjeta de pago',sources,o.source,'required')}</div>
    <label class="v147-cycle-label">Periodicidad</label><div class="v147-frequencies" role="group" aria-label="Periodicidad del pago">${cycle.map(([key,label])=>`<button type="button" class="v147-freq-btn" data-v147-frequency="${key}" aria-pressed="${String(o.frequency===key)}">${label}</button>`).join('')}</div>
    <div class="v147-hidden-freq">${formSelect('frequency','Frecuencia',cycle,o.frequency)}</div>
    <div class="v147-form-duo">${formItem('nextDue','Próximo vencimiento',o.nextDue,'date','required')}${v40ModeField(o,'recurring')}</div>
    <p class="v147-fineprint">${icon('info')} El registro automático crea movimientos dentro de la app al procesar el vencimiento; no ejecuta cargos en el banco. Si prefieres revisar cada pago, elige confirmación manual.</p>
   </section>
   <section class="v160-rec-status" aria-label="Estado del compromiso">
     <div class="v160-rec-status-copy"><span class="v160-rec-status-icon">${icon('check')}</span><span><strong>Estado del compromiso</strong><small>Activa para incluirlo en Próximos pagos; pausa para suspender vencimientos futuros.</small></span></div>
     <div class="v160-rec-status-select">${formSelect('active','Estado',[['true','Activa'],['false','Pausada']],String(o.active))}</div>
   </section>
  </div>
  <aside class="v147-rec-aside" aria-label="Vista previa del nuevo compromiso"><span class="v147-aside-label">VISTA PREVIA · PRÓXIMO COMPROMISO</span><div class="v147-card-top"><span data-v147-mark>${mark}</span><div><strong data-v147-name>${sanitize(o.name||'Tu próximo pago')}</strong><small data-v147-cycle>Recurrente</small></div></div><strong class="v147-price" data-v147-amount>RD$0.00</strong><div class="v147-price-caption">Importe por vencimiento</div><div class="v147-preview-rule"></div><div class="v147-preview-pair"><span>Próximo pago</span><strong data-v147-due>${sanitize(o.nextDue)}</strong></div><div class="v147-preview-pair"><span>Equivalente mensual*</span><strong data-v147-monthly>RD$0.00</strong></div><div class="v147-preview-pair"><span>Desde</span><strong data-v147-account>Elige una cuenta</strong></div><div class="v147-preview-note">${icon('calendar')} Aparecerá en Próximos pagos. Guardarlo no descuenta tu saldo.</div><small class="v147-preview-footnote">*Estimación de periodicidad para planificación; no es un gasto registrado.</small></aside>
  </div>
 </div>`;
 modal(id?'Editar pago recurrente':'Nuevo pago recurrente',body,'recurringForm',true);
 const f=document.getElementById('recurringForm');if(f){
   f.dataset.id=id||'';f.classList.add('smart-sub-form','v147-rec-form');
   // Evitar la pérdida silenciosa de una subcategoría histórica personalizada al editar.
   const sub=f.querySelector('#subCategory');
   if(sub&&o.subcategory&&!Array.from(sub.options).some(opt=>opt.value===o.subcategory)){
     sub.add(new Option(o.subcategory+' · histórica',o.subcategory,true,true));
   }
   v41WireServicePicker(f);v147WireRecurring(f);
 }
}

