 if(['income','expense','card_charge','card_refund'].includes(type)){let kind=type==='income'?'ingreso':'gasto',category=(editId&&o.category)?o.category:(Object.prototype.hasOwnProperty.call(categoryMap(kind),o.category)?o.category:(Object.keys(categoryMap(kind))[0]||''));body+=formSelect('category','Categoría',categoryOptions(kind,editId?o.category:''),category,'id="txCategory"')+subSelect(kind,category,editId?o.subcategory||'':'')}
