/* ========================================================================
   vive el hoy · MOTOR DE OPERACIONES CONTEXTUALES 2026
   Las operaciones de capital no se reconocen como ingreso/egreso económico.
   El impuesto (configurable) y el cargo bancario son componentes separados.
   Tarjetas RD$/US$: consumo aumenta deuda, pago reduce deuda sin duplicar gasto.
   ======================================================================== */
function refreshLegacyLoanPayment(){
 const f=document.getElementById('transactionForm');if(!f||f.dataset.guided==='yes'||f.elements.type?.value!=='loan_payment')return;
 const acc=account(f.elements.accountId?.value),loanSelected=loan(f.elements.loanId?.value);
 const channel=normalizePaymentChannel(f.elements.paymentChannel?.value)||'presencial';
 if(f.elements.paymentChannel){for(const opt of f.elements.paymentChannel.options)opt.disabled=acc?.kind==='cash'&&opt.value==='internet_banking';if(f.elements.paymentChannel.selectedOptions[0]?.disabled)f.elements.paymentChannel.value='presencial'}
 const eligible=isTaxableBankPayment(acc,f.elements.paymentChannel?.value);
 const block=document.getElementById('loanBankTaxBlock');if(block)block.hidden=!eligible;
 if(f.elements.paymentTaxable&&!eligible)f.elements.paymentTaxable.value='no';
 const rateField=f.elements.paymentTaxPct;if(rateField)rateField.closest('label').hidden=!eligible||f.elements.paymentTaxable?.value!=='yes';
 const p=eligible&&f.elements.paymentTaxable?.value==='yes'?num(rateField?.value):0;
 const amount=num(f.elements.sourceAmount?.value||f.elements.amount?.value);
 const target=document.getElementById('loanBankTaxSummary');if(target)target.innerHTML=`<small>Impuesto estimado: <b>${money(rnd(amount*p/100),acc?.currency||'DOP',2)}</b> · No reduce capital del préstamo.</small>`;
 const conversion=document.getElementById('legacyPaymentConversion');if(conversion)conversion.hidden=!loanSelected||!acc||loanSelected.currency===acc.currency;
 if(conversion?.hidden&&f.elements.sourceAmount)f.elements.sourceAmount.value='';
 const breakdown=document.getElementById('v49PaymentBreakdown');
 if(breakdown){const p1=num(f.elements.principal?.value),i=num(f.elements.interest?.value),ins=num(f.elements.insurance?.value),fee=num(f.elements.fee?.value),total=num(f.elements.amount?.value);const valid=Math.abs(p1+i+ins+fee-total)<=.025;
 breakdown.innerHTML=`<span class="v49-quiet-tag">RESUMEN DEL PAGO</span><div class="v49-pay-summary-grid"><div><small>Capital amortizado</small><b>${money(p1,loanSelected?.currency||'DOP',2)}</b></div><div><small>Interés</small><b>${money(i,loanSelected?.currency||'DOP',2)}</b></div><div><small>Seguro</small><b>${money(ins,loanSelected?.currency||'DOP',2)}</b></div><div><small>Otros cargos</small><b>${money(fee,loanSelected?.currency||'DOP',2)}</b></div></div><footer class="${valid?'v49-ok':'v49-warn'}"><span>${valid?'Total de cuota validado':'Revisa: el desglose no coincide con el total'}</span><strong>${money(total,loanSelected?.currency||'DOP',2)}</strong></footer>`;
 }
}
document.addEventListener('change',e=>{if(e.target.form?.id==='transactionForm'&&e.target.form.dataset.guided!=='yes'&&e.target.form.elements.type?.value==='loan_payment'){if(e.target.name==='date'&&e.target.form.elements.paymentTaxPct)e.target.form.elements.paymentTaxPct.value=recommendedTax(e.target.value);refreshLegacyLoanPayment()}});
document.addEventListener('input',e=>{if(e.target.form?.id==='transactionForm'&&e.target.form.dataset.guided!=='yes'&&e.target.form.elements.type?.value==='loan_payment')refreshLegacyLoanPayment()});
const TAX_RATE_CHANGE='2026-07-03';
function statutoryTransferRate(date=today()){return date>=TAX_RATE_CHANGE?.2:.15}
function recommendedTax(date=today()){return statutoryTransferRate(date)}
