  if(isPay){lines+=`<span>Deuda que se reduce <b>${displayAmount}</b></span>`;if(requiresFx){lines+=`<span>Tasa aplicada <b>RD$${rate.toFixed(4)} por US$1</b></span>`;lines+=`<span>Se descontarán de tu cuenta <b>${money(actualDebit,sourceCurrency,2)}</b></span>`}}
  if(isInstant)lines+=`<span>Pago al instante · RD$100 <b>${money(speedFee,sourceCurrency,2)}</b></span>`;
  if(taxable)lines+=`<span>Impuesto bancario (${pct.toFixed(3)}%) <b>${money(tax,isPay?sourceCurrency:curr,2)}</b></span>`;
  else if(isPay)lines+=`<span>Impuesto bancario · ${ch==='presencial'?'presencial (no se aplica)':'exento / no aplicable'} <b>${money(0,sourceCurrency,2)}</b></span>`;
  if(otherFee)lines+=`<span>Otro cargo bancario <b>${money(otherFee,isPay?sourceCurrency:curr,2)}</b></span>`;
  if(mode==='income')lines+=`<span class="flow-receipt-total">Se acredita a tu cuenta <b>${displayAmount}</b></span>`;
  else if(usingCard)lines+=`<span class="flow-receipt-total">Nueva deuda de tarjeta <b>${displayAmount}</b></span>`;
  else lines+=`<span class="flow-receipt-total">Se descuenta de ${isPay?sourceCurrency:curr} <b>${money(total,isPay?sourceCurrency:curr,2)}</b></span>`;
  const note=isOwn?(canInstant?'Las transferencias entre cuentas propias están exentas de impuesto. Solo un cargo bancario efectivo constituye gasto.':'Mover dinero propio no es ingreso ni gasto; estas transferencias no pagan impuesto.'):isPay?'Se reduce la deuda existente; el pago del principal no es otro gasto.':usingCard?'La tarjeta financia el gasto; su pago posterior no vuelve a sumarlo.':mode==='income'?'El dinero aumenta la cuenta seleccionada.':'El dinero se descuenta del saldo elegido.';
  receipt.innerHTML=`<div class="flow-receipt-title"><span>${icon('receipt')} Antes de guardar</span><span>RESUMEN AUTOMÁTICO</span></div><div class="flow-receipt-lines">${lines}</div><small>${note}</small>`;
