function nextRecurringDate(r){return v96NextRecurringDate(r.nextDue,r.frequency,r.billingDay||dateObj(r.nextDue).getDate())}
function payRecurring(id){let r=db.recurring.find(x=>x.id===id);if(!r||r.active===false)return;const [src,ref]=String(r.source||'').split(':');guidedTransactionForm({flowMode:'service',type:src==='card'?'card_charge':'expense',paymentSource:src==='card'?'card':'account',cardId:src==='card'?ref:db.cards[0]?.id,accountId:src==='account'?ref:db.accounts[0]?.id,amount:r.amount,currency:r.currency,category:r.category,subcategory:r.subcategory||'',servicePreset:'other',note:r.name,recurringId:r.id,paymentChannel:'internet_banking'});}
function executeRecurringPayment(v){let r=db.recurring.find(a=>a.id===v.recurringId);if(!r||r.active===false)throw Error('La suscripción no está disponible.');let [type,ref]=String(r.source||'').split(':');let a=type==='account'?account(ref):null,c=type==='card'?card(ref):null;if(!a&&!c)throw Error('Edita la suscripción y selecciona una cuenta o tarjeta activa.');if(a&&a.currency!==r.currency)throw Error('La moneda del cargo debe coincidir con la cuenta.');let amount=num(v.amount),date=v.date||today();if(!(amount>0))throw Error('El importe de pago debe ser positivo.');if(date>today())throw Error('No registres un cargo futuro como confirmado.');db.transactions.push({id:uuid(),created:new Date().toISOString(),date,type:a?'expense':'card_charge',note:r.name+' · Pago recurrente',category:r.category,subcategory:r.subcategory||'',accountId:a?a.id:'',cardId:c?c.id:'',currency:r.currency,amount:rnd(amount),recurringId:r.id,scheduleKey:`recurring:${r.id}:${r.nextDue}`,postingOrigin:'manual'});r.nextDue=nextRecurringDate(r);}
function download(text,file,type){let blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=file;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function exportJson(){download(JSON.stringify({...db,exportedAt:new Date().toISOString()},null,2),`vive-el-hoy-respaldo-${today()}.json`,'application/json')}
function csv(){
 // Exportación integral: una fila por movimiento, con categoría y subcategoría separadas.
 const headers=['Fecha','Tipo','Concepto','Categoría','Subcategoría','Moneda','Importe','Débito cuenta','Interés','Capital','Cuenta origen','Cuenta destino','Tarjeta','Préstamo','Canal','Beneficiario','Impuesto','Cargo bancario','Impuesto transferencia','Cargo transferencia'];
 const rows=[headers,...recentTx().map(t=>[
  t.date,TRANSL[t.type]||t.type,transactionTitle(t),t.category||'',t.subcategory||'',t.currency||'DOP',
  t.amount??'',t.sourceAmount??'',t.interest??'',t.principal??'',
  account(t.accountId)?.name||'',account(t.toAccountId)?.name||'',
  card(t.cardId)?.name||'',loan(t.loanId)?.name||'',t.paymentChannel||'',
  t.payee||'',t.paymentTax??0,t.paymentFee??0,t.transferTax??0,t.transferFixedFee??0
 ])];
 const numeric=new Set([6,7,8,9,16,17,18,19]);
 const encode=(value,col)=>{
  if(value===null||value===undefined||value==='')return '""';
  if(numeric.has(col)&&typeof value==='number'&&Number.isFinite(value))return String(value).replace('.',',');
  let str=String(value);
  // Evita que una descripción escrita por el usuario se ejecute como fórmula en Excel.
  if(/^[\s]*[=+@]/.test(str)||/^[\s]*-(?!\d)/.test(str))str="'"+str;
  return '"'+str.replace(/"/g,'""')+'"';
 };
 const content='\uFEFFsep=;\r\n'+rows.map(row=>row.map(encode).join(';')).join('\r\n');
 download(content,`vive-el-hoy-movimientos-${today()}.csv`,'text/csv;charset=utf-8');
}
