function manageProduct(kind,id,cmd){let collection={bank:'banks',account:'accounts',card:'cards',loan:'loans',certificate:'certificates'}[kind];if(!collection)return;
let list=db[collection],p=list.find(x=>x.id===id);if(!p)return;
if(kind==='account'&&p.kind==='cash'){toast('Efectivo es una cuenta del sistema permanente: no se elimina ni se archiva. Solo puedes configurar sus saldos iniciales.');return;}
let label=p.name||'Este producto';
if(cmd==='toggle'){
  if(kind==='loan'||kind==='card'){
   if(!p.archived && !confirm(`¿Cancelar «${label}»? Se archivará sin eliminar movimientos, pagos ni historial. Podrás reactivarlo después.`))return;
   p.archived=!p.archived;
   p.cancelledAt=p.archived?new Date().toISOString():null;
   v99Invalidate();persist();render();toast(p.archived?'Producto cancelado y archivado. Puedes reactivarlo.':'Producto reactivado con su historial intacto.');return;
  }
  p.archived=!p.archived;persist();render();toast(p.archived?'Archivado sin borrar el historial.':'Producto reactivado.');return;
 }
  if((kind==='loan'||kind==='card')&&cmd==='delete'){manageProduct(kind,id,'toggle');return;}
let related=kind==='bank'?[...db.accounts,...db.cards,...db.loans,...db.certificates].filter(x=>x.bankId===id).length:
 db.transactions.some(t=>(kind==='account'&&(t.accountId===id||t.toAccountId===id))||(kind==='card'&&t.cardId===id)||(kind==='loan'&&t.loanId===id)||(kind==='certificate'&&t.certificateId===id))||
 (kind==='card'&&((db.statements||[]).some(s=>s.cardId===id)||(db.rewardBalances||[]).some(x=>x.cardId===id)||(db.perkUses||[]).some(x=>x.cardId===id)))||
 (kind==='account'&&db.recurring.some(r=>r.source==='account:'+id))||(kind==='card'&&db.recurring.some(r=>r.source==='card:'+id));
let starting=kind==='account'?Math.abs(num(p.opening)):kind==='card'?(num(p.openingDOP)+num(p.openingUSD)):kind==='loan'?num(p.principal):kind==='certificate'?num(p.principal):0;
if(related||starting){toast('No se puede eliminar sin perder saldos o referencias. Usa Archivar: conserva el historial y puedes verlo desde «Ver archivados».');return}
if(!confirm(`¿Eliminar definitivamente «${label}»? Solo se permite porque no tiene movimientos, saldo inicial ni productos dependientes.`))return;
if(!v30SavePoint('Antes de eliminar producto: '+label))return;db[collection]=list.filter(x=>x.id!==id);if(ui.bankId===id)ui.bankId=null;if(ui.cardId===id)ui.cardId=null;if(ui.accountId===id)ui.accountId=null;if(ui.loanId===id)ui.loanId=null;persist();render();toast('Registro sin historial eliminado.');
}
