function tooltipElement(){if(!_chartTip){_chartTip=document.createElement('div');_chartTip.id='vive-chart-tip';_chartTip.className='vive-chart-tip';_chartTip.setAttribute('role','status');_chartTip.setAttribute('aria-live','off');document.body.appendChild(_chartTip)}return _chartTip}
function positionTip(x,y){const el=tooltipElement();let width=el.offsetWidth||240,height=el.offsetHeight||90;el.style.left=Math.max(10,Math.min(x+16,innerWidth-width-12))+'px';el.style.top=Math.max(10,Math.min(y+16,innerHeight-height-12))+'px'}
function showChartTip(target,x,y){let text=target?.dataset?.chartTip;if(!text){hideChartTip();return}let el=tooltipElement(),parts=text.split('|');el.replaceChildren();let h=document.createElement('strong');h.textContent=parts[0];el.appendChild(h);for(let line of parts.slice(1)){let item=document.createElement('span');item.textContent=line;el.appendChild(item)}el.classList.add('visible');positionTip(x,y)}
function hideChartTip(){_chartTip?.classList.remove('visible')}
document.addEventListener('pointermove',ev=>{let node=ev.target.closest?.('[data-chart-tip]');if(node)showChartTip(node,ev.clientX,ev.clientY);else hideChartTip()},{passive:true});
document.addEventListener('focusin',ev=>{let node=ev.target.closest?.('[data-chart-tip]');if(node){let r=node.getBoundingClientRect();showChartTip(node,r.left+r.width/2,r.top+r.height/2)} });
