 // Mantener colores elegidos en versiones anteriores sin alterar otros datos.
 const pal={original:'#6d69f1',ocean:'#306fdd',emerald:'#087f75',coral:'#bd4f70',plum:'#8b55c6',amber:'#b77c2f'};
 const hex=/^#[0-9a-f]{6}$/i;
 document.body.style.setProperty('--vive-theme-color',choice==='custom'&&hex.test(db.settings.paletteHex||'')?db.settings.paletteHex:(pal[choice]||pal.original));
 const bgChoice=db.settings.backgroundChoice||'original';
 document.body.dataset.viveBg=bgChoice;
 const backgrounds={original:'#d9e7fa',glacier:'#81cacc',sunset:'#e7a6b8'};
 document.body.style.setProperty('--vive-bg-color',bgChoice==='custom'&&hex.test(db.settings.backgroundHex||'')?db.settings.backgroundHex:(backgrounds[bgChoice]||backgrounds.original));
 v250DockGlassApply(db.settings.mobileDockGlassLevel ?? 50);
 document.getElementById('app').innerHTML=main();
  v40Decorate();
