/* V68 — cierre accesible para todos los formularios, incluidos estudios personalizados. */
(function(){
 const root=document.getElementById('modal-root');
 if(!root||typeof MutationObserver==='undefined')return;
 const sync=()=>{const layer=root.querySelector('.modal-layer');if(!layer||layer.querySelector('.v68-mobile-dismiss'))return;
  const btn=document.createElement('button');btn.type='button';btn.className='v68-mobile-dismiss';btn.setAttribute('aria-label','Cerrar formulario');btn.innerHTML='×';
  btn.addEventListener('click',()=>{if(typeof closeModal==='function')closeModal();else root.innerHTML='';});
  layer.appendChild(btn);
 };
 new MutationObserver(sync).observe(root,{childList:true});sync();
})();


/* V139: animación del carrusel Wallet, sin operaciones ni cambios en saldos. */
function v139WalletChooseCard(id){
 const previous=document.querySelector('.v68-wallet-gallery');
 const previousX=previous?previous.scrollLeft:0;
 ui.v68WalletId=id;
 render();
 const wallet=document.querySelector('.v68-wallet');
 const rail=wallet?.querySelector('.v68-wallet-gallery');
 if(!rail)return;
 const card=[...rail.querySelectorAll('.v68-wallet-face[data-id]')].find(x=>x.dataset.id===id);
 const reduced=!!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
 if(wallet && !reduced)wallet.classList.add('v139-wallet-switch');
 // El render recrea el carrusel: recupera primero su posición anterior.
 rail.scrollLeft=previousX;
 // V268: en la Wallet compacta alinear el carrusel antes de disparar eventos
 // de scroll para que las selecciones manuales no se reviertan.
 if(wallet?.classList.contains('v266-wallet') && card){
  const outer=rail.getBoundingClientRect(),inner=card.getBoundingClientRect();
  const dx=inner.left-outer.left-(outer.width-inner.width)/2;
  rail.scrollLeft=Math.max(0,Math.min(rail.scrollWidth-rail.clientWidth,rail.scrollLeft+dx));
 }
 // La tarjeta seleccionada no debe quedar fuera de pantalla ni provocar desplazamiento vertical.
 const focusSelected=()=>{
  if(!rail.isConnected||!card)return;
  const outer=rail.getBoundingClientRect(),inner=card.getBoundingClientRect();
  const dx=inner.left-outer.left-(outer.width-inner.width)/2;
  const target=Math.max(0,Math.min(rail.scrollWidth-rail.clientWidth,rail.scrollLeft+dx));
  if(Math.abs(target-rail.scrollLeft)>2)rail.scrollTo({left:target,behavior:reduced?'instant':'smooth'});
 };
 requestAnimationFrame(focusSelected);
 // Los gestos laterales también actualizan la tarjeta y su detalle al terminar.
 let settleTimer=0;
 const settle=()=>{
  if(!rail.isConnected)return;
  const rect=rail.getBoundingClientRect(),middle=rect.left+rect.width/2;
  let nearest=null,distance=Infinity;
  rail.querySelectorAll('.v68-wallet-face[data-id]').forEach(face=>{
   const b=face.getBoundingClientRect(),d=Math.abs((b.left+b.right)/2-middle);
   if(d<distance){distance=d;nearest=face}
  });
  if(nearest && nearest.dataset.id!==ui.v68WalletId)v139WalletChooseCard(nearest.dataset.id);
 };
 rail.addEventListener('scrollend',settle,{passive:true});
 // Compatibilidad con versiones de Safari que aún no tienen scrollend.
 if(!('onscrollend' in rail))rail.addEventListener('scroll',()=>{
  clearTimeout(settleTimer);settleTimer=setTimeout(settle,170);
 },{passive:true});
}

