 if(db.transactions.some(t=>t.id===id)){toast('El movimiento ya está registrado.');break;}
 const restored=removed[p].tx;
 if(['personal_issue','personal_settlement'].includes(restored.type)&&!personalLoan(restored.personalLoanId)){toast('La relación personal ya no existe. No se puede restaurar un movimiento huérfano.');break;}
 if(restored.type==='personal_issue'&&db.transactions.some(t=>t.type==='personal_issue'&&t.personalLoanId===restored.personalLoanId)){toast('Ya existe una entrega inicial para esta relación.');break;}
