async function f37Enable(){
 if(!f37CanPush())throw Error('Este navegador no permite notificaciones push');
 if(f37IsIOS()&&!f37Standalone())throw Error('En iPhone, primero añade la web a la pantalla de inicio');
 // Solicitar permiso como consecuencia inmediata del toque o clic del usuario.
 const permissionPromise=Notification.permission==='granted'?Promise.resolve('granted'):Notification.requestPermission();
 const permission=await permissionPromise;
 if(permission!=='granted')throw Error('Debes permitir las notificaciones del navegador para continuar');
 const reg=await f37Worker();
 const current=await reg.pushManager.getSubscription();
 const sub=current||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:F37_VAPID_PUBLIC});
 const data=sub.toJSON();if(!data.endpoint||!data.keys?.auth||!data.keys?.p256dh)throw Error('El navegador no devolvió la suscripción completa');
 const {error}=await f33Api.from('push_devices').upsert({user_id:f33User.id,endpoint:data.endpoint,p256dh:data.keys.p256dh,auth:data.keys.auth,device_label:f37DeviceLabel(),last_seen:new Date().toISOString(),enabled:true},{onConflict:'endpoint'});
 if(error)throw error;
 await f37SavePrefs({enabled:true});await f37SyncObligations();await f37Hydrate();
 f37Message='Activado. Recibirás avisos programados después de configurar la función y el cron de Supabase.';
}
async function f37Disable(){
 if(!f37CanPush())throw Error('No hay suscripción disponible');
 const reg=await f37Worker();const sub=await reg.pushManager.getSubscription();
 if(sub){const {error}=await f33Api.from('push_devices').delete().eq('user_id',f33User.id).eq('endpoint',sub.endpoint);if(error)throw error;await sub.unsubscribe();}
 await f37Hydrate();f37Message='Notificaciones desactivadas en este dispositivo.';
}
async function f37Test(){
 if(!f33Active)throw Error('Inicia sesión primero');
 const {data,error}=await f33Api.functions.invoke('push-reminders',{body:{action:'test'}});
 if(error)throw Error(error.message||'No se pudo enviar');
 if(!data?.ok)throw Error(data?.error||'La prueba no se entregó');
 f37Message='Prueba enviada a '+data.delivered+' dispositivo(s). Verifica tus notificaciones.';
}
document.addEventListener('click',async event=>{
 const el=event.target.closest('[data-v37]');if(!el)return;
 const command=el.dataset.v37;if(f37Busy)return;f37Busy=true;f37Message='';f37PanelUpdate();
 try{if(command==='enable')await f37Enable();else if(command==='disable')await f37Disable();else if(command==='test')await f37Test();}
 catch(e){f37Message='No se completó: '+(e.message||String(e));console.warn('Notificaciones:',e);}
 finally{f37Busy=false;f37PanelUpdate();}
});
document.addEventListener('change',async event=>{
 const el=event.target.closest('[data-v37-option]');if(!el||!f37SchemaReady||f37Busy)return;
 const opt=el.dataset.v37Option;f37Busy=true;f37PanelUpdate();
 try{
  if(opt==='private')await f37SavePrefs({private_preview:el.checked});
  else if(opt==='overdue')await f37SavePrefs({overdue_enabled:el.checked});
  else {const set=new Set(f37Prefs.days_before);if(el.checked)set.add(Number(opt));else set.delete(Number(opt));await f37SavePrefs({days_before:[...set].sort((a,b)=>b-a)});}
  f37Message='Preferencias guardadas en Supabase.';
 }catch(e){f37Message='No se pudo guardar: '+(e.message||'');await f37Hydrate();}
 finally{f37Busy=false;f37PanelUpdate();}
});
const f37OldReady=f33Ready;
f33Ready=function(){f37OldReady();
 if(new URLSearchParams(location.search).get('open')==='payments'){ui.page='payments';render();}
 Promise.resolve().then(async()=>{await f37Hydrate();await f37SyncObligations();}).catch(e=>console.warn('Web Push:',e));
};
const f37OldFlush=f33Flush;
f33Flush=async function(){await f37OldFlush();if(f33Active&&!f33Dirty&&!f33Conflict)await f37SyncObligations();};

/* V40 · Contratos recurrentes, instituciones multiformato y fiscalidad versionada.
   Los asientos automáticos son registros internos, NO órdenes a bancos o empleadores.
   Este cliente ejecuta la conciliación al abrir/sincronizar; no sustituye procesos
   server-side ni verifica cargos bancarios reales. */
const V40_BANK_KINDS=new Set(['Banco','Asociación de ahorros y préstamos','Cooperativa','Financiera']);
function v40Ensure(){
 if(!Array.isArray(db.incomeSchedules))db.incomeSchedules=[];
 if(!Array.isArray(db.institutionBenefits))db.institutionBenefits=[];
 if(!Array.isArray(db.fiscalRulesVersions))db.fiscalRulesVersions=[];
 if(!Array.isArray(db.automationEvents))db.automationEvents=[];
 for(const t of db.transactions||[]){if(t.currency==='USD'&&!(num(t.fxRateSnapshot)>0))t.fxRateSnapshot=num(db.settings.fx);}
 /* Auditoría V62: topes TSS vigentes en enero y febrero de 2026, sin reescribir comprobantes ni reglas personalizadas. */
 const seeded2026={taxYear:2026,afpPct:2.87,sfsPct:3.04,exempt:416220,threshold2:624329,threshold3:867123,secondBase:31216,thirdBase:79776,initial:true};
 if(!db.fiscalRulesVersions.length){
  db.fiscalRulesVersions.push({id:uuid(),...seeded2026,effectiveFrom:'2026-01-01',afpCap:433496,sfsCap:216748,createdAt:new Date().toISOString(),source:'TSS previo al 01/02/2026 · DGII 2026'});
  db.fiscalRulesVersions.push({id:uuid(),...seeded2026,effectiveFrom:'2026-02-01',afpCap:464460,sfsCap:232230,createdAt:new Date().toISOString(),source:'TSS desde el 01/02/2026 · DGII 2026'});
 }else{
  const legacy=db.fiscalRulesVersions.find(r=>r.initial===true&&r.taxYear===2026&&r.effectiveFrom==='2026-01-01'&&num(r.afpCap)===464460&&num(r.sfsCap)===232230);
  if(legacy){
   legacy.afpCap=433496;legacy.sfsCap=216748;legacy.source='TSS previo al 01/02/2026 · DGII 2026';
   if(!db.fiscalRulesVersions.some(r=>r.effectiveFrom==='2026-02-01'))db.fiscalRulesVersions.push({id:uuid(),...seeded2026,effectiveFrom:'2026-02-01',afpCap:464460,sfsCap:232230,createdAt:new Date().toISOString(),source:'TSS desde el 01/02/2026 · DGII 2026'});
  }
 }
}
function v40IsFinancial(b){return V40_BANK_KINDS.has(b?.kind||'Banco');}
function v40FinancialOpts(){return [['','Selecciona una institución financiera'],...db.banks.filter(b=>!b.archived&&v40IsFinancial(b)).map(b=>[b.id,b.name])];}
function v40NonbankDetail(b){
 const benefits=db.institutionBenefits.filter(x=>x.institutionId===b.id),schedules=db.incomeSchedules.filter(s=>s.institutionId===b.id),loanList=db.loans.filter(l=>l.bankId===b.id);
 return `<section class="bank-workspace v40-nonbank-detail v176-bank-workspace"><div class="workspace-title"><div class="hstack">${bankLogoMark(b,'institution-logo large')}<div><div class="eyebrow">INSTITUCIÓN NO BANCARIA</div><h2>${sanitize(b.name)}</h2><p>${sanitize(b.kind)}${b.notes?' · '+sanitize(b.notes):''}</p></div></div><div class="hstack v176-bank-actions">${productControls('bank',b.id,b.archived)}<button class="btn ghost sm" data-act="editBank" data-id="${b.id}">Editar institución</button><button class="btn ghost sm" data-act="closeBank">Cerrar</button><button class="btn soft sm" data-v176-bank-detail="1">Detalle ${icon('arrow')}</button></div></div><div class="v40-grid"><div class="v40-tile"><small>BENEFICIOS REGISTRADOS</small><strong>${benefits.length}</strong><p>Servicios y condiciones, sin sumar dinero ficticio.</p></div><div class="v40-tile"><small>FUENTES RECURRENTES</small><strong>${schedules.length}</strong><p>Nóminas e ingresos vinculados a la entidad.</p></div><div class="v40-tile"><small>PRÉSTAMOS VINCULADOS</small><strong>${loanList.length}</strong><p>Solo contratos reales registrados.</p></div></div><div class="v40-head"><h3>Productos y relación institucional</h3><button class="btn sm soft" data-v40-action="addBenefit" data-id="${b.id}">+ Añadir beneficio</button></div><div class="v40-rows">${benefits.length?benefits.map(p=>`<div class="v40-row"><div><strong>${sanitize(p.name)}</strong><small>${sanitize(p.kind)} · ${sanitize(p.notes||'Sin nota')} · ${prettyDate(p.validFrom)}</small></div><span class="v40-pill">${p.monetary?'Valor informativo':'No monetario'}</span></div>`).join(''):'<div class="v40-empty">Registra los beneficios que tienes con esta organización.</div>'}${schedules.map(p=>`<div class="v40-row"><div><strong>${sanitize(p.name)}</strong><small>Ingreso recurrente · ${prettyDate(p.nextDue)}</small></div><button class="btn sm ghost" data-act="navigate" data-id="income">Ir a Ingresos</button></div>`).join('')}</div></section>`;
}
function v40ModeField(o,kind){return formSelect('postingMode','Registro del cobro',[['confirm','Confirmar manualmente antes de afectar el saldo'],['auto','Automático · registrar en vive el hoy al sincronizar']],o.postingMode||'confirm');}
function v40FiscalFor(day){v40Ensure();return db.fiscalRulesVersions.filter(v=>v.effectiveFrom<=day).sort((a,b)=>b.effectiveFrom.localeCompare(a.effectiveFrom))[0]||db.fiscalRulesVersions[0];}
function v40Payroll(schedule,date){
 const grossMonthly=Math.max(0,num(schedule.grossMonthly)),mode=schedule.kind==='formal'?'formal':'informal';
 const f=schedule.frequency==='semi_monthly'?.5:schedule.frequency==='weekly'?12/52:schedule.frequency==='quarterly'?3:schedule.frequency==='annual'?12:1;
 let afp=0,sfs=0,isr=0,rule=null;
  const generalOther=Math.max(0,num(schedule.otherDeduction));
  const companyItems=mode==='formal'?v43NormalizeCompanyDeductions(schedule.companyDeductions||[]):[];
  const companyOther=rnd(companyItems.reduce((total,item)=>total+item.amount,0));
  const other=rnd(generalOther+companyOther);
 if(mode==='formal'){
  rule=v40FiscalFor(date);
  if(schedule.currency!=='DOP')throw Error('La nómina formal se calcula en pesos dominicanos.');
  afp=rnd(Math.min(grossMonthly,num(rule.afpCap))*num(rule.afpPct)/100);
  sfs=rnd(Math.min(grossMonthly,num(rule.sfsCap))*num(rule.sfsPct)/100);
  const netTaxableAnnual=Math.max(0,(grossMonthly-afp-sfs)*12);
  const b1=num(rule.exempt),b2=num(rule.threshold2),b3=num(rule.threshold3);
  const tax=netTaxableAnnual<=b1?0:netTaxableAnnual<=b2?(netTaxableAnnual-b1)*.15:netTaxableAnnual<=b3?num(rule.secondBase)+(netTaxableAnnual-b2)*.20:num(rule.thirdBase)+(netTaxableAnnual-b3)*.25;
  isr=rnd(tax/12);
 }else isr=0;
 const monthNet=Math.max(0,rnd(grossMonthly-afp-sfs-isr-other));
 return {gross:rnd(grossMonthly*f),net:rnd(monthNet*f),afp:rnd(afp*f),sfs:rnd(sfs*f),isr:rnd(isr*f),other:rnd(other*f),generalOther:rnd(generalOther*f),companyOther:rnd(companyOther*f),companyItems:companyItems.map(x=>({...x,amount:rnd(x.amount*f),monthlyAmount:x.amount})),frequency:schedule.frequency,kind:mode,currency:schedule.currency,rateVersion:rule?.id||null,ruleEffectiveFrom:rule?.effectiveFrom||null,ruleTaxYear:rule?.taxYear||null,calculation:'Estimación mensualizada; verifica el comprobante de pago.',staleRule:mode==='formal'&&Number(date.slice(0,4))>Number(rule?.taxYear||0)};
}
function v40NextDate(date,frequency){
 if(frequency==='weekly')return addDays(date,7);
 if(frequency==='quarterly')return plusMonths(date,3);
 if(frequency==='annual')return plusMonths(date,12);
 return plusMonths(date,1);
}
// 15 y último día del mes, sin confundir enero / febrero / meses de 30 días.
function v40IncomeNext(date,frequency){
 if(frequency!=='semi_monthly')return v40NextDate(date,frequency);
 const d=dateObj(date),y=d.getFullYear(),m=d.getMonth()+1,day=d.getDate();
 const end=dateStr(new Date(y,m,0));
 if(day<15)return monthDay(y,m,15);
 if(date<end)return end;
 return monthDay(y,m+1,15);
}
function v40InstitutionOptions(){return [['','Sin institución (opcional)'],...db.banks.filter(b=>!b.archived).map(b=>[b.id,b.name+' · '+b.kind])];}
function v40AccountOptions(currency='DOP'){return db.accounts.filter(a=>a.currency===currency&&!a.archived).map(a=>[a.id,isMobileViewport()?v116AccountLabel(a):a.name+' · '+a.currency+' · '+bankOf(a)]);}
function v40IncomeForm(id){
 v40Ensure();const old=db.incomeSchedules.find(x=>x.id===id)||{};
 const o={name:'',kind:'formal',institutionId:'',accountId:'',currency:'DOP',grossMonthly:0,frequency:'monthly',nextDue:today(),postingMode:'confirm',withholdingPct:0,otherDeduction:0,active:true,note:'',...old};
 const body=`<div class="form-full smart-sub-intro"><span class="smart-kicker">INGRESOS · PROGRAMACIÓN</span><strong>${id?'Modificar ingreso recurrente':'Registrar fuente recurrente'}</strong><small>Nómina formal o ingresos independientes. Se registra el neto y el desglose queda como comprobante.</small></div>
 ${formItem('name','Nombre o concepto',o.name,'text','required maxlength="85" placeholder="Ej. Salario mensual"')}
 ${formSelect('kind','Modalidad',[['formal','Trabajo formal · nómina'],['informal','Actividad independiente / informal']],o.kind)}
 ${formSelect('institutionId','Empresa o institución',v40InstitutionOptions(),o.institutionId)}
 ${formSelect('currency','Moneda',[['DOP','Pesos dominicanos'],['USD','Dólares (solo independiente)']],o.currency)}
 ${formItem('grossMonthly','Ingreso bruto mensual previsto',o.grossMonthly,'number','required min="0.01" step="0.01"')}
 ${formSelect('frequency','Calendario de cobro',[['monthly','Mensual'],['semi_monthly','15 y último día del mes'],['weekly','Semanal'],['quarterly','Trimestral']],o.frequency)}
 ${formItem('nextDue','Próximo ingreso esperado',o.nextDue,'date','required')}
 ${formSelect('accountId','Cuenta que recibe el depósito',[['','Selecciona la cuenta'],...v40AccountOptions(o.currency)],o.accountId,'required')}
 ${formSelect('postingMode','Registrar en cuenta',[['confirm','Confirmar el depósito antes de acreditar'],['auto','Automático · asentar al abrir/sincronizar']],o.postingMode)}
 <details class="form-full smart-fold" open><summary><span class="smart-fold-icon">＋</span><span><strong>Descuentos y retenciones</strong><small>Configurados como valores mensuales</small></span><span class="smart-chevron">⌄</span></summary><div class="smart-fold-grid">
 ${formItem('otherDeduction','Otros descuentos generales (mensuales)',o.otherDeduction,'number','min="0" step="0.01"')}
 ${formItem('withholdingPct','Retención pactada del independiente (%)',o.withholdingPct,'number','min="0" max="100" step="0.01"')}
 ${formSelect('active','Estado',[['true','Activo'],['false','Pausado']],String(o.active))}
 </div></details>
 ${formItem('note','Nota o condiciones',o.note||'','text','maxlength="140"')}
 <p class="form-full v40-help">En trabajo formal se estiman AFP, SFS e ISR a partir de las reglas vigentes en Configuración. Las retenciones reales pueden variar. En trabajo independiente no aplicamos AFP/SFS de nómina automáticamente. Nunca se reescriben depósitos anteriores.</p>`;
 modal(id?'Editar ingreso recurrente':'Nuevo ingreso recurrente',body,'v40IncomeForm',true);
 document.getElementById('v40IncomeForm').dataset.id=id||'';
}
function v40IncomeRow(s){let p;try{p=v40Payroll(s,s.nextDue)}catch(e){p={net:0,staleRule:true}}const auto=s.postingMode==='auto',due=s.nextDue<=today();return `<div class="v40-row"><div><strong>${sanitize(s.name)}</strong><small>${sanitize(s.kind==='formal'?'Nómina formal':'Ingreso independiente')} · ${sanitize(s.frequency==='semi_monthly'?'Quincenal · 15 y último día':s.frequency==='weekly'?'Semanal':s.frequency==='quarterly'?'Trimestral':s.frequency==='annual'?'Anual':'Mensual')} · Próximo ${prettyDate(s.nextDue)}<br/>${sanitize(bank(s.institutionId)?.name||'Sin institución')} · ${sanitize(account(s.accountId)?.name||'Sin cuenta')}${p.staleRule?' · Revisar reglas fiscales del año':''}</small></div><div class="v40-row-actions"><span class="v40-pill ${auto?'good':'manual'}">${auto?'Auto al sincronizar':'Confirmación'}</span><b>${money(p.net,s.currency,2)}</b>${s.active!==false&&!auto?`<button class="btn sm soft" data-v40-action="confirmIncome" data-id="${s.id}">${due?'Confirmar cobro':'Registrar recibido'}</button>`:''}<button class="btn sm ghost" data-v40-action="editIncome" data-id="${s.id}">Editar</button><button class="btn sm ghost" data-v40-action="toggleIncome" data-id="${s.id}">${s.active===false?'Activar':'Pausar'}</button></div></div>`}
function v40IncomeBreakdown(s){let p;try{p=v40Payroll(s,s.nextDue);}catch(e){return '';}const paid=db.transactions.filter(t=>t.incomeScheduleId===s.id).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8);return `<details class="v40-breakdown"><summary>Desglose estimado · bruto, AFP, SFS, ISR y neto</summary><div class="v40-break-grid">${[['Bruto del período',p.gross],['AFP',p.afp],['SFS',p.sfs],['ISR / Retención',p.isr],['Otros descuentos',p.other],['Neto estimado',p.net]].map(([n,v])=>`<div><small>${n}</small><b>${money(v,s.currency,2)}</b></div>`).join('')}</div>${paid.length?`<div class="v40-past"><strong>Depósitos contabilizados</strong>${paid.map(t=>`<p>${prettyDate(t.date)} · ${money(t.amount,t.currency,2)} · ${sanitize(t.postingOrigin||'Registrado')} · ISR de ese recibo: ${money(t.payrollSnapshot?.isr||0,t.currency,2)}</p>`).join('')}</div>`:'<p class="v40-one">Todavía sin depósitos contabilizados.</p>'}</details>`;}
function v40IncomeSection(){
 v40Ensure();const active=db.incomeSchedules.filter(x=>x.active!==false),formal=active.filter(x=>x.kind==='formal'),informal=active.filter(x=>x.kind!=='formal');
 let monthExpected=0;for(const s of active){try{let p=v40Payroll(s,today());let factor=s.frequency==='semi_monthly'?2:s.frequency==='weekly'?52/12:s.frequency==='quarterly'?1/3:s.frequency==='annual'?1/12:1;monthExpected+=fx(p.net*factor,s.currency);}catch(e){}}
 return `<section class="v40-shell" id="v40-income-schedules"><div class="v40-head"><div><h3>Ingresos recurrentes y nómina</h3><p>Tu calendario real de cobros, impuestos estimados y depósitos confirmados.</p></div><button class="btn" data-v40-action="addIncome">+ Programar ingreso</button></div>
 <div class="v40-grid"><div class="v40-tile"><small>FUENTES ACTIVAS</small><strong>${active.length}</strong><p>${formal.length} empleos formales · ${informal.length} fuentes independientes</p></div><div class="v40-tile"><small>NETO MENSUAL ESTIMADO</small><strong>${money(monthExpected)}</strong><p>Proyección RD$ equivalente; no se suma al balance hasta registrar depósito.</p></div><div class="v40-tile"><small>PRÓXIMO INGRESO</small><strong>${active.length?prettyDate(active.slice().sort((a,b)=>a.nextDue.localeCompare(b.nextDue))[0].nextDue):'—'}</strong><p>Confirmación manual o asiento al sincronizar, según cada fuente.</p></div></div>
 <div class="v40-rows">${db.incomeSchedules.length?db.incomeSchedules.map(s=>v40IncomeRow(s)+v40IncomeBreakdown(s)).join(''):'<div class="v40-empty">Todavía no hay fuentes programadas. Agrega tu empleo o una actividad periódica para construir el calendario de ingresos.</div>'}</div><div class="v40-note">El modo automático registra un asiento contable previsto, no verifica un depósito bancario. Los cambios de salario o reglas fiscales solo afectan vencimientos futuros; cada ingreso generado conserva su desglose y tasa de cambio de registro.</div></section>`;
}
function v40IncomeConfirmForm(id){const s=db.incomeSchedules.find(x=>x.id===id);if(!s)return;const p=v40Payroll(s,s.nextDue);
 modal('Confirmar ingreso recibido',`<div class="form-full smart-sub-intro"><span class="smart-kicker">CONCILIACIÓN</span><strong>${sanitize(s.name)}</strong><small>Bruto ${money(p.gross,s.currency,2)} · AFP ${money(p.afp,s.currency,2)} · SFS ${money(p.sfs,s.currency,2)} · ISR ${money(p.isr,s.currency,2)} · otros ${money(p.other,s.currency,2)}</small></div>${formItem('actualNet','Neto depositado según banco',p.net,'number','required min="0.01" step="0.01"')}${formItem('date','Fecha efectiva del depósito',s.nextDue<=today()?s.nextDue:today(),'date','required')}${formItem('note','Comentario (opcional)','','text','maxlength="120"')}<p class="form-full v40-help">Este registro se acreditará a la cuenta seleccionada. No modificará nóminas previas. Puedes ajustar el importe recibido si difiere de la estimación.</p>`,'v40IncomeConfirmForm');
 document.getElementById('v40IncomeConfirmForm').dataset.id=id;
}
function v40IncomePost(s,due,actualNet,actualDate='',note='',mode='auto'){
 const key=`income:${s.id}:${due}`;
 if(db.transactions.some(t=>t.scheduleKey===key))return false;
 const a=account(s.accountId);if(!a||a.currency!==s.currency||!(num(actualNet)>0))throw Error('La cuenta de destino o el neto recibido no es válido.');
 const day=actualDate||due;if(day>today())throw Error('No se pueden acreditar depósitos futuros.');
 const snap=v40Payroll(s,due);
 const tx={id:uuid(),created:new Date().toISOString(),type:'income',date:day,amount:rnd(actualNet),currency:s.currency,accountId:a.id,category:s.kind==='formal'?'Salario y nómina':'Negocios y ventas',subcategory:s.kind==='formal'?'Sueldo recurrente':'Ingreso recurrente',note:(note||s.name).slice(0,180),reviewed:mode!=='auto',incomeScheduleId:s.id,scheduleKey:key,postingOrigin:mode==='auto'?'automático estimado':'confirmado',payrollSnapshot:{...snap,sourceName:s.name,institutionName:bank(s.institutionId)?.name||'',institutionId:s.institutionId||'',accountName:a.name,expectedDate:due,actualNet:rnd(actualNet),actualDate:day,mode},fxRateSnapshot:db.settings.fx};
 db.transactions.push(tx);s.nextDue=v40IncomeNext(due,s.frequency);s.lastPostedAt=new Date().toISOString();s.lastPostedDate=day;return true;
}
