 if(v.kind==='formal'&&companyDeductions.reduce((a,x)=>a+x.amount,0)+num(v.otherDeduction)>=bruto)throw Error('Las deducciones de empresa y generales no pueden consumir todo el salario.');
 const postingMode=v.postingMode==='auto'?'auto':'confirm';
 const entry={id:id||uuid(),name:v.name.trim(),kind:v.kind,institutionId:v.institutionId||'',accountId:a.id,currency:v.currency,grossMonthly:rnd(bruto),frequency:v.frequency,nextDue:v.nextDue,postingMode,otherDeduction:rnd(v.otherDeduction),companyDeductions,withholdingPct:num(v.withholdingPct),active:v.active==='true',note:(v.note||'').slice(0,140)};
 const p=v40Payroll(entry,entry.nextDue);if(p.net<=0)throw Error('Los descuentos exceden el ingreso. Revisa la configuración.');
 if(prev){if(entry.nextDue<prev.nextDue&&db.transactions.some(t=>t.incomeScheduleId===prev.id))throw Error('No retrocedas el próximo cobro de un ingreso con histórico.');const snapshot=Object.fromEntries(Object.keys(entry).filter(k=>!['id','nextDue'].includes(k)).map(k=>[k,prev[k]]));const changed=Object.keys(snapshot).some(k=>String(snapshot[k]??'')!==String(entry[k]??''));const history=Array.isArray(prev.versions)?prev.versions:[];if(changed)history.push({at:new Date().toISOString(),effectiveFrom:today(),previous:snapshot,next:{...entry}});
  entry.autoFrom=postingMode==='auto'&&(prev.postingMode!=='auto')?today():(prev.autoFrom||today());Object.assign(prev,entry,{versions:history,updatedAt:new Date().toISOString()});}
 else {entry.autoFrom=today();db.incomeSchedules.push({...entry,versions:[],createdAt:new Date().toISOString()});}
