 let values=['afpPct','sfsPct','afpCap','sfsCap','exempt','threshold2','threshold3','secondBase','thirdBase'];if(values.some(k=>!Number.isFinite(Number(v[k]))||num(v[k])<0)||num(v.afpPct)>100||num(v.sfsPct)>100||!(num(v.exempt)<num(v.threshold2)&&num(v.threshold2)<num(v.threshold3)))throw Error('Revisa porcentajes, topes y los tres tramos progresivos.');
 const entry={id:uuid(),effectiveFrom:d,taxYear:Number(v.taxYear),source:(v.source||'Regla personalizada').slice(0,120),createdAt:new Date().toISOString()};for(const k of values)entry[k]=num(v[k]);
