const v42OldFiscal=v40FiscalSection;
v40FiscalSection=function(){const out=v42OldFiscal();const cur=v42TaxRule(today());return out.replace('<div class="v40-note">',v42TaxInfo(cur)+'<div class="v40-note">');};
