const v42DecorateOld=v40Decorate;
v40Decorate=function(){v42DecorateOld();if(ui.page==='banks'){const dup=document.getElementById('v40-institution-benefits');if(dup)dup.remove();}};


/* V43 · Deducciones adicionales por empleador: conceptos identificables, no sumados dos veces. */
const V43_EMPLOYER_CONCEPTS=['Seguro médico complementario','Seguro de vida','Préstamo de empleado','Cooperativa','Fondo de ahorro','Plan telefónico','Comedor / alimentación','Cuota sindical / asociación','Otro descuento de empresa'];
function v43NormalizeCompanyDeductions(raw){
 let arr=raw;
 if(typeof raw==='string'){
  try{arr=JSON.parse(raw||'[]');}catch(_){throw Error('Revisa las deducciones de empresa.');}
 }
 if(!Array.isArray(arr)||arr.length>12)throw Error('Puedes registrar hasta 12 conceptos de deducción por empresa.');
 return arr.map(item=>({name:String(item?.name||'').trim().slice(0,75),amount:Number(item?.amount)}))
  .filter(item=>item.name||item.amount)
  .map(item=>{if(!item.name||!Number.isFinite(item.amount)||item.amount<0||item.amount>1e9)throw Error('Cada deducción de empresa debe tener concepto e importe válido.');return {name:item.name,amount:rnd(item.amount)};});
}
function v43DeductionsRow(item={name:'',amount:0}){
 const opts=V43_EMPLOYER_CONCEPTS.map(n=>`<option value="${sanitize(n)}" ${n===item.name?'selected':''}>${sanitize(n)}</option>`).join('');
 const custom=item.name&&!V43_EMPLOYER_CONCEPTS.includes(item.name);
 return `<div class="v43-company-row">
 <label class="v43-concept"><span class="filter-label">Concepto</span><select class="field v43-concept-select" aria-label="Tipo de deducción de empresa"><option value="">Selecciona un concepto</option>${opts}<option value="__custom" ${custom?'selected':''}>Concepto personalizado…</option></select></label>
 <label class="v43-name ${custom?'':'v43-hidden'}"><span class="filter-label">Descripción</span><input class="field v43-custom-name" type="text" maxlength="75" placeholder="Nombre de la deducción" value="${sanitize(custom?item.name:'')}" /></label>
 <label class="v43-money"><span class="filter-label">Importe mensual (RD$)</span><input class="field v43-money-input" type="number" min="0" step="0.01" value="${item.amount||''}" placeholder="0.00" /></label>
 <button type="button" class="btn sm ghost v43-remove" data-v43-remove aria-label="Quitar esta deducción">Quitar</button></div>`;
}
function v43RowsToData(form){
 return [...form.querySelectorAll('.v43-company-row')].map(row=>{
  const sel=row.querySelector('.v43-concept-select');
  const custom=sel?.value==='__custom';
  return {name:custom?row.querySelector('.v43-custom-name')?.value:sel?.value,amount:row.querySelector('.v43-money-input')?.value};
 }).filter(x=>x.name||Number(x.amount)>0);
}
function v43SyncCompany(form){
 if(!form||!form.querySelector('.v43-company-deductions'))return;
 const rows=v43RowsToData(form);
 const hidden=form.elements.companyDeductionsJSON;
 if(hidden)hidden.value=JSON.stringify(rows);
 const total=rows.reduce((n,x)=>n+Math.max(0,Number(x.amount)||0),0);
 const label=form.querySelector('.v43-company-total strong');if(label)label.textContent=money(total,'DOP',2);
 const wrap=form.querySelector('.v43-company-deductions');if(wrap)wrap.hidden=form.elements.kind?.value!=='formal';
}
const v43PreviousIncomeForm=v40IncomeForm;
v40IncomeForm=function(id){
 v43PreviousIncomeForm(id);
 const form=document.getElementById('v40IncomeForm');if(!form)return;
 const original=db.incomeSchedules.find(x=>x.id===id),deductions=v43NormalizeCompanyDeductions(original?.companyDeductions||[]);
 const field=`<section class="v43-company-deductions form-full"><div class="v43-company-title"><div><strong>Otras deducciones de empresa</strong><small>Seguro complementario, préstamos laborales, cooperativa u otros descuentos que realiza tu empleador.</small></div><span>RD$ / mes</span></div>
 <div class="v43-company-rows">${deductions.map(x=>v43DeductionsRow(x)).join('')}</div><button type="button" class="btn sm soft v43-add-deduction" data-v43-add>+ Añadir deducción</button>
 <div class="v43-company-total"><span>Subtotal de deducciones de empresa</span><strong>RD$0.00</strong></div>
 <p class="v43-company-help">Se resta después de AFP, SFS e ISR. No se incluye en la base de cálculo del ISR y no se registra como gasto adicional de la cuenta. Los recibos anteriores permanecen intactos.</p>
 <input type="hidden" name="companyDeductionsJSON" value="[]"></section>`;
 const grid=form.querySelector('.smart-fold-grid');if(grid)grid.insertAdjacentHTML('beforeend',field);else form.insertAdjacentHTML('beforeend',field);
 form.querySelectorAll('.v43-company-row').forEach(row=>{
  const originalItem=deductions.shift();
  if(originalItem){const sel=row.querySelector('.v43-concept-select');sel.value=V43_EMPLOYER_CONCEPTS.includes(originalItem.name)?originalItem.name:'__custom';}
 });
 v43SyncCompany(form);v42IncomePreview(form);
};
document.addEventListener('click',event=>{
 const b=event.target.closest?.('[data-v43-add],[data-v43-remove]');if(!b)return;
 const form=b.closest('#v40IncomeForm');if(!form)return;
 event.preventDefault();event.stopImmediatePropagation();
 if(b.hasAttribute('data-v43-add')){
  const holder=form.querySelector('.v43-company-rows');if(holder.children.length>=12){toast('Máximo 12 descuentos de empresa.');return;}
  holder.insertAdjacentHTML('beforeend',v43DeductionsRow());holder.lastElementChild.querySelector('select')?.focus();
 }else b.closest('.v43-company-row')?.remove();
 v43SyncCompany(form);v42IncomePreview(form);
},true);
document.addEventListener('input',event=>{
 if(!event.target.closest?.('.v43-company-deductions'))return;
 const form=event.target.closest('#v40IncomeForm');if(!form)return;
 v43SyncCompany(form);v42IncomePreview(form);
},true);
document.addEventListener('change',event=>{
 const form=event.target.closest?.('#v40IncomeForm');if(!form)return;
 if(event.target.classList?.contains('v43-concept-select')){
  const row=event.target.closest('.v43-company-row');if(row)row.querySelector('.v43-name').classList.toggle('v43-hidden',event.target.value!=='__custom');
 }
 v43SyncCompany(form);v42IncomePreview(form);
},true);

/* V45: Diseño responsivo y funciones de análisis financiero y programación.
   Se amplía la V44 sin modificar movimientos previos ni las credenciales de Supabase. */
function v45FreqName(f){return ({semi_monthly:'Quincenal',monthly:'Mensual',annual:'Anual',weekly:'Semanal',quarterly:'Trimestral'})[f]||'Mensual';}
function v45MonthFactor(f){return ({semi_monthly:2,monthly:1,annual:1/12,weekly:52/12,quarterly:1/3})[f]||1;}
function v45GrossMonthly(value,basis,f){const x=Math.max(0,Number(value)||0);return basis==='annual'?x/12:basis==='per_payment'?x*v45MonthFactor(f):x;}
function v45MonthDay(y,m,day){const end=new Date(y,m,0).getDate(),safe=Math.max(1,Math.min(Number(day)||1,end));return `${y}-${String(m).padStart(2,'0')}-${String(safe).padStart(2,'0')}`;}
function v45NextPayDate(due,s){
 if(s.frequency==='semi_monthly'&&Array.isArray(s.payDays)&&s.payDays.length===2){
  const y=Number(due.slice(0,4)),m=Number(due.slice(5,7));
  for(let offset=0;offset<16;offset++){
   const month=m+offset,year=y+Math.floor((month-1)/12),mo=(month-1)%12+1;
   const choices=[...new Set(s.payDays.map(d=>v45MonthDay(year,mo,d)))].sort();
   const next=choices.find(d=>d>due);if(next)return next;
  }
 }
 if(s.frequency==='monthly'&&Number(s.payDay)>0){
  const y=Number(due.slice(0,4)),m=Number(due.slice(5,7))+1;
  const year=y+Math.floor((m-1)/12),month=(m-1)%12+1;
  return v45MonthDay(year,month,s.payDay);
 }
 return v40IncomeNext(due,s.frequency);
}
const v45PreviousPayroll=v40Payroll;
// Annual payments represent twelve months of a configured monthly gross salary.
const v45PreviousIncomePost=v40IncomePost;
v40IncomePost=function(s,due,net,date,note,mode){
 const completed=v45PreviousIncomePost(s,due,net,date,note,mode);
 if(completed){s.nextDue=v45NextPayDate(due,s);}
 return completed;
};
const v45PrevDeductionNormalizer=v43NormalizeCompanyDeductions;
v43NormalizeCompanyDeductions=function(items){
 let source=items;
 if(typeof source==='string'){
  try{source=JSON.parse(source||'[]')}catch(_){throw Error('Las deducciones deben tener un formato válido.')}
 }
 const clean=v45PrevDeductionNormalizer(source);
 return clean.map((x,i)=>({...x,category:String(source?.find?.(o=>o?.name===x.name&&Math.abs(Number(o?.amount)-x.amount)<.001)?.category||'Otros gastos').slice(0,65)}));
};
const v45PrevDeductionRow=v43DeductionsRow;
v43DeductionsRow=function(item={name:'',amount:0}){
 const opts=[...new Set(['Otros gastos','Salud','Deudas e intereses','Impuestos y comisiones','Suscripciones','Vivienda','Transporte','Alimentación','Educación','Negocio',...(Array.isArray(EXP)?EXP:[])])];
 const select=`<label class="v45-company-category"><span class="filter-label">Categoría de gastos</span><select class="field v45-company-category-select" aria-label="Categoría contable de la deducción">${opts.map(cat=>`<option value="${sanitize(cat)}" ${cat===(item.category||'Otros gastos')?'selected':''}>${sanitize(cat)}</option>`).join('')}</select></label>`;
 return v45PrevDeductionRow(item).replace('<button type="button" class="btn sm ghost v43-remove"',select+'<button type="button" class="btn sm ghost v43-remove"');
};
v43RowsToData=function(form){return [...form.querySelectorAll('.v43-company-row')].map(row=>{
 const sel=row.querySelector('.v43-concept-select');
 return {name:sel?.value==='__custom'?row.querySelector('.v43-custom-name')?.value:sel?.value,amount:row.querySelector('.v43-money-input')?.value,category:row.querySelector('.v45-company-category-select')?.value||'Otros gastos'};
}).filter(x=>x.name||Number(x.amount)>0)};
function v45UpdateIncomeFields(f){
 if(!f||!f.elements?.frequency)return;
 const freq=f.elements.frequency.value,kind=f.elements.kind?.value;
 const days=f.querySelector('.v45-payday-twins');if(days)days.hidden=freq!=='semi_monthly';
 const month=f.querySelector('.v45-monthly-day');if(month)month.hidden=freq!=='monthly';
 const basis=f.elements.salaryBasis?.value||'monthly';
 const lab=f.querySelector('.v45-base-helper');
 if(lab)lab.textContent=basis==='annual'?'Introduce el bruto de TODO el año. Calcularemos la base mensual.':basis==='per_payment'?'Introduce el bruto que corresponde a CADA pago.':'Introduce el bruto MENSUAL, aunque el pago sea quincenal o anual.';
 const withhold=f.elements.withholdingPct;
 if(withhold){withhold.value='0';const holder=withhold.closest('label');if(holder)holder.hidden=true;}
 const org=f.elements.institutionId; if(org){const label=org.closest('label');if(label){const cap=label.querySelector('.filter-label');if(cap)cap.textContent='Institución vinculada (opcional)';}}
 f.querySelectorAll('[data-v45-freq]').forEach(b=>b.classList.toggle('selected',b.dataset.v45Freq===freq));
 f.querySelectorAll('[data-v45-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.v45Mode===f.elements.postingMode?.value));
 const p=f.querySelector('.v45-calendar-explain');if(p)p.textContent='Primer cobro: '+(f.elements.nextDue?.value||'elige una fecha')+' · '+v45FreqName(freq)+' · '+(f.elements.postingMode?.value==='auto'?'asiento automático al sincronizar':'confirmación antes de ingresar al balance')+'.';
}
const v45PrevIncomeForm=v40IncomeForm;
v40IncomeForm=function(id){
 v45PrevIncomeForm(id);
 const f=document.getElementById('v40IncomeForm');if(!f)return;
 const old=db.incomeSchedules.find(s=>s.id===id)||{},selected=old.salaryBasis||'monthly';
 const frequency=f.elements.frequency;
 if(frequency&&!frequency.querySelector('[value="annual"]'))frequency.insertAdjacentHTML('beforeend','<option value="annual">Anual</option>');
 if(frequency&&old.frequency==='annual')frequency.value='annual';
 const gross=f.elements.grossMonthly;
 if(gross){gross.value=Number.isFinite(Number(old.salaryInput))?old.salaryInput:old.grossMonthly||0;const lab=gross.closest('label')?.querySelector('.filter-label');if(lab)lab.textContent='Salario / ingreso bruto';}
 const block=`<section class="v45-schedule-setup form-full"><div class="v45-section-title"><strong>Programación de cobros</strong><small>Define cómo cobras y los días reales. La institución es opcional.</small></div>
 <div class="v45-schedule-pills" role="group" aria-label="Frecuencia del ingreso">${['semi_monthly','monthly','annual','weekly','quarterly'].map(k=>`<button type="button" data-v45-freq="${k}" class="${(old.frequency||'monthly')===k?'selected':''}">${v45FreqName(k)}</button>`).join('')}</div>
 <label class="v45-basis-label"><span>¿Cómo introducirás el importe?</span><select class="field" name="salaryBasis"><option value="monthly" ${selected==='monthly'?'selected':''}>Bruto mensual</option><option value="per_payment" ${selected==='per_payment'?'selected':''}>Bruto por cada pago</option><option value="annual" ${selected==='annual'?'selected':''}>Bruto anual</option></select></label>
 <p class="v45-base-helper"></p>
 <div class="v45-payday-twins"><label><span>Primer día de cobro</span><input name="payDayA" type="number" class="field" min="1" max="31" value="${old.payDays?.[0]||15}"></label><label><span>Segundo día de cobro</span><input name="payDayB" type="number" class="field" min="1" max="31" value="${old.payDays?.[1]||31}"></label><small>31 representa el último día del mes cuando el mes tiene menos días.</small></div>
 <div class="v45-monthly-day"><label><span>Día habitual de cobro</span><input name="payDay" type="number" class="field" min="1" max="31" value="${old.payDay||Number((old.nextDue||today()).slice(-2))}"></label></div>
 <div class="v45-schedule-pills" role="group" aria-label="Cómo registrar el cobro"><button type="button" data-v45-mode="confirm">Confirmar depósito</button><button type="button" data-v45-mode="auto">Automático al sincronizar</button></div><p class="v45-calendar-explain"></p>
 <p class="v45-note">Un asiento automático registra un depósito estimado en vive el hoy. No consulta ni ejecuta movimientos en el banco.</p></section>`;
 const top=f.querySelector('.smart-sub-intro');if(top)top.insertAdjacentHTML('afterend',block);else f.insertAdjacentHTML('afterbegin',block);
 const general=f.elements.otherDeduction;
 if(general){general.closest('label')?.insertAdjacentHTML('afterend',`<label class="v45-general-category"><span class="filter-label">Categoría de gasto para descuento general</span><select class="field" name="generalDeductionCategory">${['Otros gastos','Deudas e intereses','Salud','Impuestos y comisiones','Negocio'].map(x=>`<option value="${x}" ${x===(old.generalDeductionCategory||'Otros gastos')?'selected':''}>${x}</option>`).join('')}</select></label>`);}
 v45UpdateIncomeFields(f);v42IncomePreview(f);
};
const v45OldSaveIncome=v40SaveIncome;
v40SaveIncome=function(form){
 const basis=form.elements.salaryBasis?.value||'monthly',raw=Number(form.elements.grossMonthly?.value),freq=form.elements.frequency?.value||'monthly';
 const monthly=v45GrossMonthly(raw,basis,freq);
 if(!(monthly>0)||!Number.isFinite(monthly))throw Error('Introduce un salario válido.');
 const dayA=Number(form.elements.payDayA?.value||15),dayB=Number(form.elements.payDayB?.value||31),payDay=Number(form.elements.payDay?.value||15);
 if([dayA,dayB,payDay].some(x=>x<1||x>31||!Number.isInteger(x)))throw Error('Los días de pago deben estar entre 1 y 31.');
 if(freq==='semi_monthly'&&dayA===dayB)throw Error('Elige dos días distintos para el cobro quincenal.');
 form.elements.grossMonthly.value=monthly.toFixed(2);
 if(form.elements.withholdingPct)form.elements.withholdingPct.value='0';
 const existingId=form.dataset.id;
 v45OldSaveIncome(form);
 const item=db.incomeSchedules.find(x=>x.id===(existingId||db.incomeSchedules.at(-1)?.id));
 if(item){item.salaryBasis=basis;item.salaryInput=raw;item.payDays=[dayA,dayB].sort((a,b)=>a-b);item.payDay=payDay;item.generalDeductionCategory=form.elements.generalDeductionCategory?.value||'Otros gastos';persist();}
};
const v45OldIncomePreview=v42IncomePreview;
v42IncomePreview=function(form){
 if(!form?.elements?.grossMonthly)return v45OldIncomePreview(form);
 const el=form.elements.grossMonthly,original=el.value;
 const basis=form.elements.salaryBasis?.value||'monthly',freq=form.elements.frequency?.value||'monthly';
 el.value=v45GrossMonthly(original,basis,freq);
 try{return v45OldIncomePreview(form)}finally{el.value=original}
};
