function v45SafeIconData(src){return typeof src==='string'&&src.length<185000&&/^data:image\/(?:png|webp|jpeg);base64,[a-zA-Z0-9+/=]+$/.test(src)?src:'';}
function v45SubIcon(s,small=''){
 const custom=v45SafeIconData(s?.iconDataUrl);
 return custom?`<span class="v41-service-mark v45-custom-mark ${small==='tiny'?'is-tiny':small?'is-small':''}"><img src="${custom}" alt="" loading="lazy" /></span>`:v41ServiceIcon(s?.iconId||v41GuessIcon(s?.name||''),small);
}
const v45PreviousRecurringForm=recurringForm;
recurringForm=function(id){
 v45PreviousRecurringForm(id);
 const f=document.getElementById('recurringForm');if(!f)return;
 const r=db.recurring.find(x=>x.id===id)||{},selected=v45SafeIconData(r.iconDataUrl)||'';
 const picker=f.querySelector('.v41-icon-selector');if(picker){
  const extra=V45_EXTRA_SERVICES.filter(o=>!picker.querySelector(`.v41-service-choice[data-id="${o.id}"]`)).map(o=>`<button type="button" class="v41-service-choice" data-act="v41PickServiceIcon" data-id="${o.id}" data-icon-label="${sanitize(o.label.toLowerCase())}" aria-pressed="${o.id===r.iconId}">${v41ServiceIcon(o.id)}<span class="v41-choice-label">${sanitize(o.label)}</span></button>`).join('');
  picker.querySelector('.v41-service-grid')?.insertAdjacentHTML('beforeend',extra);
  picker.insertAdjacentHTML('beforeend',`<div class="v45-upload-panel"><label class="v45-upload-button"><span>＋ Subir mi propio ícono</span><input type="file" name="iconUpload" accept="image/png,image/webp,image/jpeg" /></label><input type="hidden" name="serviceIconData" value="${selected}"><span class="v45-upload-hint">PNG, JPG o WebP. Se optimiza a 128 × 128 y se guarda con la suscripción.</span><span class="v45-upload-preview">${selected?`<img alt="Ícono personalizado" src="${selected}" />`:''}</span><button type="button" class="btn sm ghost" data-v45-remove-icon ${selected?'':'hidden'}>Quitar imagen propia</button></div>`);
  if(selected)picker.querySelector('#v41IconPreview').innerHTML=v45SubIcon(r)+'<small>Personalizado</small>';
 }
 const frequent=f.elements.frequency;
 const recurrence=`<section class="v45-schedule-setup form-full"><div class="v45-section-title"><strong>Programar el pago</strong><small>Controla cuánto, cuándo y cómo registrar cada vencimiento.</small></div><div class="v45-schedule-pills">${['monthly','weekly','quarterly','annual'].map(k=>`<button type="button" data-v45-payfreq="${k}">${v45FreqName(k)}</button>`).join('')}</div><p class="v45-note">Selecciona el próximo vencimiento en el campo de fecha. El cargo automático es contable y nunca ordena pagos al proveedor.</p></section>`;
 const intro=f.querySelector('.smart-sub-intro');if(intro)intro.insertAdjacentHTML('afterend',recurrence);
 v45RefreshRecurringPills(f);
};
function v45RefreshRecurringPills(f){f.querySelectorAll('[data-v45-payfreq]').forEach(b=>b.classList.toggle('selected',b.dataset.v45Payfreq===f.elements.frequency?.value));}
document.addEventListener('click',event=>{
 const b=event.target.closest?.('[data-v45-payfreq],[data-v45-remove-icon]');if(!b)return;
 const f=b.closest('#recurringForm');if(!f)return;
 event.preventDefault();event.stopImmediatePropagation();
 if(b.dataset.v45Payfreq){f.elements.frequency.value=b.dataset.v45Payfreq;v45RefreshRecurringPills(f);}
 if(b.hasAttribute('data-v45-remove-icon')){
  f.elements.serviceIconData.value='';f.querySelector('.v45-upload-preview').innerHTML='';b.hidden=true;
  const id=f.elements.serviceIcon?.value||'general';f.querySelector('#v41IconPreview').innerHTML=v41ServiceIcon(id)+'<small>Elegido</small>';
 }
},true);
document.addEventListener('click',event=>{
 const b=event.target.closest?.('[data-act="v41PickServiceIcon"]');if(!b)return;
 const f=b.closest('#recurringForm');if(!f)return;
 f.elements.serviceIconData.value='';f.querySelector('.v45-upload-preview').innerHTML='';const x=f.querySelector('[data-v45-remove-icon]');if(x)x.hidden=true;
},true);
document.addEventListener('change',event=>{
 const file=event.target;if(file.matches?.('#recurringForm [name="frequency"]'))v45RefreshRecurringPills(file.form);
 if(!file.matches?.('#recurringForm input[name="iconUpload"]'))return;
 const f=file.form,blob=file.files?.[0];if(!f||!blob)return;
 if(!blob.type.match(/^image\/(png|jpeg|webp)$/)||blob.size>5*1024*1024){toast('Usa PNG, JPG o WebP de hasta 5 MB.');file.value='';return;}
 const img=new Image(),url=URL.createObjectURL(blob);
 img.onload=()=>{
  try{const canvas=document.createElement('canvas');canvas.width=128;canvas.height=128;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,128,128);
   const z=Math.min(128/img.width,128/img.height);ctx.drawImage(img,(128-img.width*z)/2,(128-img.height*z)/2,img.width*z,img.height*z);
   let data=canvas.toDataURL('image/webp',.78);if(!v45SafeIconData(data))data=canvas.toDataURL('image/png');if(!v45SafeIconData(data))throw Error('Ícono demasiado grande: utiliza una imagen simple.');
   if(!document.contains(f))return;f.elements.serviceIconData.value=data;
   f.querySelector('.v45-upload-preview').innerHTML=`<img alt="Vista previa de ícono" src="${data}">`;
   f.querySelector('#v41IconPreview').innerHTML=`<span class="v41-service-mark v45-custom-mark"><img alt="" src="${data}"></span><small>Personalizado</small>`;
   const remove=f.querySelector('[data-v45-remove-icon]');if(remove)remove.hidden=false;
   toast('Ícono optimizado y listo para guardar con la suscripción.');
  }catch(e){toast(String(e.message||e))}finally{URL.revokeObjectURL(url)};
 };
 img.onerror=()=>{URL.revokeObjectURL(url);toast('No se pudo leer la imagen seleccionada.')};img.src=url;
},true);

// Indicadores y gráficos: fuentes reales almacenadas en el documento; sin datos de demostración.
function v45TrendSvg(values,{height=136,color='#f28b24',shade=true}={}){
 const list=values.map(x=>Number(x)||0),w=600,h=height,p=16,min=Math.min(...list,0),max=Math.max(...list,1),range=Math.max(1,max-min);
 const xy=list.map((v,i)=>[(p+(w-p*2)*i/Math.max(1,list.length-1)),(h-p-((v-min)/range)*(h-2*p))]);
 const line=xy.map(([x,y],i)=>`${i?'L':'M'} ${x.toFixed(1)} ${y.toFixed(1)}`).join(' ');
 const area=`${line} L ${xy.at(-1)?.[0]||p} ${h-p} L ${xy[0]?.[0]||p} ${h-p} Z`;
 return `<svg class="v45-spark" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img" aria-label="Evolución por períodos"><path d="${area}" fill="${color}" opacity="${shade?'.10':'0'}"/><path d="${line}" fill="none" stroke="${color}" stroke-width="4" stroke-linejoin="round" stroke-linecap="round"/>${xy.length<16?xy.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4" fill="white" stroke="${color}" stroke-width="2.5"/>`).join(''):''}</svg>`;
}
function v45LastMonths(n=12){const date=dateObj((ui.month||today().slice(0,7))+'-01');return Array.from({length:n},(_,i)=>{const d=new Date(date.getFullYear(),date.getMonth()-(n-1-i),1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`});}
function v45TotalsSeries(months){return months.map(m=>monthlyTotals(Number(m.slice(0,4)),Number(m.slice(5,7))))}
function v45ApproxWorthOn(ym){const d=new Date(Number(ym.slice(0,4)),Number(ym.slice(5,7)),0);const day=dateStr(d);
 const liquid=db.accounts.reduce((sum,a)=>sum+fx(getAccountBalance(a,day),a.currency),0);
 const currentNet=totalLiquid()+totalCertificates()+personalTotals().receivable-totalCardDebt()-totalLoanDebt()-personalTotals().payable;
 const otherAtCurrent=currentNet-totalLiquid();return rnd(liquid+otherAtCurrent);
}
function v45HomeCharts(isMobile=false){
 const months=v45LastMonths(isMobile?6:12),rows=v45TotalsSeries(months),m=rows.at(-1)||{income:0,expense:0,net:0},net=rows.map(x=>x.net),wealth=months.map(v45ApproxWorthOn);
 const pill=(name,n,c,series)=>`<div class="v45-mini-stat"><span>${name}</span><strong>${money(n)}</strong>${v45TrendSvg(series,{height:70,color:c})}</div>`;
 return `<section class="v45-home" aria-label="Evolución financiera real"><div class="v45-block-head"><div><span class="v45-kicker">TU EVOLUCIÓN</span><h3>Ingresos, gastos y neto</h3><p>Movimientos registrados · ${months[0]} a ${months.at(-1)}</p></div></div><div class="v45-mini-stats">${pill('Ingresos',m.income,'#20a47c',rows.map(r=>r.income))}${pill('Gastos',m.expense,'#e77a70',rows.map(r=>r.expense))}${pill('Neto',m.net,'#387ad6',net)}</div>
 <div class="v45-report-grid"><article class="v45-chart-card"><div><h4>Flujo de caja por mes</h4><small>Ingresos en verde · Gastos en rojo · Neto en azul</small></div><div class="v45-multi-sparklines"><div class="v45-multi-income">${v45TrendSvg(rows.map(r=>r.income),{color:'#21a585',height:170,shade:false})}</div><div class="v45-multi-expense">${v45TrendSvg(rows.map(r=>r.expense),{color:'#e97b73',height:170,shade:false})}</div><div class="v45-multi-net">${v45TrendSvg(net,{color:'#3b7bd0',height:170,shade:false})}</div></div><div class="v45-ticks">${months.map(x=>`<span>${x.slice(5)}</span>`).join('')}</div></article>
 <article class="v45-chart-card v45-worth"><div><h4>Evolución del patrimonio</h4><small>Estimación histórica de liquidez más otros activos y obligaciones a valor actual</small></div><strong>${money(wealth.at(-1)||0)}</strong>${v45TrendSvg(wealth,{color:'#f28b24',height:174})}<div class="v45-ticks">${months.map(x=>`<span>${x.slice(5)}</span>`).join('')}</div><p>Gráfico orientativo: no supone que las deudas y los activos no bancarios hayan tenido el mismo valor histórico.</p></article></div></section>`;
}
