 form.elements.principal.closest('label').querySelector('.filter-label').textContent='Capital original del contrato';
 {const termLabel=form.elements.termCount?.closest('label')?.querySelector('.filter-label')||form.elements.months.closest('label')?.querySelector('.filter-label');if(termLabel)termLabel.textContent='Duración del préstamo';}
 if(form.elements.firstDue?.closest('label')?.querySelector('.filter-label'))form.elements.firstDue.closest('label').querySelector('.filter-label').textContent='Fecha de la primera cuota pagada';
 form.querySelector('.v83-opening-fields').hidden=!isExisting;form.querySelector('.v83-opening-preview').hidden=!isExisting;
