 if(form.elements.loanOpeningMode?.value==='existing'){
  const d=form.elements.openingBalanceDate?.value;
  if(!d||d>today()||form.elements.firstDue.value>today()||form.elements.firstDue.value<form.elements.originationDate.value){ev.preventDefault();ev.stopImmediatePropagation();showError('Indica la primera cuota pagada y la última cuota pagada; ambas deben estar entre el inicio y hoy.');}
 }
