/* V86 — Wizard narrativo: contrato y protección → capital y calendario → resumen final.
   Las nuevas cuotas se activan desde una fecha y no generan ni editan pagos históricos. */
function v86InstallmentForDate(l,due){
 const base=fullOriginalLoan(l).installment;
 const hist=Array.isArray(l?.installmentHistory)?l.installmentHistory.slice().filter(x=>x&&/^\d{4}-\d{2}-\d{2}$/.test(String(x.effectiveFrom||''))).sort((a,b)=>a.effectiveFrom.localeCompare(b.effectiveFrom)):[];
 if(!hist.length){const start=l?.installmentEffectiveFrom||l?.firstDue||'0000-00-00';return due<start?base:(num(l?.currentInstallment)>0?num(l.currentInstallment):base)}
 let chosen=base;
 for(const row of hist){if(row.effectiveFrom>due)break;chosen=num(row.amount)>0?num(row.amount):base}
 return rnd(chosen);
}
/* V87 — Préstamos: contrato primero, seguro visible, saldo luego, revisión última. */
/* V100: el usuario no introduce una segunda fecha de primera cuota.
   Se conserva la fecha original al editar, y en altas se estima el primer
   vencimiento desde la fecha de inicio. Para quincenas, regla 15 y 30
   (último día cuando el mes es más corto). */
function v100FirstDue(start,frequency){
 const d=/^\d{4}-\d{2}-\d{2}$/.test(String(start||''))?start:today();
 const y=Number(d.slice(0,4)),m=Number(d.slice(5,7)),day=Number(d.slice(8,10));
 if(frequency==='semi_monthly'){
  if(day<=15)return monthDay(y,m,15);
  const last=new Date(y,m,0).getDate();
  if(day<last)return monthDay(y,m,Math.min(30,last));
  return monthDay(y,m+1,15);
 }
 return plusMonths(d,1);
}
