function v71SearchView(query){
 const target=document.getElementById('v71-search-results');if(!target)return;
 const q=v71SearchNormalize(query);const data=v149SearchIndex.length?v149SearchIndex:v71SearchEntries();let matches=[];
 if(q){const terms=q.split(/\s+/).filter(Boolean);matches=data.filter(x=>{const hay=x._v150Hay??v71SearchNormalize([x.title,x.sub,x.meta].join(' '));return terms.every(t=>hay.includes(t))}).sort((a,b)=>{const score=x=>(x.kind==='section'?5:0)+((x._v150Title??v71SearchNormalize(x.title)).startsWith(q)?9:0)+((x._v150Title??v71SearchNormalize(x.title))===q?20:0);return score(b)-score(a)}).slice(0,80)}
 else{
  const recent=v149SearchRecent.map(r=>data.find(x=>x.kind===r.kind&&x.id===r.id&&x.page===r.page)).filter(Boolean);
  const suggested=['overview','cards','payments','recurring','register','advanced','accounts','income'].map(page=>data.find(x=>x.kind==='section'&&x.page===page)).filter(Boolean);
  matches=[...recent,...suggested.filter(x=>!recent.includes(x))].slice(0,12);
 }
 window.v71VisibleSearchResults=matches;v149SearchSelected=0;
 if(!matches.length){document.getElementById('v71-search-input')?.removeAttribute('aria-activedescendant');target.innerHTML=`<div class="v149-spotlight-empty">${icon('search')}<b>Sin resultados</b><span>Prueba por nombre de banco, categoría, servicio, tarjeta o movimiento.</span></div>`;return}
 const groups=new Map();matches.forEach((x,i)=>{const group=x.kind==='section'?'section':x.group||x.kind;if(!groups.has(group))groups.set(group,[]);groups.get(group).push({x,i})});
 let markup='';for(const [key,entries] of groups){markup+=`<div class="v71-search-section">${!q&&key==='section'?'Accesos recomendados':key==='section'?'Módulos':(V149_SEARCH_LABELS[key]||'Resultados')}</div><div role="listbox" aria-label="${V149_SEARCH_LABELS[key]||'Resultados'}">${entries.map(({x,i})=>v149SearchResultMarkup(x,i)).join('')}</div>`}
 target.innerHTML=markup;const input=document.getElementById('v71-search-input');if(input)input.setAttribute('aria-activedescendant','v149-result-0');
}
