function v71SearchPick(entry){
 if(!entry)return;
 v149SearchRecent=[{kind:entry.kind,id:entry.id,page:entry.page},...v149SearchRecent.filter(x=>!(x.kind===entry.kind&&x.id===entry.id&&x.page===entry.page))].slice(0,5);
 v71SearchClose(false);
 ui.page=entry.page;
 if(entry.kind==='bank')ui.bankId=entry.id;
 if(entry.kind==='account')ui.accountId=entry.id;
 if(entry.kind==='card')ui.cardId=entry.id;
 if(entry.kind==='loan')ui.loanId=entry.id;
 if(entry.kind==='transaction'){ui.movementTab='all';ui.txPeriod='all';ui.search=entry.title||'';ui.ledgerSearch=entry.title||'';}
 render();window.scrollTo({top:0,behavior:'instant'});
 if(entry.kind==='section')return;
 setTimeout(()=>{
  let target;
  if(entry.kind==='recurring')target=[...document.querySelectorAll('[data-v149-rec-id]')].find(x=>x.dataset.v149RecId===entry.id);
  else if(entry.kind==='card')target=document.querySelector('.card-detail')||document.querySelector('.cards-grid');
  else if(entry.kind==='account')target=document.querySelector('.account-breakdown-panel')||document.querySelector('.panel.section');
  else if(entry.kind==='loan')target=document.querySelector('.loan-detail')||document.querySelector('.loans-world');
  else if(entry.kind==='transaction')target=document.querySelector('#ledger-world');
  else target=document.querySelector('#page');
  target?.scrollIntoView({block:'start',behavior:'smooth'});
 },110);
}
