/* V260 · Pagar servicio: fast visual choices, original transaction engine. */
function v260EnhanceServiceWizard(f){
 if(!f||f.dataset.mode!=='service'||f.querySelector('.v260-preset-block'))return;
 const first=f.querySelector('.studio-step[data-step="1"] .studio-fields');
 const second=f.querySelector('.studio-step[data-step="2"] .studio-fields');
 const sel=f.elements.servicePreset, source=f.elements.paymentSource;
 if(!first||!second||!sel||!source)return;
 const presetLabel=sel.closest('label');
 const quick=[['electricity','Luz','bolt2'],['water','Agua','droplet2'],['internet','Internet','wifi2'],['mobile','Teléfono','smartphone'],['streaming','Streaming','play'],['other','Otro','receipt']].filter(([k])=>SERVICE_PRESETS[k]);
 const group=document.createElement('section');group.className='v260-preset-block';
 group.innerHTML=`<div class="v260-wizard-eyebrow">01 · ¿Qué vas a pagar?</div><div class="v260-wizard-presets" role="group" aria-label="Servicios frecuentes">${quick.map(([key,label,ico])=>`<button type="button" class="v260-preset" data-v260-preset="${key}" aria-pressed="false"><span class="v260-preset-icon">${icon(ico)}</span><strong>${label}</strong></button>`).join('')}</div><div class="v260-selected-service" aria-live="polite"></div>`;
 first.insertBefore(group,presetLabel);
 // The original dropdown remains accessible inside a compact disclosure, for less-common services.
 const more=document.createElement('details');more.className='v260-service-more';more.innerHTML='<summary>Otros servicios y clasificación <span>⌄</span></summary>';
 first.insertBefore(more,presetLabel);more.appendChild(presetLabel);
 const amountLabel=f.elements.amount?.closest('label');
 if(amountLabel){amountLabel.classList.add('v260-service-amount');const label=amountLabel.querySelector('.filter-label');if(label)label.textContent='Importe del servicio';}
 const sourceLabel=source.closest('label');
 if(sourceLabel){const methods=document.createElement('section');methods.className='v260-payment-methods';methods.innerHTML=`<div class="v260-wizard-eyebrow">02 · ¿Desde dónde se paga?</div><div class="v260-method-grid" role="group" aria-label="Origen del pago">${[...source.options].map(x=>`<button type="button" data-v260-source="${sanitize(x.value)}" aria-pressed="false">${icon(x.value==='card'?'card':'wallet')}<span>${x.value==='card'?'Tarjeta de crédito':'Cuenta o efectivo'}</span></button>`).join('')}</div>`;
 second.insertBefore(methods,sourceLabel);sourceLabel.classList.add('v260-native-source');}
 const methodBadge=document.createElement('div');methodBadge.className='v260-method-note';methodBadge.innerHTML=`${icon('shield')}<span>Revisa la cuenta, el canal y los impuestos antes de confirmar.</span>`;second.appendChild(methodBadge);
 const third=f.querySelector('.studio-step[data-step="3"] .studio-fields');if(third){const trust=document.createElement('div');trust.className='v260-review-head';trust.innerHTML=`${icon('check')} <span><strong>Revisión final</strong><small>Se registra un solo movimiento, con sus cargos aplicables.</small></span>`;third.prepend(trust);}
 const sync=()=>{
  group.querySelectorAll('[data-v260-preset]').forEach(btn=>{const selected=sel.value===btn.dataset.v260Preset;btn.classList.toggle('selected',selected);btn.setAttribute('aria-pressed',String(selected))});
  if(!quick.some(x=>x[0]===sel.value))more.open=true;
  const current=SERVICE_PRESETS[sel.value];const selected=group.querySelector('.v260-selected-service');
  if(selected)selected.innerHTML=`${icon('check')} <span>${sanitize(current?.label||'Otro servicio')} · ${sanitize(f.elements.category?.value||current?.category||'Categoría')} ${f.elements.subcategory?.value?' / '+sanitize(f.elements.subcategory.value):''}</span>`;
  f.querySelectorAll('[data-v260-source]').forEach(btn=>{const chosen=source.value===btn.dataset.v260Source;btn.classList.toggle('selected',chosen);btn.setAttribute('aria-pressed',String(chosen))});
 };
 f.addEventListener('click',ev=>{const preset=ev.target.closest('[data-v260-preset]');if(preset){ev.preventDefault();sel.value=preset.dataset.v260Preset;sel.dispatchEvent(new Event('change',{bubbles:true}));queueMicrotask(sync);return;}const method=ev.target.closest('[data-v260-source]');if(method){ev.preventDefault();source.value=method.dataset.v260Source;source.dispatchEvent(new Event('change',{bubbles:true}));queueMicrotask(sync);return;}});
 f.addEventListener('change',()=>queueMicrotask(sync));sync();
}
document.addEventListener('click',function(e){const q=e.target.closest('[data-v260-service-quick]');if(!q)return;e.preventDefault();e.stopImmediatePropagation();const preset=q.dataset.v260ServiceQuick;if(!SERVICE_PRESETS[preset])return;closeModal();guidedTransactionForm({type:'expense',flowMode:'service',servicePreset:preset});},true);



/* V154 — Buscar + Explorar: one native mobile screen, real data, zero financial state changes. */
const V154_MOBILE_CATEGORIES=[
 {id:'dinero',title:'Mi dinero',sub:'Bancos y cuentas',ico:'wallet',tone:'ocean',pages:['banks','accounts','certificates']},
 {id:'tarjetas',title:'Tarjetas',sub:'Crédito y beneficios',ico:'card',tone:'violet',pages:['cards','benefits']},
 {id:'pagos',title:'Pagos',sub:'Cuotas y vencimientos',ico:'calendar',tone:'coral',pages:['payments','loans','personal']},
 {id:'servicios',title:'Servicios',sub:'Suscripciones',ico:'cycle',tone:'amber',pages:['recurring']},
 {id:'movimientos',title:'Movimientos',sub:'Ingresos y egresos',ico:'chart',tone:'teal',pages:['register','income','expenses','categories']},
 {id:'analitica',title:'Analítica',sub:'Indicadores y evolución',ico:'analytics',tone:'blue',pages:['advanced','kpis','patrimony','budget','analytics']}
];
let v154MobileSearchIndex=[],v154MobileSearchMatches=[],v154MobileCategory=null;
function v154PrepareMobileIndex(){
 v154MobileCategory=null;
 ui.v154MobileSearchQuery='';
 v154MobileSearchIndex=v71SearchEntries().map(x=>({...x,_v154Text:v71SearchNormalize([x.title,x.sub,x.meta].filter(Boolean).join(' ')),_v154Title:v71SearchNormalize(x.title)}));
}
function v154SearchResultsUpdate(){
 const input=document.getElementById('v154-mobile-search-input');
 const output=document.getElementById('v154-mobile-search-results');
 const discover=document.getElementById('v154-mobile-discover');
 if(!input||!output||!discover)return;
 const raw=input.value||'';ui.v154MobileSearchQuery=raw;
 const query=v71SearchNormalize(raw);const terms=query.split(/\s+/).filter(Boolean);
 const category=V154_MOBILE_CATEGORIES.find(c=>c.id===v154MobileCategory);
 const active=!!(terms.length||category);
 discover.hidden=active;output.hidden=!active;
 const clear=input.closest('.v154-search-box')?.querySelector('[data-v154-clear]');if(clear)clear.hidden=!active;
 if(!active){v154MobileSearchMatches=[];output.replaceChildren();return}
 let found=v154MobileSearchIndex.filter(x=>{
  if(category&&!category.pages.includes(x.page))return false;
  return terms.every(t=>x._v154Text.includes(t));
 });
 if(query)found.sort((a,b)=>{
  const score=x=>(x.kind==='section'?4:0)+(x._v154Title===query?20:0)+(x._v154Title.startsWith(query)?10:0);
  return score(b)-score(a);
 });
 v154MobileSearchMatches=found.slice(0,60);
 const resultCount=found.length;
 const label=category?category.title:'Resultados';
 let html=`<div class="v154-results-heading"><div><span class="v154-search-eyebrow">${category?'EXPLORAR CATEGORÍA':'BÚSQUEDA GLOBAL'}</span><h2>${sanitize(label)}</h2><small>${resultCount} coincidencia${resultCount===1?'':'s'}${query?' · '+sanitize(raw):''}</small></div><button type="button" data-v154-clear="1">Ver todo</button></div>`;
 if(category)html+=`<div class="v154-active-filter"><span>${icon(category.ico)} ${sanitize(category.title)}</span><button type="button" data-v154-clear-category="1" aria-label="Quitar filtro de ${sanitize(category.title)}">×</button></div>`;
 if(!resultCount){html+=`<div class="v154-empty">${icon('search')}<strong>Sin resultados</strong><p>Prueba otro nombre o explora otra categoría.</p></div>`}
 else {
  const groups=new Map();v154MobileSearchMatches.forEach((x,i)=>{const key=x.kind==='section'?'section':x.group||x.kind;if(!groups.has(key))groups.set(key,[]);groups.get(key).push({x,i})});
  for(const [key,entries] of groups){html+=`<div class="v154-result-group"><h3>${key==='section'?'Módulos':sanitize(V149_SEARCH_LABELS[key]||'Registros')}</h3>${entries.map(({x,i})=>`<button type="button" class="v154-result-item" data-v154-pick="${i}" aria-label="Abrir ${sanitize(x.title||'registro')}"><span class="v154-result-icon">${icon(x.ico||'search')}</span><span class="v154-result-text"><strong>${sanitize(x.title||'Registro')}</strong><small>${sanitize(x.sub||'')}</small></span><span class="v154-result-chevron">›</span></button>`).join('')}</div>`}
  if(found.length>v154MobileSearchMatches.length)html+=`<p class="v154-more-hint">Mostrando los primeros ${v154MobileSearchMatches.length} resultados. Escribe más para precisar.</p>`;
 }
 output.innerHTML=html;
}
// Dedicated delegated listeners: render() replaces the app tree; these handlers do not multiply.
document.addEventListener('input',e=>{
 if(e.target?.id!=='v154-mobile-search-input')return;
 v154SearchResultsUpdate();
});
document.addEventListener('keydown',e=>{
 if(e.target?.id!=='v154-mobile-search-input')return;
 if(e.key==='Enter'){
  if(v154MobileSearchMatches.length){e.preventDefault();v71SearchPick(v154MobileSearchMatches[0]);}
 }else if(e.key==='Escape'){
  if(e.target.value||v154MobileCategory){e.preventDefault();e.target.value='';v154MobileCategory=null;v154SearchResultsUpdate()}
  else e.target.blur();
 }
});
document.addEventListener('click',e=>{
 const tile=e.target.closest?.('[data-v154-category]');
 const clear=e.target.closest?.('[data-v154-clear]');
 const clearCategory=e.target.closest?.('[data-v154-clear-category]');
 const result=e.target.closest?.('[data-v154-pick]');
 if(!tile&&!clear&&!clearCategory&&!result)return;
 e.preventDefault();e.stopImmediatePropagation();
 if(result){v71SearchPick(v154MobileSearchMatches[Number(result.dataset.v154Pick)]);return}
 const input=document.getElementById('v154-mobile-search-input');if(!input)return;
 if(tile){v154MobileCategory=tile.dataset.v154Category;input.value='';input.blur()}
 else if(clear){v154MobileCategory=null;input.value='';input.blur()}
 else if(clearCategory){v154MobileCategory=null}
 v154SearchResultsUpdate();
},true);
document.addEventListener('focusin',e=>{
 if(e.target?.id==='v154-mobile-search-input')document.body.classList.add('v154-mobile-input-focused');
});
document.addEventListener('focusout',e=>{
 if(e.target?.id==='v154-mobile-search-input')document.body.classList.remove('v154-mobile-input-focused');
});




/* V158 — Wallet: a single swipe selection drives every detail below the rail.
   Updating only the lower wallet content avoids rebuilding the scrolling element
   (which previously interrupted momentum / snap on mobile Safari). */
(function(){
 const reduce=()=>!!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
 function nearestCard(rail){
  const box=rail.getBoundingClientRect(),center=box.left+box.width/2;
  let nearest=null,distance=Infinity;
  for(const face of rail.querySelectorAll('.v68-wallet-face[data-id]')){
   const rect=face.getBoundingClientRect();
   const gap=Math.abs(rect.left+rect.width/2-center);
   if(gap<distance){distance=gap;nearest=face}
  }
  return nearest;
 }
 function setVisualCard(rail,face){
  const id=face.dataset.id;
  rail.querySelectorAll('.v68-wallet-face[data-id]').forEach(card=>{
   const active=card===face;
   card.classList.toggle('selected',active);
   card.setAttribute('aria-pressed',String(active));
  });
  const wallet=rail.closest('.v144-wallet-shell');
  wallet?.querySelectorAll('.v68-wallet-dots [data-id]').forEach(dot=>{
   const selected=dot.dataset.id===id;
   dot.classList.toggle('active',selected);
   dot.setAttribute('aria-current',String(selected));
  });
 }
 function syncDetails(rail,id){
  if(!rail.isConnected||ui.page!=='wallet'||ui.v68WalletId===id)return;
  const host=rail.closest('.v144-wallet-shell');
  const current=host?.querySelector('.v68-wallet');
  if(!current)return;
  const oldActions=current.querySelector(':scope > .v266-selected-balance, :scope > .v68-wallet-actions');
  if(!oldActions)return;
  // Set only the selected view state. No database mutation and no persistence.
  ui.v68WalletId=id;
  ui.v144WalletExpanded=true;
  const template=document.createElement('div');
  template.innerHTML=v68Wallet();
  const updated=template.querySelector('.v68-wallet');
  const freshActions=updated?.querySelector(':scope > .v266-selected-balance, :scope > .v68-wallet-actions');
  if(!freshActions)return;
  const replacement=[];
  let next=freshActions;
  while(next){replacement.push(next);next=next.nextElementSibling}
  let remove=oldActions;
  while(remove){const after=remove.nextElementSibling;remove.remove();remove=after}
  // A fragment reuses the existing gallery and its uninterrupted touch momentum.
  const fragment=document.createDocumentFragment();
  replacement.forEach(el=>fragment.appendChild(el));
  current.appendChild(fragment);
  const active=rail.querySelector('.v68-wallet-face.selected[data-id]');
  const label=active?.getAttribute('aria-label')||active?.textContent?.trim().slice(0,70)||'Tarjeta seleccionada';
  const status=host.querySelector('.v158-wallet-selection-status');
  if(status)status.textContent=label;
  if(!reduce())current.classList.remove('v158-wallet-motion-reset');
 }
 function install(){
  if(ui.page!=='wallet'||window.innerWidth>790)return;
  const rail=document.querySelector('.v144-wallet-shell .v68-wallet-gallery');
  if(!rail||rail.dataset.v158Bound)return;
  rail.dataset.v158Bound='true';
  const wallet=rail.closest('.v144-wallet-shell');
  let status=wallet.querySelector('.v158-wallet-selection-status');
  if(!status){
   status=document.createElement('span');
   status.className='v158-wallet-selection-status';
   status.setAttribute('role','status');status.setAttribute('aria-live','polite');
   rail.insertAdjacentElement('afterend',status);
  }
  let frame=0,prevId=ui.v68WalletId;
  function update(){
   if(!rail.isConnected)return;
   const face=nearestCard(rail);
   if(!face)return;
   setVisualCard(rail,face);
   const id=face.dataset.id;
   if(prevId!==id){prevId=id;syncDetails(rail,id)}
  }
  const schedule=()=>{if(frame||!rail.isConnected)return;frame=requestAnimationFrame(()=>{frame=0;update()})};
  rail.addEventListener('scroll',schedule,{passive:true});
  rail.addEventListener('scrollend',schedule,{passive:true});
  // The browser may not dispatch scrollend; the regular scroll path is sufficient.
  // Do not apply scroll-behavior:smooth during touch inertia: it can create snap loops.
  const initial=rail.querySelector('.v68-wallet-face.selected[data-id]');
  if(initial)status.textContent=initial.getAttribute('aria-label')||'Tarjeta seleccionada';
 }
 const priorRender=render;
 render=function(...args){
  const result=priorRender.apply(this,args);
  if(ui.page==='wallet')requestAnimationFrame(install);
  return result;
 };
 document.addEventListener('DOMContentLoaded',()=>requestAnimationFrame(install),{once:true});
 requestAnimationFrame(install);
})();

/* Keyboard-safe mobile search: keep field visible as the visual viewport changes. */
(function(){
 const vv=window.visualViewport;
 if(!vv)return;
 let frame=0;
 function measure(){
  frame=0;
  if(ui.page!=='mobilesearch'||!isMobileViewport())return;
  const keyboard=Math.max(0,window.innerHeight-vv.height-vv.offsetTop);
  const isKeyboard=keyboard>110;
  document.body.classList.toggle('v158-keyboard-visible',isKeyboard&&document.activeElement?.id==='v154-mobile-search-input');
  document.documentElement.style.setProperty('--v158-visual-height',Math.round(vv.height)+'px');
 }
 function schedule(){if(!frame)frame=requestAnimationFrame(measure)}
 vv.addEventListener('resize',schedule,{passive:true});
 vv.addEventListener('scroll',schedule,{passive:true});
 document.addEventListener('focusin',event=>{if(event.target?.id==='v154-mobile-search-input')schedule()});
 document.addEventListener('focusout',event=>{if(event.target?.id==='v154-mobile-search-input'){document.body.classList.remove('v158-keyboard-visible');schedule()}});
})();

/* V186 contextual view: same lexical scope as db, ui, onAction and render. */
/* Vive el hoy · V186 — Explorador financiero contextual.
   No añade movimientos ni consulta servicios externos. Solo muestra información ya registrada. */
(function(){
 'use strict';
 const cash=a=>Number(getAccountBalance(a))||0;
 const dop=(amount,cur='DOP')=>Number(fx(Number(amount)||0,cur))||0;
 const cardD=c=>Number(cardStatus(c,'DOP').debt)||0;
 const cardU=c=>Number(cardStatus(c,'USD').debt)||0;
 const cardTotal=c=>dop(cardD(c))+dop(cardU(c),'USD');
 const bankLoan=l=>dop(loanStatus(l).balance,l.currency||'DOP');
 const certValue=c=>dop(certificateCapital(c),c.currency||'DOP');
 const balance=()=>db.accounts.reduce((s,a)=>s+dop(cash(a),a.currency||'DOP'),0);
 const credit=()=>db.cards.reduce((s,c)=>s+cardTotal(c),0);
 const loans=()=>db.loans.reduce((s,l)=>s+bankLoan(l),0);
 const certificates=()=>db.certificates.reduce((s,c)=>s+certValue(c),0);
 const owed=()=>db.personalLoans.filter(l=>l.direction==='borrowed').reduce((s,l)=>s+dop(personalBalance(l),l.currency||'DOP'),0);
 const recv=()=>db.personalLoans.filter(l=>l.direction==='lent').reduce((s,l)=>s+dop(personalBalance(l),l.currency||'DOP'),0);
 const net=()=>balance()+certificates()+recv()-credit()-loans()-owed();
 const fmt=(n,cur='DOP')=>money(n,cur,2);
 const fmtEq=n=>money(n,'DOP',2);
 const period=()=>String(ui.month||today().slice(0,7));
 const metric=(label,value)=>`<div><small>${sanitize(label)}</small><strong class="${Number(value)<0?'is-negative':''}">${typeof value==='number'?fmtEq(value):sanitize(String(value))}</strong></div>`;
 const row=(title,subtitle,amount,action,id,cur='DOP')=>({title,subtitle,amount,action,id,cur});
 const bankName=id=>db.banks.find(b=>b.id===id)?.name||'Sin institución';
 const accountRows=(filter=()=>true)=>db.accounts.filter(filter).map(a=>row(a.name,`${a.kind==='cash'?'Efectivo':bankName(a.bankId)} · ${a.currency||'DOP'}${cash(a)<0?' · Saldo negativo':''}`,cash(a),'goAccount',a.id,a.currency||'DOP'));
 const cardRows=(filter=()=>true)=>db.cards.filter(filter).map(c=>row(c.name,`${bankName(c.bankId)} · RD$ ${fmt(cardD(c))} · US$ ${fmt(cardU(c),'USD')}`,cardTotal(c),'goCard',c.id));
 const loanRows=(filter=()=>true)=>db.loans.filter(filter).map(l=>row(l.name,`${bankName(l.bankId)} · ${l.currency||'DOP'} · Capital pendiente`,loanStatus(l).balance,'goLoan',l.id,l.currency||'DOP'));
 const certRows=(filter=()=>true)=>db.certificates.filter(filter).map(c=>row(c.name,`${bankName(c.bankId)} · ${c.currency||'DOP'} · Inversión, no disponible`,certificateCapital(c),'goCertificate',c.id,c.currency||'DOP'));
 const personalRows=(direction)=>db.personalLoans.filter(l=>l.direction===direction&&personalBalance(l)>.005).map(l=>row(l.person||'Relación personal',`${direction==='lent'?'Por cobrar':'Por pagar'} · ${l.currency||'DOP'}`,personalBalance(l),'navigate','personal',l.currency||'DOP'));
 const cardAvailable=()=>db.cards.reduce((s,c)=>s+dop(Math.max(0,cardStatus(c,'DOP').availableWithOverdraft))+dop(Math.max(0,cardStatus(c,'USD').availableWithOverdraft),'USD'),0);
 function totalBank(b){const accounts=db.accounts.filter(a=>a.bankId===b.id),cards=db.cards.filter(c=>c.bankId===b.id),loanArr=db.loans.filter(l=>l.bankId===b.id),certArr=db.certificates.filter(c=>c.bankId===b.id);
  const f=accounts.reduce((s,a)=>s+dop(cash(a),a.currency),0),d=cards.reduce((s,c)=>s+cardTotal(c),0)+loanArr.reduce((s,l)=>s+bankLoan(l),0),invested=certArr.reduce((s,c)=>s+certValue(c),0);
  return {funds:f,debt:d,invested,net:f+invested-d,products:accounts.length+cards.length+loanArr.length+certArr.length};
 }
 const scopeRows=(name,items)=>({name,items});
 function view(kind){
  const sums=[],groups=[],actions=[],note='Importes calculados a partir de tus registros. Los valores US$ se convierten al tipo de cambio configurado solo para los totales RD$ equivalentes. No son saldos consultados en tiempo real.';
  let title='',hint='',memo=note;
  const nav=(name,route)=>actions.push([name,route]);
  const sum=(name,n)=>sums.push([name,n]);
  const group=(name,items)=>groups.push(scopeRows(name,items));
  if(kind.startsWith('bank:')){
   const id=kind.slice(5),b=db.banks.find(b=>b.id===id);if(!b)return view('banks');const t=totalBank(b);
   title=b.name;hint='Dónde está el dinero y dónde están las obligaciones de esta institución.';
   sum('Fondos en cuentas',t.funds);sum('Deuda de productos',t.debt);sum('Posición con el banco',t.net);
   group('Cuentas y disponibilidad',accountRows(a=>a.bankId===id));group('Tarjetas y utilización',cardRows(c=>c.bankId===id));group('Préstamos',loanRows(l=>l.bankId===id));group('Certificados',certRows(c=>c.bankId===id));
   nav('Abrir la institución','banks');
  }else if(kind==='liquidity'||kind==='accounts'){
   title='Tu liquidez, cuenta por cuenta';hint='Ubica el dinero disponible y descubre cualquier saldo negativo sin confundirlo con crédito.';
   sum('Liquidez neta registrada',balance());sum('Cuentas en RD$',db.accounts.filter(a=>a.currency==='DOP').reduce((s,a)=>s+cash(a),0));sum('Cuentas en US$',fmt(db.accounts.filter(a=>a.currency==='USD').reduce((s,a)=>s+cash(a),0),'USD'));
   const ordered=[...db.accounts].sort((a,b)=>cash(a)-cash(b));
   group('Dónde tienes saldos negativos',accountRows(a=>cash(a)<-.005));
   group('Todas tus cuentas y efectivo',ordered.map(a=>row(a.name,`${a.kind==='cash'?'Efectivo':bankName(a.bankId)} · ${a.currency} · ${a.kind||'Cuenta'}`,cash(a),'goAccount',a.id,a.currency||'DOP')));
   group('Fondos por institución',db.banks.map(b=>{const v=totalBank(b);return row(b.name,`${v.products} productos registrados · neto institucional ${fmtEq(v.net)}`,v.funds,'bankDetails',b.id)}));
   nav('Ir a cuentas','accounts');
  }else if(kind==='debt'){
   title='Todas tus deudas';hint='Tarjetas, capital de préstamos y obligaciones personales, sin duplicar los compromisos mensuales.';
   sum('Deuda total registrada',credit()+loans()+owed());sum('En tarjetas',credit());sum('Préstamos y personas',loans()+owed());
   group('Tarjetas de crédito',cardRows());group('Préstamos bancarios',loanRows());group('Dinero que debes a personas',personalRows('borrowed'));
   nav('Abrir tarjetas','cards');nav('Abrir préstamos','loans');
  }else if(kind==='net'||kind==='patrimony'){
   title='Cómo se forma tu posición neta';hint='De activos a pasivos: sigue cada partida hasta su producto de origen.';
   sum('Activos registrados',balance()+certificates()+recv());sum('Deudas registradas',credit()+loans()+owed());sum('Posición neta',net());
   group('Cuentas y efectivo',accountRows());group('Capital invertido',certRows());group('Por cobrar a personas',personalRows('lent'));
   group('Deuda de tarjetas',cardRows());group('Préstamos bancarios',loanRows());group('Obligaciones personales',personalRows('borrowed'));
   nav('Ver patrimonio','patrimony');
  }else if(kind==='banks'){
   title='Instituciones y productos';hint='De cada banco a sus fondos, préstamos, tarjetas, certificados y posición neta.';
   sum('Instituciones',String(db.banks.length));sum('Fondos en cuentas',balance());sum('Deuda bancaria',credit()+loans());
   group('Resultado por institución',db.banks.map(b=>{const v=totalBank(b);return row(b.name,`Fondos ${fmtEq(v.funds)} · Deuda ${fmtEq(v.debt)} · ${v.products} productos`,v.net,'v186Deep','bank:'+b.id)}));
   group('Productos con saldo negativo',accountRows(a=>cash(a)<0));nav('Instituciones','banks');
  }else if(kind==='cards'){
   title='Tarjetas: deuda y crédito';hint='Deuda por tarjeta y moneda, con acceso a cortes, movimientos y beneficios.';
   sum('Deuda actual',credit());sum('Crédito disponible',cardAvailable());sum('Tarjetas registradas',String(db.cards.length));
   group('Tarjetas y saldos',cardRows());nav('Abrir mis tarjetas','cards');nav('Beneficios y costos','benefits');
  }else if(kind.startsWith('card:')){
   const c=db.cards.find(x=>x.id===kind.slice(5));if(!c)return view('cards');title=c.name;hint='Ciclo de vida y saldos por moneda de esta tarjeta.';
   sum('Deuda RD$',cardD(c));sum('Deuda US$',fmt(cardU(c),'USD'));sum('Equivalente de deuda',cardTotal(c));
   group('Producto',cardRows(x=>x.id===c.id));nav('Ver cortes y movimientos','cards');nav('Beneficios de tarjetas','benefits');
  }else if(kind==='loans'){
   title='Préstamos bancarios';hint='Capital pendiente por contrato y moneda.';
   sum('Capital pendiente',loans());sum('Contratos',String(db.loans.length));sum('Próximo mes',v89DebtCapacity(period()).a.loans);
   group('Préstamos registrados',loanRows());nav('Abrir préstamos','loans');
  }else if(kind==='certificates'){
   title='Certificados e inversiones';hint='Capital registrado que forma parte del patrimonio, pero no de la liquidez.';
   sum('Capital invertido',certificates());sum('Certificados',String(db.certificates.length));sum('Liquidez independiente',balance());
   group('Certificados registrados',certRows());nav('Abrir certificados','certificates');
  }else if(kind==='payments'){
   const items=v99PendingForPeriod(period()).filter(x=>x&&x.date).sort((a,b)=>a.date.localeCompare(b.date)),d=v89DebtCapacity(period());
   title='Compromisos del período';hint=`Vencimientos de ${period()} y carga mensual: no son el saldo total de la deuda.`;
   sum('Compromisos mensuales',d.monthly);sum('Pendiente en agenda',items.reduce((s,x)=>s+dop(x.amount,x.currency),0));sum('Ingresos considerados',d.income);
   group('Vencimientos ordenados por fecha',items.map(x=>row(x.name,`${prettyDate(x.date)} · ${x.kind==='recurring'?'Servicio o suscripción':x.kind==='loan'?'Préstamo':x.kind==='card'?'Tarjeta':'Relación personal'}`,x.amount, 'navigate',({card:'cards',loan:'loans',recurring:'recurring',personal:'personal'})[x.kind]||'payments',x.currency)));
   nav('Abrir calendario de pagos','payments');
  }else if(kind==='recurring'){
   title='Suscripciones y servicios';hint='Cuánto cuesta cada servicio, cuándo vence y cómo administrarlo.';
   const active=db.recurring.filter(x=>x.active!==false),rate={weekly:52/12,monthly:1,quarterly:1/3,annual:1/12};
   const monthly=active.reduce((s,x)=>s+dop(Number(x.amount||0)*(rate[x.frequency]||1),x.currency),0);
   sum('Servicios activos',String(active.length));sum('Costo mensual equivalente',monthly);sum('Total registrados',String(db.recurring.length));
   group('Mis suscripciones',db.recurring.map(x=>row(x.name,`${x.active===false?'Pausada':'Activa'} · ${x.frequency||'monthly'} · próximo ${x.nextDue||'sin fecha'}`,x.amount,'editRecurring',x.id,x.currency||'DOP')));
   nav('Ir a suscripciones','recurring');nav('Centro de pagos','payments');
  }else if(kind==='personal'){
   title='Deudas y préstamos entre personas';hint='Lo que te deben y lo que debes; sin mezclar estas relaciones con bancos.';
   sum('Por cobrar',recv());sum('Por pagar',owed());sum('Posición personal',recv()-owed());
   group('Me deben',personalRows('lent'));group('Yo debo',personalRows('borrowed'));nav('Abrir entre personas','personal');
  }else if(kind==='income'||kind==='expenses'){
   const m=monthStats(),t=kind==='income'?'income':'expense',isIncome=t==='income',tx=db.transactions.filter(x=>String(x.date||'').startsWith(period())&&x.type===t);
   title=isIncome?'Ingresos del período':'Egresos del período';hint='Abre cada registro para comprobar su origen y concepto. Los totales siguen la metodología del módulo.';
   sum(isIncome?'Ingresos':'Egresos',isIncome?m.income:m.expense);sum('Movimientos directos',String(tx.length));sum('Resultado neto',m.net);
   group('Operaciones registradas',tx.sort((a,b)=>b.date.localeCompare(a.date)).slice(0,35).map(x=>row(transactionTitle(x),`${prettyDate(x.date)} · ${x.category||'Sin categoría'}`,x.amount,'navigate','register',x.currency||'DOP')));
   nav(isIncome?'Analizar ingresos':'Analizar egresos',isIncome?'income':'expenses');
  }else if(kind==='benefits'){
   title='Beneficios por tarjeta';hint='Cashback acreditado y cargos registrados por producto.';
   const year=Number(period().slice(0,4));let received=0,cost=0;
   const rows=db.cards.map(c=>{const x=benefitBreakdown(c,'DOP',year),y=benefitBreakdown(c,'USD',year),inD=dop(x.credited)+dop(y.credited,'USD'),outD=dop(x.costs)+dop(y.costs,'USD');received+=inD;cost+=outD;return row(c.name,`Cashback ${fmtEq(inD)} · costos cobrados ${fmtEq(outD)}`,inD-outD,'goCard',c.id)});
   sum('Cashback acreditado',received);sum('Costos cobrados',cost);sum('Resultado neto',received-cost);
   group('Beneficios por tarjeta',rows);nav('Abrir beneficios','benefits');
  }else if(kind==='budget'||kind==='advanced'){
   const m=monthStats();title=kind==='budget'?'Presupuesto y evolución':'Analítica y desempeño';hint='Analiza las cifras del período sin alterar tus registros.';
   sum('Ingresos',m.income);sum('Egresos',m.expense);sum('Resultado',m.net);
   group('Profundiza en la información',[row('Ingresos','Fuentes y tendencias',m.income,'navigate','income'),row('Egresos','Categorías y movimientos',m.expense,'navigate','expenses'),row('Deudas','Productos y saldos',credit()+loans()+owed(),'v186Deep','debt')]);
   nav(kind==='budget'?'Abrir presupuestos':'Abrir analítica',kind);
  }else return view('net');
  return {title,hint,sums,groups,actions,memo};
 }
 function renderRows(items){return items.length?`<div class="v186-deep-rows">${items.map(x=>`<button type="button" class="v186-deep-row" data-act="v186Go" data-next="${sanitize(x.action||'navigate')}" data-id="${sanitize(String(x.id||''))}"><span><strong>${sanitize(x.title)}</strong><small>${sanitize(x.subtitle||'')}</small></span><b class="${Number(x.amount)<0?'is-negative':''}">${fmt(x.amount,x.cur)}</b>${icon('arrow')}</button>`).join('')}</div>`:'<p class="v186-deep-note">No hay productos o movimientos registrados en esta categoría.</p>'}
 function open(kind){
  const data=view(kind),holder=document.getElementById('modal-root');if(!holder)return;
  document.querySelectorAll('.v36-notifications[open]').forEach(x=>x.open=false);
  holder.innerHTML=`<div class="v186-deep-layer" role="presentation"><section class="v186-deep-dialog" role="dialog" aria-modal="true" aria-labelledby="v186-deep-title"><header class="v186-deep-head"><div><small>EXPLORADOR FINANCIERO · ${sanitize(ui.page||'Resumen')}</small><h2 id="v186-deep-title">${sanitize(data.title)}</h2><p>${sanitize(data.hint)}</p></div><button type="button" data-act="closeModal" class="v186-deep-close" aria-label="Cerrar desglose">×</button></header><div class="v186-deep-summary">${data.sums.map(([key,n])=>metric(key,n)).join('')}</div>${data.groups.map(g=>`<section class="v186-deep-section"><h3>${sanitize(g.name)} · ${g.items.length}</h3>${renderRows(g.items)}</section>`).join('')}<footer class="v186-deep-actions">${data.actions.map(([label,route])=>`<button type="button" data-act="v186Go" data-next="navigate" data-id="${sanitize(route)}" class="btn sm soft">${sanitize(label)} ${icon('arrow')}</button>`).join('')}</footer><p class="v186-deep-note">${sanitize(data.memo)}</p></section></div>`;
  holder.querySelector('.v186-deep-close')?.focus({preventScroll:true});
 }
 // Click contextual for main bubbles and all other prominent KPI tiles.
 const previousAction=onAction;
 onAction=function(action,el){
  if(action==='v186Deep'){open(String(el?.dataset.id||'net'));return;}
  if(action==='v186Go'){const next=el?.dataset.next||'navigate',id=el?.dataset.id||'';closeModal();if(next==='v186Deep')return open(id);return previousAction(next,{dataset:{id}});}
  return previousAction(action,el);
 };
 function interpret(title,page){
  const x=String(title||'').toLocaleLowerCase('es').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  if(/posicion neta|patrimonio|neto/.test(x))return 'net';
  if(/deuda|sobregiro|pasivo/.test(x))return 'debt';
  if(/liquid|disponible|fondos|efectivo|cuentas|saldo/.test(x))return 'liquidity';
  if(/tarjeta|limite de consumo|credito/.test(x))return 'cards';
  if(/prestamo|capital pendiente|cuota/.test(x))return 'loans';
  if(/certificado|inversion/.test(x))return 'certificates';
  if(/compromis|vencim|pendiente|pago/.test(x))return 'payments';
  if(/ingreso/.test(x))return 'income';
  if(/gasto|egreso/.test(x))return 'expenses';
  if(/beneficio|cashback|recompensa/.test(x))return 'benefits';
  return ({banks:'banks',accounts:'liquidity',cards:'cards',loans:'loans',certificates:'certificates',payments:'payments',recurring:'recurring',personal:'personal',benefits:'benefits',income:'income',expenses:'expenses',budget:'budget',patrimony:'net',advanced:'advanced',register:'income'})[page]||'net';
 }
 function decorate(){
  const main=document.querySelector('#app .main'),page=document.getElementById('page');if(!main||!page)return;
  const route=String(ui.page||'overview');
  if(route==='overview')return; // The reference summary has its own three existing interactive circles.
  page.querySelectorAll('.kpi,.v145-payment-kpi,.v46-global-main,.v46-global-secondary>div,.v176-card-kpi,.v57-product-hero .v46-global-main').forEach(tile=>{
   if(tile.classList.contains('v187-interactive-kpi'))return;
   if(tile.closest('button,[role="button"],.ws-gallery,.v186-deep-layer,.v186-tools-extra'))return;
   const heading=tile.querySelector('.kpi-head,small,span,h3')?.textContent?.trim()||route;
   let kind=interpret(heading,route);
   if(route==='banks'&&tile.closest('.bank-workspace')&&ui.bankId)kind='bank:'+ui.bankId;
   tile.dataset.act='v186Deep';tile.dataset.id=kind;
   tile.classList.add('v187-interactive-kpi');
   if(!tile.hasAttribute('tabindex'))tile.tabIndex=0;
   if(!tile.hasAttribute('role'))tile.setAttribute('role','button');
   tile.title='Consultar '+heading;
   tile.setAttribute('aria-label',heading+'. Pulsar para ver su desglose contextual.');
  });
 }
 const originalRender=render;
 render=function(){originalRender();decorate()};
 decorate();
 // This listener is scoped to the explorer overlay. It does not interfere with existing modals.
 document.addEventListener('click',ev=>{if(ev.target.classList?.contains('v186-deep-layer'))closeModal()},true);
 document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&document.querySelector('.v186-deep-layer')){ev.preventDefault();closeModal()}},true);
})();

/* V187 interaction — click on the existing KPI surface, with no new text or buttons. */
(function(){
 const prev=onAction;
 onAction=function(action,el){
  if(action==='v187WealthDetail'){v187OpenWealthDetail(el?.dataset.id||'net');return;}
  if(action==='v187History'){v187OpenHistory('60');return;}
  if(action==='v187HistoryRange'){v187OpenHistory(el?.dataset.id||'60');return;}
  if(action==='v187WealthGo'){const id=el?.dataset.id||'patrimony';closeModal();return prev('navigate',{dataset:{id}})}
  return prev(action,el);
 };
 document.addEventListener('keydown',e=>{
  if((e.key==='Enter'||e.key===' ')&&e.target?.classList?.contains('v187-interactive-kpi')){e.preventDefault();onAction('v186Deep',e.target)}
  if(e.key==='Escape'&&document.querySelector('.v187-modal-overlay')){e.preventDefault();closeModal()}
 });
 document.addEventListener('click',e=>{if(e.target?.classList?.contains('v187-modal-overlay'))closeModal()},true);
})();


(function(){'use strict';
// Search without dropping input focus; use the same global selector after re-render.
document.addEventListener('input',function(ev){
 if(ev.target?.id!=='v209WidgetSearch')return;
 const raw=ev.target.value||'';
 if(typeof ui!=='undefined')ui.widgetSearch=raw;
 const norm=(v)=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const q=norm(raw);
 document.querySelectorAll('.ws-library .ws-catalog-section').forEach(section=>{
  let count=0;
  section.querySelectorAll('.ws-gallery-card').forEach(card=>{
   const text=norm(card.querySelector('.ws-gallery-footer strong')?.textContent+' '+card.querySelector('.v208-global-note')?.textContent+' '+(card.getAttribute('data-widget-preview')||''));
   card.hidden=!!q&&!text.includes(q);if(!card.hidden)count++;
  });section.hidden=count===0;
 });
});
let resize=null;
function clamp(v,lo,hi){return Math.max(lo,Math.min(hi,v))}
function finish(ev,cancelled){
 if(!resize||ev.pointerId!==resize.pointer)return;
 const r=resize;resize=null;
 try{r.handle.releasePointerCapture(ev.pointerId)}catch(_){ }
 r.tile.classList.remove('v209-resizing');
 if(cancelled){r.tile.style.setProperty('--ws-cols',r.span);r.tile.style.setProperty('--ws-h',r.height+'px');return;}
 if(!r.moved)return;
 if(typeof db!=='undefined'&&typeof persist==='function'){
  db.settings.widgetSizes??={};db.settings.widgetHeights??={};
  db.settings.widgetSizes[r.id]=r.newSpan;
  db.settings.widgetHeights[r.id]=r.newHeight;
  persist();if(typeof render==='function')render();
 }
}
document.addEventListener('pointerdown',function(ev){
 const handle=ev.target.closest?.('[data-widget-resizer]');if(!handle)return;
 if(ev.pointerType==='mouse'&&ev.button!==0)return;
 const tile=handle.closest('.ws-tile'),board=tile?.parentElement;
 if(!tile||!board)return;
 ev.preventDefault();ev.stopPropagation();
 const grid=getComputedStyle(board),cols=grid.gridTemplateColumns.split(' ').filter(Boolean).length||2;
 const gap=parseFloat(grid.columnGap)||12;
 const colWidth=(board.getBoundingClientRect().width-gap*(cols-1))/cols;
 const span=clamp(Number(tile.dataset.wsSpan)||1,1,cols);
 const height=clamp(Number(tile.dataset.wsHeight)||194,165,600);
 resize={pointer:ev.pointerId,handle,tile,id:tile.dataset.widget,cols,colWidth,gap,startX:ev.clientX,startY:ev.clientY,span,height,newSpan:span,newHeight:height,moved:false};
 tile.classList.add('v209-resizing');
 try{handle.setPointerCapture(ev.pointerId)}catch(_){ }
},true);
document.addEventListener('pointermove',function(ev){
 const r=resize;if(!r||ev.pointerId!==r.pointer)return;
 const dx=ev.clientX-r.startX,dy=ev.clientY-r.startY;
 if(Math.abs(dx)+Math.abs(dy)<7&&!r.moved)return;
 r.moved=true;
 const cols=clamp(Math.round(r.span+dx/(r.colWidth+r.gap)),1,r.cols);
 const height=clamp(Math.round((r.height+dy)/20)*20,165,600);
 r.newSpan=cols;r.newHeight=height;
 r.tile.style.setProperty('--ws-cols',cols);
 r.tile.style.setProperty('--ws-h',height+'px');
},true);
document.addEventListener('pointerup',ev=>finish(ev,false),true);
document.addEventListener('pointercancel',ev=>finish(ev,true),true);
document.addEventListener('keydown',function(ev){
 if(ev.key==='Escape'&&typeof ui!=='undefined'&&ui.widgetEditor){ui.widgetEditor=false;if(typeof render==='function')render();return;}
 const handle=ev.target.closest?.('[data-widget-resizer]');if(!handle||!['ArrowRight','ArrowLeft','ArrowUp','ArrowDown'].includes(ev.key))return;
 ev.preventDefault();
 const id=handle.dataset.widgetResizer;
 if(typeof db==='undefined'||!id)return;
 db.settings.widgetSizes??={};db.settings.widgetHeights??={};
 const board=handle.closest('.ws-board');
 const cols=board?getComputedStyle(board).gridTemplateColumns.split(' ').filter(Boolean).length:2;
 if(ev.key==='ArrowLeft'||ev.key==='ArrowRight'){
  const now=typeof widgetSize==='function'?widgetSize(id):1;
  db.settings.widgetSizes[id]=clamp(now+(ev.key==='ArrowRight'?1:-1),1,cols);
 }else{
  const now=typeof widgetHeight==='function'?widgetHeight(id):194;
  db.settings.widgetHeights[id]=clamp(now+(ev.key==='ArrowDown'?40:-40),165,600);
 }
 if(typeof persist==='function')persist();if(typeof render==='function')render();
},true);
})();

/* V213: Apple Pay con Supabase Edge Functions; movimientos + Wallet móvil.
   El navegador no lee Wallet. Los tokens se emiten solo en el backend y no se persisten en el documento del usuario. */

function v213ApplePayBadge(t){
 if(!t || !(t.applePaySource==='wallet-shortcuts' || t.applePayEventId || String(t.tags||'').split(',').includes('apple-pay')))return '';
 return `<span class="v213-apple-badge v216-apple-pay-brand" title="Compra registrada por Apple Pay / Atajos" aria-label="Origen Apple Pay"><span class="v216-apple-mark" aria-hidden="true">${icon('apple')}</span><span>Pay</span></span>`;
}
const v212State={links:[],events:[],secret:'',webhook:'',selectedCard:'',currency:'DOP',busy:false,loaded:false,error:'',syncError:'',lastSync:'',health:'unverified',healthMessage:'El vínculo y la recepción son pasos separados.'};
let v212Busy=false;
const v212Enabled=()=>!!(f33Active&&f33Api&&f33User);
function v212SettingsPanel(){
 const cards=(db.cards||[]).filter(c=>!c.archived);
 const linkRows=v212State.links.filter(x=>x.active).map(x=>{
   const c=card(x.instrument_id);
   return `<div class="v212-linked"><div><strong>${sanitize(c?.name||x.card_label||'Tarjeta')}</strong><small>${sanitize(bankOf(c))} · ${sanitize(x.currency)} · Conexión activa</small></div><button type="button" class="v212-small" data-v212="revoke" data-id="${sanitize(x.id)}" ${v212State.busy?'disabled':''}>Desvincular</button></div>`;
 }).join('');
 const eventRows=v212State.events.filter(x=>['pending','review','imported'].includes(x.status)).slice(0,12).map(x=>{
   const c=card(x.instrument_id);
   return `<div class="v212-event"><span class="v212-dot"></span><div><strong>${sanitize(x.merchant||'Comercio')}</strong><small>${sanitize(c?.name||'Tarjeta archivada')} · ${prettyDate(String(x.received_at||'').slice(0,10))} · ${x.status==='review'?'Revisar posible duplicado':x.status==='imported'?'Registrada en Movimientos':'Por sincronizar'}</small></div><b>${money(x.amount,x.currency,2)}</b>${x.status==='review'?`<button class="v212-small" type="button" data-v212="force" data-id="${sanitize(x.id)}">Registrar</button><button class="v212-small" type="button" data-v212="ignore" data-id="${sanitize(x.id)}">Ignorar</button>`:''}</div>`;
 }).join('');
 return `<section class="v212-panel" aria-label="Apple Pay y Atajos"><div class="v212-head"><div><span class="summary-tag">ATAJOS · APPLE PAY</span><h3>Compras de Wallet, registradas con claridad</h3><p>Vincula cada tarjeta a su atajo. Los pagos compatibles llegan directamente a Supabase. Al sincronizar se registran en Movimientos y en la Wallet móvil de la tarjeta correcta, con un distintivo Apple Pay, sin descontar una cuenta dos veces. El estado muestra si el servidor recibió el evento, no si Wallet concedió acceso directo.</p></div><span class="v212-pill">${v212State.links.filter(x=>x.active).length} ${v212State.links.filter(x=>x.active).length===1?'vinculada':'vinculadas'}</span></div>
 <div class="v212-setup"><div><label class="filter-label" for="v212-card">Tarjeta en Vive el Hoy</label><select class="field" id="v212-card">${cards.length?cards.map(c=>`<option value="${sanitize(c.id)}" ${c.id===v212State.selectedCard?'selected':''}>${sanitize(c.name)} · ${sanitize(bankOf(c))}</option>`).join(''):'<option value="">Primero registra una tarjeta</option>'}</select></div><div><label class="filter-label" for="v212-currency">Moneda del atajo</label><select class="field" id="v212-currency"><option value="DOP" ${v212State.currency==='DOP'?'selected':''}>RD$</option><option value="USD" ${v212State.currency==='USD'?'selected':''}>US$</option></select></div><button type="button" class="btn primary" data-v212="pair" ${!cards.length||v212State.busy?'disabled':''}>${v212State.busy?'Conectando…':'Vincular tarjeta'}</button></div>
 <div class="v274-apple-health ${v212State.health==='ok'?'ready':v212State.health==='error'?'fail':'neutral'}" role="status" aria-live="polite"><div><strong>${v212State.health==='ok'?'Receptor verificado · sin registrar gastos':v212State.health==='testing'?'Comprobando receptor…':v212State.health==='error'?'Receptor pendiente de reparar':'Vinculación y recepción se verifican por separado'}</strong><p>${sanitize(v212State.healthMessage||'')}</p></div>${v212State.secret?`<button type="button" class="v212-small" data-v212="test-ingest" ${v212State.health==='testing'?'disabled':''}>Probar conexión</button>`:''}</div>
 ${v212State.secret?`<div class="v212-secret"><strong>Conexión creada: guarda estos datos en tu Atajo</strong><p>La clave solo se muestra ahora. No la compartas ni la coloques en capturas.</p><div class="v212-secretline"><span>URL de recepción</span><button class="v212-small" data-v212="copy-url" type="button">Copiar URL</button></div><code>${sanitize(v212State.webhook)}</code><div class="v212-secretline"><span>Encabezado: X-Vive-Token</span><button class="v212-small" data-v212="copy-token" type="button">Copiar clave</button></div><input type="password" autocomplete="off" readonly aria-label="Clave del atajo" value="${sanitize(v212State.secret)}"/></div>`:''}
 <details class="v212-guide" open><summary>Configurar Atajos de iPhone · 3 pasos</summary><ol><li>Abre <b>Atajos → Automatización → Transacción</b> y elige esta tarjeta. Los nombres pueden variar según iOS.</li><li>Selecciona <b>Ejecutar inmediatamente</b>, si está disponible.</li><li>En el editor del Atajo, utiliza las variables <b>Shortcut Input → Amount</b> y <b>Shortcut Input → Merchant</b> recibidas por el disparador. No escribas esos nombres como texto literal. <b>No añadas event_id</b>.</li><li>En <b>Obtener contenido de URL</b>, utiliza la URL de recepción, método <b>POST</b> y encabezados <b>X-Vive-Token</b> con tu clave y <b>Content-Type: application/json</b>.</li><li>En <b>Cuerpo de solicitud → JSON</b> envía solamente: <code>amount</code> = importe de la transacción (Número); <code>merchant</code> = comercio de la transacción (Texto); <code>currency</code> = <b>DOP</b> o <b>USD</b>. Inserta las variables de la transacción, no las palabras “Importe” o “Comercio”.</li><li>Al vincular, pulsa <b>Probar conexión</b>: comprobará el token, el receptor y el vínculo con <code>dry_run</code>, sin crear gastos. Si no responde, revisa la publicación de las dos funciones y la migración SQL.</li><li>Abre Vive el Hoy con sesión iniciada y pulsa <b>Actualizar</b> en esta sección. La importación también se ejecuta periódicamente mientras la app está visible.</li></ol><p>La recepción en Supabase puede ocurrir con la app cerrada; la contabilización requiere abrir y sincronizar Vive el Hoy. Una prueba correcta de conexión no confirma que Atajos se haya ejecutado. El servidor evita reintentos idénticos próximos mediante una ventana de seguridad; dos compras legítimas iguales muy seguidas pueden requerir revisión. No recupera pagos antiguos automáticamente.</p></details>
 <div class="v212-sections"><div><div class="v212-title"><strong>Tarjetas conectadas</strong><button type="button" class="v212-small" data-v212="refresh">Actualizar</button></div>${linkRows||'<p class="v212-muted">Todavía no has vinculado tarjetas.</p>'}</div><div><div class="v212-title"><strong>Actividad reciente</strong><span>${v212State.events.length} evento${v212State.events.length===1?'':'s'}</span></div>${eventRows||'<p class="v212-muted">No hay compras recibidas recientemente.</p>'}<small class="v212-muted">Las compras claras se contabilizan al sincronizar la app. Coincidencias dudosas quedan pendientes de revisión.</small></div></div>
 ${(v212State.error||v212State.syncError)?`<p class="v212-error" role="status">${sanitize(v212State.error||v212State.syncError)}</p>`:''}<p class="v212-muted">Las tarjetas se administran con <code>apple-pay-link</code>; las compras se reciben mediante <code>apple-pay-ingest</code>. Son funciones distintas y deben publicarse por separado en Supabase. No se solicitan números de tarjeta, CVV ni contraseñas bancarias.</p></section>`;
}
function v212Show(){const target=document.querySelector('.v212-panel');if(target)target.outerHTML=v212SettingsPanel();}
async function v212SessionToken(){const {data,error}=await f33Api.auth.getSession();if(error||!data?.session?.access_token)throw Error('Vuelve a iniciar sesión.');return data.session.access_token;}
async function v212Load(){
 if(!v212Enabled())return;
 try{
  const [l,e]=await Promise.all([
    f33Api.from('apple_pay_links').select('id,instrument_type,instrument_id,card_label,currency,active').eq('user_id',f33User.id).order('created_at',{ascending:false}).limit(100),
    f33Api.from('apple_pay_events').select('id,event_id,instrument_id,amount,merchant,currency,received_at,transaction_time,status').eq('user_id',f33User.id).in('status',['pending','review','imported']).order('received_at',{ascending:false}).limit(50)
  ]);
  if(l.error||e.error)throw(l.error||e.error);
  v212State.links=l.data||[];v212State.events=e.data||[];v212State.error='';v212State.loaded=true;
 }catch(e){v212State.error='No se pudo consultar Apple Pay: '+(e.message||'revisa tu conexión y permisos de Supabase')+(e.code?' ['+e.code+']':'');v212State.loaded=false;}
 v212Show();
}
function v212LinkError(payload, status, action){
 const raw=String(payload?.error||payload?.message||'').trim();
 if(/Falta X-Vive-Token|Vinculación inválida|Importe o comercio inválido/i.test(raw)){
  return `El servicio apple-pay-link está respondiendo como receptor de compras (HTTP ${status}). Revisa que apple-pay-link tenga SU propio código, no el de apple-pay-ingest. No cambies el token de Wallet para solucionar esto.`;
 }
 if(status===401||status===403){
  return `No se pudo ${action}: sesión no autorizada (HTTP ${status}). Cierra sesión y vuelve a entrar en Vive el Hoy.`;
 }
 if(status===404){
  return 'No se encuentra apple-pay-link (HTTP 404). Publica la función apple-pay-link en el mismo proyecto Supabase.';
 }
 return raw||`No se pudo ${action} (HTTP ${status}). Revisa la función apple-pay-link en Supabase.`;
}
async function v212LinkCall(method, body){
 const auth=await v212SessionToken();
 let response;
 try{
  response=await fetch(`${F33_URL}/functions/v1/apple-pay-link`,{
   method,
   headers:{Authorization:`Bearer ${auth}`,apikey:F33_KEY,'Content-Type':'application/json'},
   body:JSON.stringify(body)
  });
 }catch(err){throw Error('Sin conexión con apple-pay-link. Revisa Internet y la configuración de Supabase.');}
 const payload=await response.json().catch(()=>({}));
 if(!response.ok||payload?.ok===false)throw Error(v212LinkError(payload,response.status,method==='DELETE'?'desvincular':'vincular'));
 return payload;
}
async function v212Pair(){
 if(!v212Enabled())throw Error('Inicia sesión para conectar tarjetas');
 const id=document.getElementById('v212-card')?.value||v212State.selectedCard||db.cards.find(c=>!c.archived)?.id;
 const currency=document.getElementById('v212-currency')?.value||v212State.currency;
 if(!card(id)||!['DOP','USD'].includes(currency))throw Error('Selecciona una tarjeta y su moneda');
 if(v212State.busy)return;
 v212State.selectedCard=id;v212State.currency=currency;
 v212State.busy=true;v212State.error='';v212Show();
 try{
  const payload=await v212LinkCall('POST',{instrument_type:'card',instrument_id:id,currency,card_label:card(id)?.name||'Tarjeta'});
  if(!payload?.token||!payload?.webhook_url)throw Error('apple-pay-link respondió sin token o URL. Revisa su despliegue.');
  v212State.secret=payload.token;v212State.webhook=payload.webhook_url;
  v212State.health='testing';v212State.healthMessage='Vínculo creado. Comprobando si el receptor está publicado…';
  await v212Load();
  await v274ProbeAppleIngest(true);
  toast('Vínculo creado. Configura las variables Amount y Merchant en Atajos con la nueva clave.');
 }catch(err){v212State.error=err.message||'No fue posible generar el enlace';}
 finally{v212State.busy=false;v212Show();}
}
async function v274ProbeAppleIngest(silent=false){
 if(!v212State.secret||!v212State.webhook)throw Error('Vincula una tarjeta para obtener una clave de prueba nueva.');
 v212State.health='testing';v212State.healthMessage='Comprobando el endpoint sin guardar movimientos…';v212Show();
 const controller=new AbortController();
 const timeout=setTimeout(()=>controller.abort(),14000);
 try{
  const resp=await fetch(v212State.webhook,{
   method:'POST',headers:{'Content-Type':'application/json','X-Vive-Token':v212State.secret},
   body:JSON.stringify({amount:0.01,merchant:'PRUEBA CONEXION VIVE',currency:v212State.currency,dry_run:true}),
   signal:controller.signal,cache:'no-store'
  });
  const payload=await resp.json().catch(()=>({}));
  if(!resp.ok||payload?.ok!==true||payload?.dry_run!==true||payload?.linked!==true){
   let message=String(payload?.error||'').trim()||('HTTP '+resp.status);
   if(resp.status===404)message='No existe apple-pay-ingest en Supabase: publícala por separado de apple-pay-link.';
   else if(resp.status===401&&!(payload&&payload.code))message='El gateway de Supabase bloquea el atajo (401). En apple-pay-ingest desactiva Verify JWT; la función valida X-Vive-Token.';
   else if(payload?.code==='link_revoked')message='El token no coincide con el vínculo activo. Vuelve a vincular y actualiza Atajos.';
   throw Error(message);
  }
  v212State.health='ok';v212State.healthMessage='Supabase validó la clave y el vínculo. No se guardó ningún gasto. La inserción en la tabla de eventos y el atajo de iPhone se comprueban con una compra real.';
  if(!silent)toast('Receptor Apple Pay verificado. Prueba ahora un pago desde Atajos.');
  return true;
 }catch(err){
  v212State.health='error';
  v212State.healthMessage=err?.name==='AbortError'?'El receptor no respondió en 14 segundos. Revisa que apple-pay-ingest esté desplegada.':
    err instanceof TypeError?'Falló la conexión con el receptor. Comprueba la URL, CORS y la red.':(err?.message||'Error de receptor no identificado');
  if(!silent)toast(v212State.healthMessage);
  return false;
 }finally{clearTimeout(timeout);v212Show();}
}
async function v212Revoke(id){
 if(v212State.busy)return;
 if(!v212State.links.some(x=>x.id===id&&x.active))throw Error('El enlace ya no está activo. Pulsa Actualizar.');
 if(!confirm('¿Desvincular esta tarjeta de Apple Wallet? Las compras ya registradas se conservan.'))return;
 v212State.busy=true;v212State.error='';v212Show();
 try{
  await v212LinkCall('DELETE',{link_id:id});
  v212State.secret='';v212State.webhook='';v212State.health='unverified';v212State.healthMessage='Se revocó este vínculo; su token anterior ya no funcionará.';
  await v212Load();toast('Tarjeta desvinculada. Su token anterior queda desactivado.');
 }catch(err){v212State.error=err.message||'No se pudo desvincular';}
 finally{v212State.busy=false;v212Show();}
}
async function v212Mark(event,status,txId=''){
 const {error}=await f33Api.from('apple_pay_events').update({status,local_tx_id:txId||null,imported_at:status==='imported'?new Date().toISOString():null}).eq('id',event.id).eq('user_id',f33User.id).select('id').single();
 if(error)throw error;
}
function v212Date(iso){
 const valid=new Date(iso||'');if(!Number.isFinite(+valid))return today();
 const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Santo_Domingo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(valid);
 const f=k=>parts.find(p=>p.type===k)?.value||'';
 const out=`${f('year')}-${f('month')}-${f('day')}`;
 return out>today()?today():out;
}
function v212PossibleDuplicate(e,date){
 const amount=Number(e.amount),merchant=String(e.merchant||'').toLocaleLowerCase('es').trim();
 return db.transactions.some(t=>t.cardId===e.instrument_id&&t.type==='card_charge'&&t.currency===e.currency&&t.date===date&&Math.abs(num(t.amount)-amount)<0.01&&(String(t.payee||'').toLocaleLowerCase('es').includes(merchant)||String(t.note||'').toLocaleLowerCase('es').includes(merchant)));
}
function v274GuessAppleCategory(e){
 const normalize=v=>String(v||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es').replace(/[^\p{L}\p{N}]+/gu,' ').trim();
 const merchant=normalize(e.merchant);
 if(!merchant)return null;
 const examples=(db.transactions||[]).filter(t=>
  t.type==='card_charge' && t.category && normalize(t.payee||t.note).includes(merchant) &&
  !t.applePayEventId && !t.deleted
 );
 const votes=new Map();
 for(const t of examples){const key=String(t.category)+'\u0000'+String(t.subcategory||'');votes.set(key,(votes.get(key)||0)+1)}
 const sorted=[...votes].sort((a,b)=>b[1]-a[1]);
 // Only reuse a category the user already selected consistently for this merchant.
 if(!sorted.length||sorted[0][1]<2||(sorted[1]&&sorted[1][1]>=sorted[0][1]))return null;
 const [category,subcategory]=sorted[0][0].split('\u0000');
 return {category,subcategory};
}
async function v212ImportEvent(e,forced=false){
 if(!v212Enabled()||f33Dirty||f33Saving||f33Conflict)return false;
 const existing=db.transactions.find(t=>t.applePayEventId===e.id);
 if(existing){await v212Mark(e,'imported',existing.id);return true;}
 const c=card(e.instrument_id),date=v212Date(e.transaction_time||e.received_at),amount=Number(e.amount);
 if(!c||c.archived||!['DOP','USD'].includes(e.currency)||!Number.isFinite(amount)||amount<=0){
  await v212Mark(e,'review');return false;
 }
 if(!forced&&v212PossibleDuplicate(e,date)){await v212Mark(e,'review');return false;}
 const suggested=v274GuessAppleCategory(e);
 const tx={id:e.id,created:new Date().toISOString(),date,type:'card_charge',amount:rnd(amount),currency:e.currency,cardId:c.id,accountId:'',toAccountId:'',loanId:'',category:suggested?.category||'Compras personales',subcategory:suggested?.subcategory||'',note:`Apple Pay · ${String(e.merchant||'Comercio').slice(0,100)}`,payee:String(e.merchant||'Comercio').slice(0,100),tags:'apple-pay',reviewed:false,flowMode:'spend',paymentFlowMode:'spend',paymentChannel:'presencial',paymentService:'',paymentSource:'card',cardOnly:'no',paymentTax:0,paymentFee:0,fxRateSnapshot:num(db.settings.fx),applePayEventId:e.id,applePaySource:'wallet-shortcuts',applePayReceivedAt:e.received_at,applePayTransactionTime:e.transaction_time||null};
 db.transactions.push(tx);
 if(!persist()){db.transactions=db.transactions.filter(t=>t.id!==tx.id);return false;}
 await f33Flush();
 if(f33Dirty||f33Saving||f33Conflict)throw Error('La compra está pendiente de confirmar en la nube. Resuelve la sincronización; no la registres manualmente de nuevo.');
 await v212Mark(e,'imported',tx.id);
 if(!document.querySelector('#modal-root .modal-layer'))render();
 return true;
}
async function v212Sync(){
 if(!v212Enabled()||v212Busy)return;
 if(f33Dirty||f33Saving||f33Conflict||!navigator.onLine){v212State.syncError=f33Conflict?'Apple Pay en espera: resuelve el conflicto de sincronización de la app.':!navigator.onLine?'Apple Pay en espera: sin conexión.':'Apple Pay en espera: hay cambios de la app pendientes de guardar.';v212Show();return;}
 v212State.syncError='';v212Busy=true;
 try{
  const result=await f33Api.from('apple_pay_events').select('id,event_id,instrument_id,amount,merchant,currency,received_at,transaction_time,status').eq('user_id',f33User.id).eq('status','pending').order('received_at',{ascending:true}).limit(30);
  if(result.error)throw result.error;
  let added=0;
  for(const e of result.data||[]){
   if(f33Dirty||f33Saving||f33Conflict)break;
   if(await v212ImportEvent(e))added++;
  }
  if(added)toast(`${added} compra${added===1?'':'s'} de Apple Pay registrada${added===1?'':'s'} en tus tarjetas.`);
 }catch(err){v212State.syncError='No se pudo sincronizar Apple Pay: '+(err.message||String(err));console.warn('Sincronización Apple Pay:',err.message||err);v212Show();}
 finally{v212Busy=false;v212State.lastSync=new Date().toISOString();if(ui.page==='settings')await v212Load();}
}
// La interfaz utiliza un controlador propio, sin cambiar los flujos existentes.
document.addEventListener('click',async ev=>{
 const el=ev.target.closest('[data-v212]');if(!el)return;
 ev.preventDefault();const act=el.dataset.v212;
 try{
  if(act==='pair')await v212Pair();
  if(act==='test-ingest')await v274ProbeAppleIngest();
  if(act==='revoke')await v212Revoke(el.dataset.id);
  if(act==='refresh'){if(f33Dirty&&!f33Conflict)await f33Flush();await v212Load();await v212Sync();}
  if(act==='copy-url'||act==='copy-token'){
   const value=act==='copy-url'?v212State.webhook:v212State.secret;
   if(!value)throw Error('Primero conecta una tarjeta');
   await navigator.clipboard.writeText(value);toast('Copiado. Pégalo en el atajo de Wallet.');
  }
  if(act==='ignore'||act==='force'){
   const e=v212State.events.find(q=>q.id===el.dataset.id);if(!e)throw Error('Actualiza la bandeja.');
   if(act==='ignore'){await v212Mark(e,'ignored');toast('Compra ignorada sin alterar saldos.');}
   else {if(v212Busy)throw Error('Hay una sincronización en curso; espera a que termine.');v212Busy=true;try{if(!await v212ImportEvent(e,true))throw Error('No se pudo contabilizar. Comprueba la tarjeta, la moneda y la sincronización de Supabase.');}finally{v212Busy=false;}}
   await v212Load();
  }
 }catch(err){v212State.error=err.message||'No se pudo completar la operación';v212Show();toast(v212State.error);}
});
document.addEventListener('change',ev=>{if(ev.target.id==='v212-card')v212State.selectedCard=ev.target.value;if(ev.target.id==='v212-currency')v212State.currency=ev.target.value;});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&v212Enabled()){v212Sync();}});
window.addEventListener('online',()=>{if(v212Enabled())v212Sync();});
setInterval(()=>{if(!document.hidden&&v212Enabled())v212Sync();},45000);

/* V219 | Informes internos de solo lectura. Los datos financieros no se mutan.
   Cada período queda habilitado a las 19:00 de America/Santo_Domingo.
   No confundir estos informes recalculables con snapshots ni push programado. */
const V216_TZ='America/Santo_Domingo', V216_CUTOFF=19;
function v216NowParts(){
 const map={};
 try{
  const parts=new Intl.DateTimeFormat('en-CA',{timeZone:V216_TZ,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',hourCycle:'h23'}).formatToParts(new Date());
  for(const part of parts)map[part.type]=part.value;
 }catch(err){
  const date=new Date();map.year=String(date.getFullYear());map.month=String(date.getMonth()+1).padStart(2,'0');map.day=String(date.getDate()).padStart(2,'0');map.hour=String(date.getHours());
 }
 return {date:`${map.year}-${map.month}-${map.day}`,hour:Number(map.hour)};
}
function v216Shift(iso,days){
 const d=new Date(`${iso}T12:00:00Z`);
 if(!Number.isFinite(d.getTime()))return iso;
 d.setUTCDate(d.getUTCDate()+days);
 return d.toISOString().slice(0,10);
}
function v216ClosedDay(){const n=v216NowParts();return n.hour>=V216_CUTOFF?n.date:v216Shift(n.date,-1)}
function v216Currency(amount){return money(rnd(amount),'DOP',2)}
function v216Period(kind,closed=v216ClosedDay()){
 const y=Number(closed.slice(0,4)),m=Number(closed.slice(5,7)),day=Number(closed.slice(8,10));
 const first=closed.slice(0,7)+'-01';
 const wd=(new Date(closed+'T12:00:00Z').getUTCDay()+6)%7;
 if(kind==='diario')return {title:'Resumen diario',start:closed,end:closed};
 if(kind==='semanal')return {title:'Resumen semanal',start:v216Shift(closed,-wd),end:closed};
 if(kind==='quincenal')return {title:day<=15?'Primera quincena':'Segunda quincena',start:day<=15?first:closed.slice(0,7)+'-16',end:closed};
 if(kind==='mitad'){
  const firstOfPeriod=day>=15?first:v216Shift(first,-1).slice(0,7)+'-01';
  return {title:'Corte de mitad de mes',start:firstOfPeriod,end:firstOfPeriod.slice(0,7)+'-15'};
 }
 if(kind==='cierre'){
  if(closed===periodEnd(y,m))return {title:'Cierre mensual',start:first,end:closed};
  const prevEnd=v216Shift(first,-1);
  return {title:'Cierre mensual anterior',start:prevEnd.slice(0,7)+'-01',end:prevEnd};
 }
 if(kind==='corte')return {title:'Corte financiero · 7:00 p. m.',start:closed,end:closed};
 return {title:'Acumulado mensual',start:first,end:closed};
}
function v216Types(closed=v216ClosedDay()){
 const types=['diario','semanal','quincenal','acumulado','corte'];
 const day=Number(closed.slice(8,10));
 if(day===15)types.push('mitad');
 if(closed===periodEnd(Number(closed.slice(0,4)),Number(closed.slice(5,7))))types.push('cierre');
 return types;
}
function v216Amounts(start,end){
 let income=0,expense=0,count=0,appleCount=0;const byCategory={};
 const convert=(v,c,rate)=>num(v)*(c==='USD'?num(rate)||num(db.settings.fx):1);
 const addExpense=(v,cat)=>{expense+=v;byCategory[cat]=(byCategory[cat]||0)+v;};
 for(const t of db.transactions||[]){
  if(typeof t.date!=='string'||t.date<start||t.date>end)continue;
  count++;
  if(t.applePayEventId||t.applePaySource==='wallet-shortcuts'||String(t.tags||'').split(',').includes('apple-pay'))appleCount++;
  const rate=t.fxRateSnapshot||db.settings.fx,ccy=t.currency||'DOP',value=convert(t.amount,ccy,rate);
  const feeCcy=t.paymentFeeCurrency||account(t.accountId)?.currency||ccy;
  if(['income','card_reward','bank_reward'].includes(t.type))income+=value;
  if(['expense','card_charge','card_refund'].includes(t.type))addExpense(t.type==='card_refund'?-value:value,t.category||'Otros gastos');
  if(['expense','card_payment'].includes(t.type)){
   const cost=convert(num(t.paymentTax)+num(t.paymentFee),feeCcy,rate);
   if(cost)addExpense(cost,'Impuestos y comisiones');
  }
  if(t.type==='loan_payment'){
   const cost=convert(num(t.interest)+num(t.fee)+num(t.insurance),ccy,rate);
   if(cost)addExpense(cost,'Deudas e intereses');
   const tax=convert(num(t.paymentTax)+num(t.paymentFee),feeCcy,rate);
   if(tax)addExpense(tax,'Impuestos y comisiones');
  }
  if(t.type==='transfer'){
   const cost=convert(num(t.transferFee),account(t.accountId)?.currency||ccy,rate);
   if(cost)addExpense(cost,'Impuestos y comisiones');
  }
  if(t.type==='personal_settlement'){
   const relation=personalLoan(t.personalLoanId);
   const interest=convert(t.interest,ccy,rate);
   if(relation?.direction==='lent')income+=interest;
   else if(relation?.direction==='borrowed'&&interest)addExpense(interest,'Deudas e intereses');
  }
 }
 return {income:rnd(income),expense:rnd(expense),net:rnd(income-expense),count,appleCount,byCategory};
}
function v216Previous(p){
 const length=Math.max(1,Math.round((Date.parse(p.end+'T12:00:00Z')-Date.parse(p.start+'T12:00:00Z'))/86400000)+1);
 const end=v216Shift(p.start,-1);
 return {start:v216Shift(end,1-length),end};
}
function v216Due(closed=v216ClosedDay()){
 return upcoming().filter(o=>o.kind!=='personal_recv'&&num(o.amount)>0&&/^\d{4}-\d{2}-\d{2}$/.test(String(o.date||''))&&o.date<=v216Shift(closed,30)).sort((a,b)=>a.date.localeCompare(b.date));
}
function v216Insights(current,previous,closed,dues,liquid){
 const list=[];
 const dueSoon=dues.filter(o=>o.date>=closed&&o.date<=v216Shift(closed,7));
 const overdue=dues.filter(o=>o.date<closed);
 if(overdue.length)list.push({danger:true,text:`Hay ${overdue.length} vencimiento(s) atrasado(s). Revisa si ya fueron pagados y registra los abonos para actualizar las cifras.`});
 if(current.net<0)list.push({danger:true,text:`Los egresos superan los ingresos por ${v216Currency(-current.net)}. Prioriza pagos esenciales y revisa los gastos variables.`});
 else if(current.income>0)list.push({text:`El período registra un balance positivo de ${v216Currency(current.net)}. Considera reservar parte para próximos compromisos.`});
 if(dueSoon.length){
  const total=dueSoon.reduce((sum,o)=>sum+fx(num(o.amount),o.currency||'DOP'),0);
  list.push({danger:liquid<total,text:`Vencen ${dueSoon.length} compromiso(s) en 7 días, por ${v216Currency(total)}${liquid<total?'; la liquidez actual no alcanza para cubrirlos.':'.'}`});
 }
 if(previous.expense>0&&current.expense>previous.expense*1.2){
  const pct=(current.expense/previous.expense-1)*100;
  list.push({danger:true,text:`Los egresos aumentaron ${pct.toFixed(1)}% respecto de un período anterior de igual duración. Identifica los cargos que explican la diferencia.`});
 }
 const biggest=Object.entries(current.byCategory).filter(([,v])=>v>0).sort((a,b)=>b[1]-a[1])[0];
 if(biggest)list.push({text:`Principal categoría de gastos: ${biggest[0]} (${v216Currency(biggest[1])}). Evalúa si existe margen para reducir gastos sin afectar lo esencial.`});
 if(!current.count)list.push({text:'Sin movimientos registrados en este período: las métricas pueden estar incompletas.'});
 return list.slice(0,6);
}
function v216Modal(kind){
 const closed=v216ClosedDay(),p=v216Period(kind,closed),a=v216Amounts(p.start,p.end);
 const prev=v216Previous(p),b=v216Amounts(prev.start,prev.end),delta=a.net-b.net;
 const dues=v216Due(closed),due7=dues.filter(o=>o.date>=closed&&o.date<=v216Shift(closed,7));
 const overdue=dues.filter(o=>o.date<closed);
 const sumDue=due7.reduce((n,o)=>n+fx(num(o.amount),o.currency||'DOP'),0);
 const personal=personalTotals();
 const debt=rnd(totalCardDebt()+totalLoanDebt()+num(personal.payable));
 const liquid=totalLiquid();
 const position=rnd(liquid+totalCertificates()+num(personal.receivable)-debt);
 const pct=b.net!==0?`${delta>=0?'+':''}${(100*delta/Math.abs(b.net)).toFixed(1)}%`:'Sin base comparable';
 const items=v216Insights(a,b,closed,dues,liquid).map(x=>`<li class="${x.danger?'v216-critical':''}">${sanitize(x.text)}</li>`).join('');
 const shown=[...overdue.slice(0,3),...dues.filter(o=>o.date>=closed).slice(0,7)].slice(0,10);
 const rows=shown.map(o=>`<div class="v216-due"><span><strong>${sanitize(o.name||'Compromiso')}</strong><small>${prettyDate(o.date)}${o.date<closed?' · Vencido':''}</small></span><b>${money(o.amount,o.currency,2)}</b></div>`).join('');
 const chips=['diario','semanal','quincenal','mitad','corte','cierre','acumulado'].map(k=>`<button type="button" class="${k===kind?'current':''}" data-v216="report" data-kind="${k}" aria-pressed="${k===kind}">${sanitize(v216Period(k,closed).title)}</button>`).join('');
 document.getElementById('v216-layer')?.remove();
 const layer=document.createElement('div');layer.id='v216-layer';layer.className='v216-overlay';
 layer.innerHTML=`<section class="v216-report" role="dialog" aria-modal="true" aria-labelledby="v216-title" tabindex="-1"><header class="v216-report-head"><div><div class="v216-eyebrow">VIVE EL HOY · INTELIGENCIA FINANCIERA</div><h2 id="v216-title">${sanitize(p.title)}</h2><p>${prettyDate(p.start)}${p.start===p.end?'':' – '+prettyDate(p.end)} · Corte diario 7:00 p. m. (RD)</p></div><button class="v216-close" type="button" data-v216="close" aria-label="Cerrar informe">×</button></header><nav class="v216-periods" aria-label="Seleccionar período">${chips}</nav><div class="v216-report-body"><div class="v216-metrics"><article><small>Ingresos</small><strong>${v216Currency(a.income)}</strong></article><article><small>Egresos</small><strong>${v216Currency(a.expense)}</strong></article><article><small>Balance del período</small><strong class="${a.net<0?'v216-negative':'v216-positive'}">${v216Currency(a.net)}</strong></article></div><div class="v216-metrics v216-secondary"><article><small>Posición neta estimada actual</small><strong>${v216Currency(position)}</strong></article><article><small>Deudas totales actuales</small><strong>${v216Currency(debt)}</strong><small>Tarjetas, préstamos y deudas personales</small></article><article><small>Vencimientos próximos 7 días</small><strong>${v216Currency(sumDue)}</strong></article></div><section class="v216-report-section"><h3>Evolución financiera</h3><div class="v216-compare"><div><small>Balance del período anterior comparable</small><b>${v216Currency(b.net)}</b></div><div><small>Variación del balance</small><b class="${delta<0?'v216-negative':'v216-positive'}">${v216Currency(delta)} · ${pct}</b></div><div><small>Ingresos del período anterior</small><b>${v216Currency(b.income)}</b></div><div><small>Egresos del período anterior</small><b>${v216Currency(b.expense)}</b></div></div><p class="v216-note">Comparación con los ${Math.round((Date.parse(p.end+'T12:00:00Z')-Date.parse(p.start+'T12:00:00Z'))/86400000)+1} días inmediatamente anteriores. No se contabilizan transferencias internas como ingresos ni pagos de capital como gasto adicional.</p></section><section class="v216-report-section"><h3>Alertas y recomendaciones</h3><ul class="v216-insights">${items}</ul></section><section class="v216-report-section"><h3>Compromisos y vencimientos</h3>${rows||'<p class="v216-note">No hay vencimientos pendientes registrados en los próximos 30 días ni atrasos vigentes.</p>'}<button type="button" class="v216-link" data-v216="payments">Abrir compromisos</button></section><footer class="v216-report-foot"><span>${a.count} movimiento(s) · ${a.appleCount} Apple Pay</span><span>Datos registrados al abrir · este informe se recalcula si editas movimientos</span></footer></div></section>`;
 document.body.append(layer);layer.querySelector('.v216-report')?.focus();document.body.classList.add('v216-modal-open');
}
function v216BellItems(){
 const closed=v216ClosedDay();
 return `<div class="v216-notice-title" role="heading" aria-level="3">INFORMES FINANCIEROS · 7:00 P. M.</div>${v216Types(closed).map(k=>{const p=v216Period(k,closed);return `<button type="button" class="v216-notice" data-v216="report" data-kind="${k}"><span class="v216-notice-icon" aria-hidden="true">↗</span><span class="v216-notice-copy"><strong>${sanitize(p.title)}</strong><small>${prettyDate(p.start)}${p.start!==p.end?' – '+prettyDate(p.end):''} · Ver informe ejecutivo</small></span><span aria-hidden="true">›</span></button>`}).join('')}`;
}
function v216Close(){document.getElementById('v216-layer')?.remove();document.body.classList.remove('v216-modal-open')}
document.addEventListener('click',e=>{
 const action=e.target?.closest?.('[data-v216]');
 if(action){
  e.preventDefault();e.stopPropagation();const command=action.dataset.v216;
  if(command==='report'){
   const kind=action.dataset.kind||'corte',end=action.dataset.end||'';
   if(end && !v246EligibleEvent(kind,end))return;
   if(action.dataset.reportId)v246MarkReportRead(action.dataset.reportId);
   document.querySelector('.v36-notifications[open]')?.removeAttribute('open');
   v216Modal(kind,end);
  }
  if(command==='close')v216Close();
  if(command==='payments'){v216Close();ui.page='payments';render()}
  return;
 }
 if(e.target.id==='v216-layer')v216Close();
},true);
document.addEventListener('keydown',e=>{
 const modal=document.getElementById('v216-layer');if(!modal)return;
 if(e.key==='Escape'){v216Close();return;}
 if(e.key==='Tab'){
  const focusables=[...modal.querySelectorAll('button:not([disabled]),[href],input:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(el=>el.getClientRects().length);
  if(!focusables.length)return;
  const first=focusables[0],last=focusables[focusables.length-1];
  if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}
  else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}
 }
});
// Si la app permanece abierta, se actualiza al pasar el corte; no equivale a envío push.
let v216LastClosed=v216ClosedDay();
setInterval(()=>{
 const next=v216ClosedDay();
 if(next!==v216LastClosed){
  v216LastClosed=next;
  if(document.getElementById('app')?.children.length&&!document.getElementById('v216-layer')){
   render();toast('Tu resumen financiero al corte de las 7:00 p. m. está disponible en Notificaciones.');
  }
 }
},60000);

