/* V243 · Restrict origin tracking to actual Explore links. Do not modify bottom
   navigation or global route actions. */
document.addEventListener('click',function(e){
 const back=e.target.closest?.('[data-v243-explore-back]');
 if(back){
  e.preventDefault();e.stopImmediatePropagation();
  v243ExploreDestination=null;ui.page='mobilehub';render();window.scrollTo(0,0);return;
 }
 const link=e.target.closest?.('.v243-explore [data-act="navigate"][data-id]');
 if(link){v243ExploreDestination=link.dataset.id;return;}
 // Clear the contextual breadcrumb only when choosing a primary destination.
 if(e.target.closest?.('.vive-mobile-dock [data-act="navigate"],.sidebar [data-act="navigate"]'))v243ExploreDestination=null;
},true);

/* V243 · Top-bar visibility follows real document scroll, not component
   re-renders. It remains hidden until the beginning of the viewport. */
function v243SyncMobileTop(){
 const mobile=window.matchMedia('(max-width:790px)').matches;
 document.body.classList.toggle('v243-top-away',mobile&&window.scrollY>28);
}
window.addEventListener('scroll',v243SyncMobileTop,{passive:true});
window.addEventListener('resize',v243SyncMobileTop,{passive:true});
window.addEventListener('pageshow',v243SyncMobileTop,{passive:true});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',v243SyncMobileTop,{once:true});
else v243SyncMobileTop();

/* V243 · Four targeted notification report designs: all figures continue
   coming from the read-only V216 calculations and the original cutoffs. */
function v243NotificationReport(kind,reportEnd=''){
 // The selected entry is tied to its actual release date, not to today's latest period.
 const currentClosed=v216ClosedDay();
 const closed=/^\d{4}-\d{2}-\d{2}$/.test(reportEnd)&&reportEnd<=currentClosed?reportEnd:currentClosed;
 const p=v216Period(kind,closed),a=v216Amounts(p.start,p.end);
 const prev=v216Previous(p),b=v216Amounts(prev.start,prev.end),delta=a.net-b.net;
 // Obligations and net position are current; historical income/expense keep their own dates.
 const dues=v216Due(currentClosed),due7=dues.filter(x=>x.date>=currentClosed&&x.date<=v216Shift(currentClosed,7));
 const overdue=dues.filter(x=>x.date<currentClosed);
 const dueSum=due7.reduce((n,x)=>n+fx(num(x.amount),x.currency||'DOP'),0);
 const personal=personalTotals(),debt=rnd(totalCardDebt()+totalLoanDebt()+num(personal.payable));
 const liquid=totalLiquid(),position=rnd(liquid+totalCertificates()+num(personal.receivable)-debt);
 const classification={
  diario:{label:'RESUMEN DIARIO',title:'Así cerró tu día',desc:'Tus movimientos registrados, balance y próximos compromisos.',icon:'calendar'},
  corte:{label:'RESUMEN AL CORTE',title:'Tu corte financiero',desc:'Fotografía del día al horario de corte de las 7:00 p. m.',icon:'shield'},
  mitad:{label:'MITAD DE MES',title:'Tu primera mitad del mes',desc:'Los primeros quince días, su comportamiento y lo que sigue.',icon:'chart'},
  cierre:{label:'FIN DE MES',title:'Tu cierre mensual',desc:'Resultado mensual, comparación y compromisos por atender.',icon:'analytics'},
  semanal:{label:'CIERRE SEMANAL',title:'Tu semana, en perspectiva',desc:'Siete días de movimientos y compromisos, del lunes al domingo.',icon:'calendar'}
 }[kind];
 const dayCount=Math.max(1,Math.round((Date.parse(p.end+'T12:00:00Z')-Date.parse(p.start+'T12:00:00Z'))/86400000)+1);
 const pct=b.net!==0?`${delta>=0?'+':''}${(100*delta/Math.abs(b.net)).toFixed(1)}%`:'Sin base comparable';
 const topCats=Object.entries(a.byCategory||{}).filter(([,v])=>v>0).sort((x,y)=>y[1]-x[1]).slice(0,4);
 const catTotal=topCats.reduce((n,x)=>n+x[1],0);
 const categories=topCats.length?topCats.map(([label,value])=>`<div class="v243-cat-line"><div><strong>${sanitize(label)}</strong><b>${v216Currency(value)}</b></div><span class="v243-cat-track"><i style="width:${Math.max(2,Math.min(100,100*value/Math.max(1,catTotal))).toFixed(1)}%"></i></span></div>`).join(''):'<p class="v243-report-empty">Sin egresos clasificados registrados en este período.</p>';
 const compared=`<div class="v243-report-mini"><span>Balance anterior comparable</span><strong>${v216Currency(b.net)}</strong></div><div class="v243-report-mini"><span>Variación de balance</span><strong class="${delta<0?'v216-negative':'v216-positive'}">${v216Currency(delta)}</strong><small>${pct}</small></div>`;
 const currentDue=dues.filter(x=>x.date>=closed);
 const dueRows=[...overdue.slice(0,2),...currentDue.slice(0,5)].slice(0,7).map(o=>`<div class="v243-due-row"><span><strong>${sanitize(o.name||'Compromiso')}</strong><small>${prettyDate(o.date)}${o.date<closed?' · Vencido':''}</small></span><b>${money(o.amount,o.currency,2)}</b></div>`).join('');
 const stat=(label,value,sub='')=>`<article class="v243-report-stat"><small>${label}</small><strong>${value}</strong>${sub?`<span>${sub}</span>`:''}</article>`;
 let special='';
 if(kind==='diario')special=`<section class="v243-report-block"><div class="v243-report-block-head"><span class="v243-report-block-icon">${icon('chart')}</span><div><h3>En qué se movió tu dinero</h3><p>${a.count} operaciones registradas durante el día</p></div></div>${categories}</section>`;
 if(kind==='corte')special=`<section class="v243-report-block"><div class="v243-report-block-head"><span class="v243-report-block-icon">${icon('wallet')}</span><div><h3>Estado financiero actual</h3><p>Posición y obligaciones en el momento de consulta</p></div></div><div class="v243-report-dual">${stat('Fondos disponibles',v216Currency(liquid))}${stat('Deuda total',v216Currency(debt))}${stat('Posición neta estimada',v216Currency(position))}${stat('Próximos 7 días',v216Currency(dueSum))}</div></section>`;
 if(kind==='mitad')special=`<section class="v243-report-block"><div class="v243-report-block-head"><span class="v243-report-block-icon">${icon('chart')}</span><div><h3>Primera quincena en perspectiva</h3><p>${dayCount} días del período seleccionado</p></div></div><div class="v243-report-dual">${compared}</div><div class="v243-report-categories"><h4>Gastos principales</h4>${categories}</div></section>`;
 if(kind==='cierre')special=`<section class="v243-report-block"><div class="v243-report-block-head"><span class="v243-report-block-icon">${icon('analytics')}</span><div><h3>Cómo terminó el mes</h3><p>${dayCount} días contabilizados, según lo registrado</p></div></div><div class="v243-report-dual">${compared}</div><div class="v243-report-categories"><h4>Principales categorías</h4>${categories}</div></section>`;
 if(kind==='semanal')special=`<section class="v243-report-block"><div class="v243-report-block-head"><span class="v243-report-block-icon">${icon('chart')}</span><div><h3>Así evolucionó tu semana</h3><p>Balance de lunes a domingo · ${dayCount} días</p></div></div><div class="v243-report-dual">${compared}</div><div class="v243-report-categories"><h4>En qué se concentraron los gastos</h4>${categories}</div></section>`;
 const insights=v216Insights(a,b,currentClosed,dues,liquid);
 const tabs='';
 document.getElementById('v216-layer')?.remove();
 const layer=document.createElement('div');layer.id='v216-layer';layer.className='v216-overlay v243-report-overlay';
 layer.innerHTML=`<section class="v216-report v243-report" role="dialog" aria-modal="true" aria-labelledby="v216-title" tabindex="-1"><header class="v243-report-head"><div class="v243-report-brand">${icon(classification.icon)}<span>VIVE EL HOY · INFORMES FINANCIEROS</span></div><button type="button" class="v216-close" data-v216="close" aria-label="Cerrar informe">×</button><div class="v243-report-head-copy"><span>${classification.label}</span><h2 id="v216-title">${classification.title}</h2><p>${classification.desc}</p></div><div class="v243-report-dates"><span>${icon('calendar')} ${prettyDate(p.start)}${p.start===p.end?'':' — '+prettyDate(p.end)}</span><small>Corte 7:00 p. m. · República Dominicana</small></div></header><div class="v246-report-context"><span>${icon('check')} Informe liberado el ${prettyDate(closed)} · 7:00 p. m.</span><small>Período cerrado · RD</small></div><div class="v216-report-body v243-report-content"><div class="v243-report-hero"><span>BALANCE DEL PERÍODO</span><strong class="${a.net<0?'v216-negative':'v216-positive'}">${v216Currency(a.net)}</strong><p>Ingresos registrados menos egresos del período</p></div><div class="v243-report-core">${stat('Ingresos',v216Currency(a.income))}${stat('Egresos',v216Currency(a.expense))}${stat('Movimientos',String(a.count),'Registrados')}</div>${special}<section class="v243-report-block"><div class="v243-report-block-head"><span class="v243-report-block-icon">${icon('calendar')}</span><div><h3>Compromisos y fechas</h3><p>${overdue.length} vencidos · ${due7.length} próximos 7 días</p></div></div>${dueRows||'<p class="v243-report-empty">No hay vencimientos próximos registrados.</p>'}<button type="button" class="v216-link" data-v216="payments">Ver centro de pagos ${icon('arrow')}</button></section><section class="v243-report-block v243-report-advice"><div class="v243-report-block-head"><span class="v243-report-block-icon">${icon('shield')}</span><div><h3>Lo que merece atención</h3><p>Observaciones calculadas con tus registros</p></div></div><ul class="v216-insights">${insights.map(x=>`<li class="${x.danger?'v216-critical':''}">${sanitize(x.text)}</li>`).join('')}</ul></section><footer class="v216-report-foot"><span>${a.appleCount} movimiento(s) Apple Pay · ${a.count} movimiento(s) totales</span><span>Vista dinámica: no modifica tus registros.</span></footer></div></section>`;
 document.body.append(layer);layer.querySelector('.v216-report')?.focus();document.body.classList.add('v216-modal-open');
}
const v243PreviousReport=v216Modal;
v216Modal=function(kind,reportEnd=''){
 if(['diario','corte','mitad','cierre','semanal'].includes(kind))return v243NotificationReport(kind,reportEnd);
 return v243PreviousReport(kind);
};

/* V246 · Informes que aparecen gradualmente (hora oficial República Dominicana).
   No backfill: se empieza desde el primer uso de esta versión por perfil.
   Interno y recalculable: no altera el motor de cifras ni programa push. */
const V246_CATALOG={
 corte:{title:'Corte del día',caption:'Tu balance al cierre de la noche',icon:'calendar',priority:4},
 semanal:{title:'Cierre semanal',caption:'Lunes a domingo · semana concluida',icon:'chart',priority:2},
 mitad:{title:'Mitad de mes',caption:'Del día 1 al 15 · primera quincena',icon:'analytics',priority:1},
 cierre:{title:'Fin de mes',caption:'Resultado final del mes concluido',icon:'wallet',priority:0}
};
function v246ReportActivation(){
 const setting=String(db.settings?.v246ReportFeedStart||'');
 if(/^\d{4}-\d{2}-\d{2}$/.test(setting))return setting;
 const todayRD=v216NowParts().date;
 db.settings.v246ReportFeedStart=todayRD;
 // Date is nonfinancial metadata, synchronized with the normal app preferences.
 persist();
 return todayRD;
}
function v246ReportEvents(n=v216NowParts(),start=v246ReportActivation()){
 if(!/^\d{4}-\d{2}-\d{2}$/.test(start))return [];
 const closed=n.hour>=V216_CUTOFF?n.date:v216Shift(n.date,-1);
 if(closed<start)return [];
 const events=[];
 for(let i=0;i<46;i++){
  const day=v216Shift(closed,-i);if(day<start)break;
  const dow=new Date(day+'T12:00:00Z').getUTCDay();
  const d=Number(day.slice(-2)),y=Number(day.slice(0,4)),m=Number(day.slice(5,7));
  const ready=['corte'];
  if(dow===0)ready.push('semanal');     // Domingo, 7:00 p.m. RD
  if(d===15)ready.push('mitad');         // Día 15, 7:00 p.m. RD
  if(day===periodEnd(y,m))ready.push('cierre'); // Último día del mes, 7:00 p.m. RD
  for(const kind of ready){const label=V246_CATALOG[kind];events.push({id:kind+'|'+day,kind,date:day,...label});}
 }
 return events.sort((a,b)=>b.date.localeCompare(a.date)||a.priority-b.priority);
}
function v246ReadIds(){return Array.isArray(db.settings?.v246ReadReportIds)?db.settings.v246ReadReportIds:[];}
function v246UnreadReportCount(){
 const closed=v216ClosedDay(),weekAgo=v216Shift(closed,-6),read=new Set(v246ReadIds());
 return Math.min(9,v246ReportEvents().filter(r=>r.date>=weekAgo&&!read.has(r.id)).length);
}
function v246EligibleEvent(kind,end){return v246ReportEvents().some(e=>e.kind===kind&&e.date===end);}
function v246MarkReportRead(id){
 if(!id||v246ReadIds().includes(id))return;
 db.settings.v246ReadReportIds=[id,...v246ReadIds()].slice(0,160);
 persist();
 const urgent=v36DueItems().filter(o=>diffDays(o.date,today())<=7).length;
 const total=urgent+v123CategoryAlerts().length+v246UnreadReportCount();
 document.querySelectorAll('.v36-notifications>summary').forEach(notif=>{
  notif.setAttribute('aria-label',`Notificaciones: ${total} avisos`);
  let badge=notif.querySelector('.v36-notification-count');
  if(total){
   if(!badge){badge=document.createElement('span');badge.className='v36-notification-count';notif.append(badge);}
   badge.textContent=total>99?'99+':String(total);
  }else badge?.remove();
 });
 document.querySelectorAll(`[data-report-id="${id}"]`).forEach(b=>{b.classList.remove('v246-unread');b.querySelector('.v246-new')?.remove();});
}
function v246BellItems(){
 const events=v246ReportEvents(),recent=events.slice(0,3),older=events.slice(3),read=new Set(v246ReadIds());
 const row=e=>`<button type="button" class="v216-notice v246-notice v246-${e.kind} ${read.has(e.id)?'':'v246-unread'}" data-v216="report" data-kind="${e.kind}" data-end="${e.date}" data-report-id="${e.id}" aria-label="${e.title} del ${prettyDate(e.date)}; abrir informe">
 <span class="v246-notice-icon" aria-hidden="true">${icon(e.icon)}</span>
 <span class="v216-notice-copy v246-notice-copy"><strong>${e.title}</strong><small>${prettyDate(e.date)} · ${e.caption}</small></span>
 ${read.has(e.id)?'':`<span class="v246-new">Nuevo</span>`}<span class="v246-chevron" aria-hidden="true">${icon('arrow')}</span></button>`;
 const label='<div class="v246-inbox-heading"><span>CIERRES FINANCIEROS</span><small>Se liberan a las 7:00 p. m. · RD</small></div>';
 if(!events.length){
  const n=v216NowParts();const next=n.hour<V216_CUTOFF?'Hoy':'Mañana';
  return label+`<div class="v246-inbox-empty"><span class="v246-empty-icon">${icon('calendar')}</span><strong>Tu próximo corte está en camino</strong><p>${next} a las 7:00 p. m. aparecerá aquí el cierre diario. Los semanales y mensuales solo llegarán al terminar su período.</p></div>`;
 }
 return `${label}<div class="v246-current-feed">${recent.map(row).join('')}</div>${older.length?`<details class="v246-report-history"><summary>${icon('calendar')} Informes anteriores <b>${older.length}</b>${icon('arrow')}</summary><div class="v246-history-list">${older.map(row).join('')}</div></details>`:''}`;
}
v216BellItems=v246BellItems;

// If a suspended app regains focus after a cutoff, refresh the internal inbox.
let v246LastClosed=v216ClosedDay();
function v246RefreshAfterResume(){
 const now=v216ClosedDay();if(now===v246LastClosed||document.getElementById('v216-layer'))return;
 v246LastClosed=now;
 if(document.getElementById('app')?.children.length)render();
}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)v246RefreshAfterResume();});
window.addEventListener('focus',v246RefreshAfterResume,{passive:true});

 f33Boot();

/* V244 · Tarjetas móvil limpio + refinamiento transversal de módulos.
   Objetivo: igualar la claridad de Cuentas y efectivo en iPhone sin tocar los cálculos. */
(function(){
  const v244DesktopCards = pages.cards;
  function v244CardProduct(cardItem){
    const dop = cardStatus(cardItem,'DOP');
    const usd = cardStatus(cardItem,'USD');
    const limit = num(cardItem.limitDOP) + fx(num(cardItem.limitUSD),'USD');
    const debt = num(dop.debt) + fx(num(usd.debt),'USD');
    const available = Math.max(0,num(dop.availableWithOverdraft)) + Math.max(0,fx(Math.max(0,num(usd.availableWithOverdraft)),'USD'));
    const utilization = limit>0 ? (debt/limit)*100 : null;
    const nexts = [
      dop.nextDue ? {date:dop.nextDue, billed:dop.billed, ccy:'DOP'} : null,
      usd.nextDue ? {date:usd.nextDue, billed:usd.billed, ccy:'USD'} : null
    ].filter(Boolean).sort((a,b)=>String(a.date).localeCompare(String(b.date)));
    const next = nexts[0] || null;
    return `<article class="v244-product v244-card-item">
      <div class="v244-product-top">
        <span class="v244-logo">${icon('card')}</span>
        <span class="v244-product-meta"><strong>${sanitize(cardItem.name)}</strong><small>${sanitize(bankOf(cardItem))} · ${sanitize(CARD_TIER_NAMES[cardTierKey(cardItem)] || 'Tarjeta')}</small></span>
        <span class="v244-currency">•••• ${sanitize(cardItem.last4||'—')}</span>
      </div>
      <div class="v244-product-value"><small>LÍMITE TOTAL</small><strong>${money(limit)}</strong></div>
      <div class="v244-inline-metrics">
        <div><small>Deuda utilizada</small><b>${money(debt)}</b></div>
        <div><small>Disponible</small><b>${money(Math.max(0,available))}</b></div>
      </div>
      <div class="v244-product-foot"><span>${utilization===null?'Sin límite definido':utilization.toFixed(1)+'% utilizado'}${next?' · Próximo pago '+prettyDate(next.date):''}</span><button type="button" data-act="cardDetails" data-id="${sanitize(cardItem.id)}">Ver tarjeta ${icon('arrow')}</button></div>
    </article>`;
  }
  function v244CardsTx(tx){
    return tx.length ? `<div class="v244-history">${tx.slice(0,10).map(t=>{
      const incoming = ['card_payment','card_refund','card_reward'].includes(t.type);
      return `<div class="v244-history-row"><span class="v244-history-mark ${incoming?'positive':''}">${icon(incoming?'up':'down')}</span><span class="v244-history-copy"><strong>${sanitize(transactionTitle(t))}</strong><small>${prettyDate(t.date)} · ${sanitize(TRANSL[t.type]||t.type)}</small></span><b class="${incoming?'positive':''}">${incoming?'+':'−'}${money(num(t.amount),t.currency,2)}</b></div>`;
    }).join('')}</div>` : '<p class="v244-no-data">Aún no hay movimientos registrados en esta tarjeta.</p>';
  }
  function v244CardsMobile(){
    const visible = (db.cards||[]).filter(c=>ui.showHidden||!isHidden(c));
    const selected = ui.cardId ? card(ui.cardId) : null;
    const totalLimit = visible.reduce((s,c)=>s + num(c.limitDOP) + fx(num(c.limitUSD),'USD'),0);
    const totalDebt = visible.reduce((s,c)=>s + num(cardStatus(c,'DOP').debt) + fx(num(cardStatus(c,'USD').debt),'USD'),0);
    const totalAvailable = Math.max(0,totalLimit-totalDebt);
    const overallUtil = totalLimit>0 ? (totalDebt/totalLimit)*100 : null;
    if(selected){
      const dop = cardStatus(selected,'DOP');
      const usd = cardStatus(selected,'USD');
      const limit = num(selected.limitDOP) + fx(num(selected.limitUSD),'USD');
      const debt = num(dop.debt) + fx(num(usd.debt),'USD');
      const avail = Math.max(0,num(dop.availableWithOverdraft)) + Math.max(0,fx(Math.max(0,num(usd.availableWithOverdraft)),'USD'));
      const utilization = limit>0 ? (debt/limit)*100 : null;
      const tx = recentTx().filter(t=>t.cardId===selected.id);
      const benefitD = benefitBreakdown(selected,'DOP');
      const benefitU = benefitBreakdown(selected,'USD');
      const upcomingCuts = [
        {ccy:'RD$', cut:dop.cut, due:dop.nextDue, billed:dop.billed, debt:dop.debt},
        {ccy:'US$', cut:usd.cut, due:usd.nextDue, billed:usd.billed, debt:usd.debt, currency:'USD'}
      ].filter(x=>num(x.debt)||num(x.billed)||x.cut||x.due);
      return `<div class="v244-mobile-root v244-cards v244-detail-mode">
        <button class="v244-back" data-act="closeCardDetails">${icon('arrow')} Todas mis tarjetas</button>
        <section class="v244-hero v244-detail-hero"><span class="v244-hero-label">CRÉDITO PERSONAL · ${sanitize(bankOf(selected))}</span><h2>${sanitize(selected.name)}</h2><p>${sanitize(CARD_TIER_NAMES[cardTierKey(selected)]||'Tarjeta')} · •••• ${sanitize(selected.last4||'—')}</p><small>DEUDA UTILIZADA</small><strong>${money(debt)}</strong><div class="v244-hero-bottom"><span>${utilization===null?'Sin límite definido':utilization.toFixed(1)+'% del límite'}</span><span>${selected.network?sanitize(selected.network):'Crédito registrado'}</span></div></section>
        <div class="v244-actions"><button class="v244-action-primary" data-act="payCard" data-id="${sanitize(selected.id)}">${icon('card')} Registrar pago</button><button class="v244-action" data-act="cardHistory" data-id="${sanitize(selected.id)}">${icon('chart')} Ver histórico</button></div>
        <section class="v244-sheet"><h3>Resumen de crédito</h3><div class="v244-facts">${['Límite total|'+money(limit),'Disponible|'+money(Math.max(0,avail)),'Deuda RD$|'+money(dop.debt,'DOP',2),'Deuda US$|'+money(usd.debt,'USD',2)].map(x=>{const p=x.split('|');return `<div class="v244-fact"><span>${p[0]}</span><strong>${p[1]}</strong></div>`;}).join('')}</div><p class="v244-disclaimer">La deuda utilizada se calcula con tus movimientos registrados. Los montos en US$ se convierten a RD$ según la tasa configurada.</p></section>
        <section class="v244-sheet"><div class="v244-sheet-head"><h3>Cortes y próximos pagos</h3><span>${upcomingCuts.length}</span></div>${upcomingCuts.length?`<div class="v244-cut-list">${upcomingCuts.map(x=>`<article class="v244-cut-item"><strong>${x.ccy}</strong><div><small>Saldo actual</small><b>${money(x.debt,x.currency||'DOP',2)}</b></div><div><small>Facturado</small><b>${money(x.billed||0,x.currency||'DOP',2)}</b></div><div><small>Próximo pago</small><b>${x.due?prettyDate(x.due):'Sin fecha'}</b></div></article>`).join('')}</div>`:'<p class="v244-no-data">No hay cortes calculados todavía para esta tarjeta.</p>'}</section>
        <section class="v244-sheet"><div class="v244-sheet-head"><h3>Beneficios acreditados</h3><span>${money(num(benefitD.credited)+fx(num(benefitU.credited),'USD'))}</span></div><div class="v244-facts"><div class="v244-fact"><span>Cashback en RD$</span><strong>${money(benefitD.credited,'DOP',2)}</strong></div><div class="v244-fact"><span>Cashback en US$</span><strong>${money(benefitU.credited,'USD',2)}</strong></div></div></section>
        <section class="v244-sheet"><div class="v244-sheet-head"><h3>Actividad reciente</h3><span>${tx.length}</span></div>${v244CardsTx(tx)}</section>
        <details class="v244-more"><summary>Administrar esta tarjeta ${icon('arrow')}</summary><div class="v244-more-body">${productControls('card',selected.id,selected.archived)}</div></details>
      </div>`;
    }
    const scope = ui.v244Cards || 'all';
    const shown = visible.filter(c=> scope==='all' ? true : scope==='used' ? (num(cardStatus(c,'DOP').debt)+num(cardStatus(c,'USD').debt))>0.005 : (num(cardStatus(c,'DOP').debt)+num(cardStatus(c,'USD').debt))<=0.005);
    const visibility = db.cards.some(c=>c.archived) && typeof visibilityControl==='function' ? visibilityControl() : '';
    return `<div class="v244-mobile-root v244-cards">
      <header class="v244-intro"><div><span class="v244-eyebrow">TU CRÉDITO, MÁS CLARO</span><h2>Tarjetas</h2><p>Límites y deuda utilizada, sin ruido visual.</p></div><button class="v244-add" type="button" data-act="addCard" aria-label="Nueva tarjeta">${icon('plus')}<span>Nueva</span></button></header>
      <section class="v244-hero" aria-label="Resumen de tarjetas"><div class="v244-hero-top"><span class="v244-hero-label">LÍMITE TOTAL · RD$ EQUIVALENTES</span><span class="v244-hero-icon">${icon('card')}</span></div><strong class="v244-hero-amount">${money(totalLimit)}</strong><div class="v244-hero-metrics"><div><small>DEUDA UTILIZADA</small><strong>${money(totalDebt)}</strong></div><div><small>CRÉDITO DISPONIBLE</small><strong>${money(totalAvailable)}</strong></div></div><p class="v244-hero-footnote">${overallUtil===null?'Sin límites suficientes para calcular uso.':overallUtil.toFixed(1)+'% del límite comprometido'} · ${visible.length} ${visible.length===1?'tarjeta registrada':'tarjetas registradas'}.</p></section>
      <div class="v244-actions" aria-label="Acciones rápidas"><button class="v244-action-primary" data-act="guidedFlow" data-mode="cardpay">${icon('card')} Pagar</button><button class="v244-action" data-act="addCard">${icon('plus')} Nueva tarjeta</button></div>
      <div class="v244-list-head"><div><span class="v244-eyebrow">MIS PRODUCTOS</span><h3>Mis tarjetas <small>${visible.length}</small></h3></div>${visibility}</div>
      <div class="v244-segments" role="tablist" aria-label="Filtrar tarjetas"><button type="button" class="${scope==='all'?'selected':''}" data-v244-cards="all">Todas <small>${visible.length}</small></button><button type="button" class="${scope==='used'?'selected':''}" data-v244-cards="used">Con deuda <small>${visible.filter(c=>(num(cardStatus(c,'DOP').debt)+num(cardStatus(c,'USD').debt))>0.005).length}</small></button><button type="button" class="${scope==='free'?'selected':''}" data-v244-cards="free">Sin deuda <small>${visible.filter(c=>(num(cardStatus(c,'DOP').debt)+num(cardStatus(c,'USD').debt))<=0.005).length}</small></button></div>
      <div class="v244-product-list">${shown.length?shown.map(v244CardProduct).join(''):'<section class="v244-empty"><span>'+icon('card')+'</span><h3>No hay tarjetas para este filtro</h3><p>Prueba otro filtro o registra una nueva tarjeta.</p><button class="btn" data-act="addCard">Crear tarjeta</button></section>'}</div>
      <p class="v244-bottom-note">Wallet mantiene su experiencia visual propia. Esta vista está pensada para gestión rápida y lectura limpia dentro de Bancos.</p>
    </div>`;
  }
  document.addEventListener('click',function(e){
    const seg = e.target.closest('[data-v244-cards]');
    if(!seg) return;
    e.preventDefault();
    ui.v244Cards = seg.dataset.v244Cards || 'all';
    render();
  },true);
  pages.cards = () => isMobileViewport() ? v244CardsMobile() : v244DesktopCards();
})();

