/* V252 · Compromisos: arquitectura visual coherente con Cuentas y efectivo.
   Traslada controles DOM existentes y conserva sus data-act y eventos. */
(function(){
  'use strict';
  function make(tag,cl,text){const e=document.createElement(tag);e.className=cl||'';if(text!==undefined)e.textContent=text;return e;}
  function header(kicker,title,description){
    const h=make('header','v252-module-heading');
    const intro=make('div','v252-module-heading-copy');
    intro.append(make('span','v252-kicker',kicker),make('h2','',title),make('p','',description));
    h.append(intro);return h;
  }
  function heroStart(kicker,title){
    const el=make('section','v252-hero');
    el.setAttribute('aria-label',title);
    el.append(make('span','v252-hero-kicker',kicker));
    return el;
  }
  function polishPayments(){
    const root=document.getElementById('v145-payment-center');
    if(!root||root.dataset.v252Ready)return;
    const old=root.querySelector(':scope > .v145-pay-hero');
    const originalTiles=root.querySelector(':scope > .v145-payment-kpis');
    const main=old?.querySelector('.v245-pay-amount')||originalTiles?.children[0];
    let metrics=old?.querySelector('.v245-pay-summary');
    if(!metrics&&originalTiles?.children.length>=4){
      metrics=make('div','v245-pay-summary');
      metrics.append(originalTiles.children[1],originalTiles.children[1]);
    }
    if(!old||!main||!metrics)return;
    main.classList.add('v245-pay-amount');
    if(originalTiles?.children.length){
      const extra=make('details','v245-pay-extra');
      extra.append(make('summary','','Ver ingresos considerados y demás indicadores'));
      extra.append(originalTiles);root.insertBefore(extra,root.querySelector('.v145-pay-quick'));
    }
    const newHead=header('TUS COMPROMISOS','Centro de pagos','Vencimientos, cuotas y obligaciones en un solo lugar.');
    const period=old.querySelector('.v145-period-control');
    if(period){const wrap=make('div','v252-month-picker');wrap.append(period);newHead.append(wrap);}
    const hero=heroStart('COMPROMISOS DEL MES','Compromisos del mes');
    const title=make('h3','v252-hero-title','Tu agenda, bajo control.');
    hero.append(title,main,metrics);
    const cap=old.querySelector('.v145-debt-indicator');
    if(cap){const badge=make('div','v252-capacity');badge.append(cap);hero.append(badge);}
    old.replaceWith(newHead,hero);
    root.classList.add('v252-center');
    const actions=root.querySelector('.v145-pay-quick');
    if(actions){actions.classList.add('v252-quick');const label=actions.querySelector('.v145-pay-quick-title');if(label){label.innerHTML='<span class="v252-kicker">ACCIONES</span><strong>Gestiona un pago</strong>';}}
    const heading=root.querySelector('.v145-payment-section-head');
    if(heading){heading.classList.add('v252-group-heading');const p=heading.querySelector('p');if(p)p.textContent='Selecciona una categoría para filtrar los vencimientos.';}
    root.querySelector('.v145-pay-cardgrid')?.classList.add('v252-group-grid');
    root.querySelector('.v145-pay-lower')?.classList.add('v252-schedule');
    root.dataset.v252Ready='1';
  }
  function recurring(){
    const root=document.querySelector('#page .v26-internal[data-module="recurring"]');
    if(!root||root.dataset.v252Ready)return;
    const body=root.querySelector(':scope > .v26-body');
    if(!body)return;
    const oldHead=root.querySelector(':scope > .v26-head');
    const fresh=header('PAGOS RECURRENTES','Suscripciones','Servicios, próximos cargos y pagos registrados.');
    const add=oldHead?.querySelector('button[data-act="addRecurring"]');
    if(add){add.classList.add('v252-add');fresh.append(add);}
    if(oldHead)oldHead.replaceWith(fresh);else root.insertBefore(fresh,root.firstChild);
    const tabs=root.querySelector(':scope > .v26-nav');if(tabs)tabs.classList.add('v252-tabs');
    // Las pestañas internas conservan su renderización y filtros propios.
    const oldHero=body.querySelector(':scope > .v245-recurring-hero');
    const duplicate=body.querySelector(':scope > .v58-exec');
    if(oldHero){
      const amount=oldHero.querySelector('.v245-hero-total');
      const sides=oldHero.querySelector('.v245-hero-sides');
      const hero=heroStart('COSTO RECURRENTE · EQUIVALENTE MENSUAL','Costo recurrente mensual');
      hero.append(make('h3','v252-hero-title','Lo que mantienes activo.'));
      if(amount){amount.classList.add('v252-hero-value');hero.append(amount);}
      if(sides){sides.classList.add('v252-hero-sides');hero.append(sides);}
      hero.append(make('p','v252-hero-note','Importe mensual equivalente; no representa deuda acumulada.'));
      oldHero.replaceWith(hero);
    } else if(duplicate){
      // Escritorio: reutilizar el importe ya calculado en el KPI anterior.
      const feature=duplicate.querySelector('.v58-feature');
      const hero=heroStart('COSTO RECURRENTE · EQUIVALENTE MENSUAL','Costo recurrente mensual');
      hero.append(make('h3','v252-hero-title','Lo que mantienes activo.'));
      if(feature){feature.classList.add('v252-recurring-value');hero.append(feature);}
      const active=(db.recurring||[]).filter(x=>x.active!==false);
      const future=active.filter(x=>x.nextDue).slice().sort((a,b)=>String(a.nextDue).localeCompare(String(b.nextDue)))[0];
      const sides=make('div','v252-hero-sides');
      const stat=(label,val)=>{const span=make('span','');span.append(make('small','',label),make('b','',String(val)));return span;};
      sides.append(stat('SERVICIOS ACTIVOS',active.length),stat('PRÓXIMO CARGO',future?prettyDate(future.nextDue):'Sin fecha'));
      hero.append(sides,make('p','v252-hero-note','Importe mensual equivalente; no representa deuda acumulada.'));
      duplicate.before(hero);
    }
    if(duplicate){
      const fold=make('details','v252-additional-metrics');
      fold.append(make('summary','', 'Ver análisis y desglose del costo recurrente'));
      duplicate.replaceWith(fold);fold.append(duplicate);
    }
    let extra=body.querySelector(':scope > .v245-recurring-extra');
    if(!extra){
      // Escritorio también tiene lectura complementaria; plegar las cifras
      // repetidas sin perder acceso a botones ni a la agenda heredada.
      const redundant=[...body.children].filter(x=>x.matches('.section-title,.grid.kpis,.v149-rec-unified'));
      if(redundant.length){
        extra=make('details','v245-recurring-extra');
        extra.append(make('summary','','Más indicadores y agenda de pagos'));
        redundant.forEach(x=>extra.append(x));
        body.insertBefore(extra,body.querySelector('.v252-hero')?.nextSibling||body.firstChild);
      }
    }
    extra?.classList.add('v252-additional-metrics');
    const panel=body.querySelector('.v46-subs-panel');
    if(panel){panel.classList.add('v252-product-panel');const title=panel.querySelector('.v46-subs-head h3');if(title)title.textContent='Tus servicios';const info=panel.querySelector('.v46-subs-head p');if(info)info.textContent='Importe, frecuencia y próximo cargo por servicio.';}
    body.querySelector('.v46-subscriptions-grid')?.classList.add('v252-subscriptions');
    root.classList.add('v252-recurring');root.dataset.v252Ready='1';
  }
  function persons(){
    const root=document.querySelector('#page .v26-internal[data-module="personal"]');
    if(!root||root.dataset.v252Ready)return;
    const body=root.querySelector(':scope > .v26-body');if(!body)return;
    const oldHead=root.querySelector(':scope > .v26-head');
    const fresh=header('RELACIONES FINANCIERAS','Entre personas','Tus acuerdos, saldos pendientes y abonos.');
    const add=oldHead?.querySelector('button[data-act="addPersonal"]');
    if(add){add.classList.add('v252-add');add.innerHTML=icon('plus')+' Nueva relación';fresh.append(add);}
    if(oldHead)oldHead.replaceWith(fresh);else root.insertBefore(fresh,root.firstChild);
    root.querySelector(':scope > .v26-nav')?.classList.add('v252-tabs');
    const oldHero=body.querySelector(':scope > .v189-person-hero');
    if(oldHero){
      const metric=oldHero.querySelector('.v58-feature');
      const debt=oldHero.querySelector('.v189-payable-inline');
      const hero=heroStart('DINERO ENTRE PERSONAS · RD$ EQUIVALENTES','Saldo entre personas');
      hero.append(make('h3','v252-hero-title','Cada acuerdo, en su lugar.'));
      if(metric){metric.classList.add('v252-person-receivable');hero.append(metric);}
      // El balance neto no sustituye los importes separados: reutiliza los saldos de cada acuerdo.
      const entries=(db.personalLoans||[]).filter(x=>ui.showHidden||!x.archived);
      const receivable=entries.filter(x=>x.direction==='lent').reduce((sum,x)=>sum+fx(personalBalance(x),x.currency),0);
      const payable=entries.filter(x=>x.direction==='borrowed').reduce((sum,x)=>sum+fx(personalBalance(x),x.currency),0);
      const net=receivable-payable;
      const featureLabel=metric?.querySelector('.v58-main-label');
      const featureAmount=metric?.querySelector('.v58-main-value');
      if(featureLabel)featureLabel.textContent='BALANCE NETO · RD$ EQUIVALENTES';
      if(featureAmount)featureAmount.textContent=money(net,'DOP',2);
      const month=String(ui.month||today().slice(0,7)).slice(0,7);
      const monthPayments=(db.transactions||[]).filter(t=>t.type==='personal_settlement'&&String(t.date||'').startsWith(month));
      const lookup=new Map(entries.map(x=>[String(x.id),x]));
      const monthSum=direction=>monthPayments.reduce((sum,t)=>lookup.get(String(t.personalLoanId))?.direction===direction?sum+fx(Math.max(0,num(t.principal)),t.currency||lookup.get(String(t.personalLoanId)).currency):sum,0);
      const lower=make('div','v252-person-metrics v253-person-metrics');
      [['ME DEBEN',money(receivable)],['DEBO',money(payable)],['COBRADO · MES',money(monthSum('lent'))],['PAGADO · MES',money(monthSum('borrowed'))]].forEach(([label,value])=>{
        const item=make('div','v253-person-metric');
        item.append(make('span','',label),make('strong','',value));lower.append(item);
      });
      hero.append(lower);
      const note=make('p','v253-person-note',`${entries.length} acuerdos · Importes en RD$ equivalentes. Abonos registrados del período ${month}; las deudas perdonadas no cuentan como cobros.`);
      hero.append(note);
      oldHero.replaceWith(hero);
    }
    const ledger=body.querySelector('.v189-person-ledger');
    if(ledger){
      ledger.classList.add('v252-person-ledger');
      const h=ledger.querySelector('.v189-table-head h3');if(h)h.textContent='Tus relaciones';
      // Nueva relación también está disponible en el encabezado; no duplicarla.
      if(add){ledger.querySelector('.v189-table-head [data-act="addPersonal"]')?.remove();}
    }
    root.classList.add('v252-personal');root.dataset.v252Ready='1';
  }
  function decorate(){
    if(!document.getElementById('app'))return;
    if(ui.page==='payments')polishPayments();
    if(ui.page==='recurring')recurring();
    if(ui.page==='personal')persons();
  }
  const prev=render;
  render=function(...args){const result=prev.apply(this,args);decorate();return result;};
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',decorate,{once:true});
  else decorate();
})();


/* V254 · GASTOS HORMIGA — vista analítica, no transaccional.
   No crea categorías ni vuelve a registrar gastos. */
const ANT_PREFS_KEY='vive_el_hoy_ant_preferences_v254';
const ANT_DEFAULTS={maxUnitDop:1500,minRepetitions:3,excluded:[],forced:[]};
const antUi={tab:'habits',sort:'frequency',selected:null,search:'',showRules:false};
function antPrefs(){
 if(!db.settings.antExpenses){
  let local=null;
  try{local=JSON.parse(localStorage.getItem(ANT_PREFS_KEY)||'null')}catch(_e){}
  db.settings.antExpenses={...ANT_DEFAULTS,...(local&&typeof local==='object'?local:{})};
 }
 const p=db.settings.antExpenses;
 p.excluded=Array.isArray(p.excluded)?p.excluded:[];
 p.forced=Array.isArray(p.forced)?p.forced:[];
 return p;
}
function antRemember(){
 const p=antPrefs();
 // Preserve preferences on this device when cloud session is temporarily missing.
 try{localStorage.setItem(ANT_PREFS_KEY,JSON.stringify(p));}catch(_e){}
 const ok=persist();
 if(!ok)toast('Preferencia guardada en este dispositivo; pendiente de sincronización con tu cuenta.');
}
function antNormalize(v){
 return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'')
  .toLocaleLowerCase('es').replace(/[^\p{L}\p{N}\s]/gu,' ')
  .replace(/\b(\d{1,4}|rd|usd|dop|compra|pago|consumo|tarjeta|credito|debito|en|de|del|a|el|la|un|una|con|por|ref)\b/gu,' ')
  .replace(/\s+/g,' ').trim().slice(0,90);
}
function antIdentity(t){
 const merchant=String(t.merchant||'').trim();
 const note=String(t.note||t.description||'').trim();
 const sub=String(t.subcategory||'').trim();
 const generic=/^(otro(s)?( gastos?)?|sin (categoria|concepto)|comercio|compra|gasto|pago|consumo|pos|terminal|tarjeta|visa|mastercard|otros alimentos?)$/i;
 if(merchant && !generic.test(merchant) && antNormalize(merchant).length>=3){
  return {key:'m:'+antNormalize(merchant),label:merchant,origin:'Comercio'};
 }
 if(note && !generic.test(note) && antNormalize(note).length>=3){
  return {key:'n:'+antNormalize(note),label:note,origin:'Concepto'};
 }
 // Specific subcategories can signal an identifiable habit; never group
 // everything into the general default category.
 if(sub && /caf[eé]|meriendas|uber|taxi|delivery|snack|parqueo|pasajes|bebidas/i.test(sub)){
  return {key:'s:'+antNormalize(sub),label:sub,origin:'Subcategoría'};
 }
 return null;
}
function antFx(t){
 const rate=num(t.fxRateSnapshot)||num(db.settings.fx)||0;
 return num(t.amount)*(t.currency==='USD'?rate:1);
}
function antAnalyzedPeriod(){
 const key=/^\d{4}-(0[1-9]|1[0-2])$/.test(String(ui.month))?ui.month:today().slice(0,7);
 const [y,m]=key.split('-').map(Number);
 const start=periodStart(y,m),end=periodEnd(y,m),cutoff=end>today()?today():end;
 const daysInMonth=dateObj(end).getDate();
 return {key,y,m,start,end,cutoff,daysInMonth};
}
function antModel(){
 const p=antPrefs(),period=antAnalyzedPeriod();
 const firstDay=addDays(period.cutoff,-89),cutoff=period.cutoff;
 const byKey=new Map();
 const max=Math.max(1,Math.min(100000,Number(p.maxUnitDop)||1500));
 for(const t of db.transactions||[]){
  if(!['expense','card_charge','card_refund'].includes(t.type))continue;
  if(!/^\d{4}-\d{2}-\d{2}$/.test(String(t.date||'')))continue;
  if(t.date<firstDay||t.date>cutoff)continue;
  const identity=antIdentity(t);if(!identity)continue;
  const raw=antFx(t);
  if(!Number.isFinite(raw)||raw<=0||raw>max)continue;
  let entry=byKey.get(identity.key);
  if(!entry){entry={...identity,items:[],refunds:[]};byKey.set(identity.key,entry)}
  if(t.type==='card_refund')entry.refunds.push({...t,amountDop:raw});
  else entry.items.push({...t,amountDop:raw});
 }
 const minCount=Math.max(2,Math.min(30,Math.trunc(num(p.minRepetitions)||3)));
 const groups=[];
 for(const g of byKey.values()){
  const dates=[...new Set(g.items.map(t=>t.date))].sort();
  if(!g.items.length)continue;
  const forced=p.forced.includes(g.key);
  if(!forced && (g.items.length<minCount || dates.length<2 || dates[dates.length-1]<addDays(cutoff,-30)))continue;
  const daysObserved=Math.max(14,diffDays(cutoff,dates[0])+1);
  const count=g.items.length;
  const sumAll=g.items.reduce((s,t)=>s+t.amountDop,0)-g.refunds.reduce((s,t)=>s+t.amountDop,0);
  const monthItems=g.items.filter(t=>t.date>=period.start&&t.date<=cutoff);
  const monthRefunds=g.refunds.filter(t=>t.date>=period.start&&t.date<=cutoff);
  const real=Math.max(0,rnd(monthItems.reduce((s,t)=>s+t.amountDop,0)-monthRefunds.reduce((s,t)=>s+t.amountDop,0)));
  const gaps=dates.slice(1).map((d,i)=>diffDays(d,dates[i])).filter(x=>x>0).sort((a,b)=>a-b);
  const gap=gaps.length?(gaps.length%2?gaps[(gaps.length-1)/2]:(gaps[gaps.length/2-1]+gaps[gaps.length/2])/2):null;
  const pastCutoff=period.end<=today();
  const expected=rnd(Math.max(0,sumAll)/daysObserved*period.daysInMonth);
  const projected=pastCutoff?real:Math.max(real,expected);
  const annual=rnd(projected*12);
  const confidence=daysObserved>=45&&count>=6?'Alta':daysObserved>=21&&count>=4?'Media':'Inicial';
  groups.push({...g,number:count,uniqueDays:dates.length,frequency:gap,real,projected,annual,confidence,firstDate:dates[0],lastDate:dates[dates.length-1],
   monthItems,monthRefunds,allNet:Math.max(0,sumAll),average:count?Math.max(0,sumAll)/count:0,
   ignored:p.excluded.includes(g.key),forced});
 }
 const expense=Math.max(0,monthlyTotals(period.y,period.m).expense);
 for(const g of groups)g.share=expense>0?100*g.real/expense:null;
 const active=groups.filter(g=>!g.ignored),ignored=groups.filter(g=>g.ignored);
 const actual=active.reduce((s,g)=>s+g.real,0),projected=active.reduce((s,g)=>s+g.projected,0);
 const annual=projected*12;
 return {...period,expense,groups,active,ignored,actual,projected,annual,
  participation:expense>0?100*actual/expense:null,empty:groups.length===0};
}
const antPct=v=>v===null?'Sin base':v.toLocaleString('es-DO',{maximumFractionDigits:1,minimumFractionDigits:1})+'%';
const antFreq=g=>g.frequency===null?'Aún sin ritmo':g.frequency<=1?'Cada día':`Cada ${g.frequency.toLocaleString('es-DO',{maximumFractionDigits:1})} días`;
function antHighlights(model){
 const active=model.active;
 if(!active.length)return '<p class="ant-muted">Aún no hay hábitos confirmados en este período. Aparecerán tras varias compras identificables; puedes revisar el umbral en Reglas.</p>';
 const byCount=active.slice().sort((a,b)=>b.number-a.number)[0];
 const bySpend=active.slice().sort((a,b)=>b.real-a.real)[0];
 const extras=[];
 if(byCount)extras.push(`<strong>${sanitize(byCount.label)}</strong> es tu hábito más frecuente, con ${byCount.number} compras observadas (${antFreq(byCount).toLowerCase()}).`);
 if(bySpend&&bySpend.key!==byCount?.key)extras.push(`<strong>${sanitize(bySpend.label)}</strong> concentra el mayor gasto reconocido del mes: ${money(bySpend.real,'DOP',2)}.`);
 return extras.map(s=>`<p>${s}</p>`).join('');
}
function antWeeklyChart(m){
 const bars=Array.from({length:8},(_,i)=>{
  const end=addDays(m.cutoff,-7*(7-i)),start=addDays(end,-6);
  const val=m.active.reduce((sum,g)=>{
   const bought=g.items.filter(t=>t.date>=start&&t.date<=end).reduce((a,t)=>a+t.amountDop,0);
   const refunded=g.refunds.filter(t=>t.date>=start&&t.date<=end).reduce((a,t)=>a+t.amountDop,0);
   return sum+Math.max(0,bought-refunded);
  },0);
  return {start,end,val:rnd(val)};
 });
 const max=Math.max(1,...bars.map(b=>b.val));
 return `<section class="ant-panel ant-weekly"><div class="ant-section-heading"><div><span class="ant-eyebrow">EVOLUCIÓN REAL</span><h3>Las últimas ocho semanas</h3><p>Importes reconocidos de los hábitos detectados, sin incluir pagos ni transferencias.</p></div><span class="ant-weekly-total">${money(bars.reduce((s,b)=>s+b.val,0))}</span></div><div class="ant-weekly-chart" role="img" aria-label="Gráfico de gasto hormiga real por semana">${bars.map(b=>`<div class="ant-week" title="${prettyDate(b.start)} a ${prettyDate(b.end)} · ${money(b.val,'DOP',2)}"><span class="ant-week-value">${b.val?money(b.val):'—'}</span><span class="ant-week-track"><i style="height:${b.val?Math.max(5,100*b.val/max):0}%"></i></span><small>${dateObj(b.end).toLocaleDateString('es-DO',{day:'2-digit',month:'short'})}</small></div>`).join('')}</div></section>`;
}
function antTableRows(groups,model){
 const maxActual=Math.max(1,...groups.map(g=>g.real));
 return groups.map((g,i)=>`<tr data-ant-search="${sanitize((g.label+' '+g.origin).toLocaleLowerCase('es'))}"><td class="ant-rank">${i+1}</td><td><strong>${sanitize(g.label)}</strong><small>${sanitize(g.origin)} · ${g.confidence==='Inicial'?'Pocos datos':'Ritmo '+g.confidence.toLowerCase()}</small></td><td class="ant-num">${g.number}</td><td>${antFreq(g)}</td><td class="ant-num">${money(g.real,'DOP',2)}<span class="ant-bar"><i style="width:${(100*g.real/maxActual).toFixed(1)}%"></i></span></td><td class="ant-num">${antPct(g.share)}</td><td class="ant-num">${money(g.projected)}</td><td class="ant-num">${money(g.annual)}</td><td><div class="ant-row-actions"><button type="button" data-ant="detail" data-key="${sanitize(g.key)}">Ver compras</button><button type="button" data-ant="${g.ignored?'restore':'ignore'}" data-key="${sanitize(g.key)}">${g.ignored?'Restaurar':'No es hormiga'}</button></div></td></tr>`).join('');
}
function antDetail(g,model){
 const all=[...g.items.map(t=>({...t,_refund:false})),...g.refunds.map(t=>({...t,_refund:true}))]
  .sort((a,b)=>b.date.localeCompare(a.date)||String(b.id||'').localeCompare(String(a.id||'')));
 return `<section class="ant-panel ant-detail" id="ant-detail" aria-label="Detalle de ${sanitize(g.label)}"><div class="ant-section-heading"><div><span class="ant-eyebrow">DETALLE DEL HÁBITO</span><h3>${sanitize(g.label)}</h3><p>${g.number} compras en los últimos 90 días · ${antFreq(g).toLowerCase()} · ${g.confidence==='Inicial'?'Estimación con pocos datos':'Confianza '+g.confidence.toLowerCase()}</p></div><button type="button" class="ant-icon-close" data-ant="close" aria-label="Cerrar detalle">×</button></div><div class="ant-detail-metrics"><div><small>COMPRA PROMEDIO</small><b>${money(g.average,'DOP',2)}</b></div><div><small>ÚLTIMA COMPRA</small><b>${prettyDate(g.lastDate)}</b></div><div><small>REAL DEL MES</small><b>${money(g.real,'DOP',2)}</b></div></div><div class="ant-table-scroll"><table class="ant-table ant-activity"><thead><tr><th>Fecha</th><th>Comercio o concepto</th><th>Categoría original</th><th>Tipo</th><th class="ant-num">Importe RD$</th></tr></thead><tbody>${all.map(t=>`<tr><td>${prettyDate(t.date)}</td><td>${sanitize(t.merchant||t.note||t.description||g.label)}</td><td>${v255TransactionCategoryCell(t)}</td><td>${t._refund?'Devolución':'Compra'}</td><td class="ant-num">${t._refund?'−':''}${money(t.amountDop,'DOP',2)} <small>${sanitize(t.currency||'DOP')}</small></td></tr>`).join('')}</tbody></table></div><div class="ant-detail-footer"><button type="button" data-ant="${g.ignored?'restore':'ignore'}" data-key="${sanitize(g.key)}">${g.ignored?'Volver a mostrar este hábito':'No es un gasto hormiga'}</button><button type="button" data-act="navigate" data-id="register">Abrir Movimientos ${icon('arrow')}</button></div></section>`;
}
function antPage(){
 const m=antModel();
 const list=(antUi.tab==='ignored'?m.ignored:m.active).slice();
 const compare=antUi.sort||'frequency';
 list.sort((a,b)=>compare==='cost'?b.real-a.real:compare==='projection'?b.projected-a.projected:compare==='share'?num(b.share)-num(a.share):b.number-a.number);
 const selected=m.groups.find(g=>g.key===antUi.selected);
 const count=list.length;
 const p=antPrefs();
 const isOpen=m.end>today();
 const top=list.slice(0,3);
 const stats=[['RITMO MENSUAL',money(m.projected),'Según compras detectadas'],['EQUIVALENTE ANUAL',money(m.annual),'Si mantienes el mismo patrón'],['PESO EN EGRESOS',antPct(m.participation),'Sobre los gastos del período']];
 return `<div class="ant-module ${window.matchMedia('(max-width:790px)').matches?'ant-mobile':''}" aria-label="Gastos hormiga">
 <header class="ant-heading"><div><span class="ant-eyebrow">TU INTELIGENCIA FINANCIERA</span><h1>Gastos hormiga</h1><p>Descubre las compras que repites, cuánto representan realmente y su posible impacto futuro.</p></div><label class="ant-month-label">PERÍODO <input id="ant-month" type="month" value="${m.key}" max="${today().slice(0,7)}" aria-label="Mes de análisis"></label></header>
 <section class="ant-hero"><div class="ant-hero-primary"><span class="ant-eyebrow">GASTO HORMIGA REAL · ${sanitize(dateObj(m.start).toLocaleDateString('es-DO',{month:'long',year:'numeric'}).toUpperCase())}</span><strong>${money(m.actual)}</strong><p>${m.active.length} hábitos detectados · ${m.active.reduce((s,g)=>s+g.monthItems.length,0)} compras este mes</p><button type="button" data-ant="rules">${icon('settings')} Ajustar detección</button></div><div class="ant-hero-stats">${stats.map(([label,value,desc])=>`<div><small>${label}</small><strong>${value}</strong><span>${desc}</span></div>`).join('')}</div></section>
 <section class="ant-insight-panel"><div><span class="ant-eyebrow">LO QUE ESTÁS REPITIENDO</span><h2>Hábitos bajo la lupa</h2>${antHighlights(m)}</div><div class="ant-insight-side"><strong>${antPct(m.participation)}</strong><small>de tus egresos reconocidos este mes</small><span class="ant-total-progress"><i style="width:${Math.max(0,Math.min(100,m.participation||0))}%"></i></span></div></section>
 ${antWeeklyChart(m)}
 ${antUi.showRules?`<section class="ant-panel ant-rulepanel"><div class="ant-section-heading"><div><span class="ant-eyebrow">CONTROL DE DETECCIÓN</span><h3>Reglas de análisis</h3></div><button type="button" data-ant="rules">Cerrar</button></div><div class="ant-rulegrid"><label>Importe máximo por compra (RD$)<input type="number" id="ant-amount" min="1" max="100000" step="50" value="${p.maxUnitDop}"></label><label>Compras mínimas en 90 días<input type="number" id="ant-repeat" min="2" max="30" step="1" value="${p.minRepetitions}"></label></div><p>Estas reglas solo afectan la detección. No modifican categorías, presupuestos, saldos ni movimientos registrados.</p><button type="button" class="ant-primary-button" data-ant="save-rules">Aplicar reglas</button></section>`:''}
 <section class="ant-panel ant-directory"><div class="ant-section-heading"><div><span class="ant-eyebrow">RECURRENCIAS</span><h3>Ranking de hábitos</h3><p>Compara frecuencia, gasto mensual real y proyección. Abre una fila para revisar todas las compras.</p></div><div class="ant-list-toolbar"><div class="ant-tabs" role="group" aria-label="Mostrar hábitos"><button type="button" data-ant="tab" data-value="habits" class="${antUi.tab==='habits'?'active':''}">Detectados <b>${m.active.length}</b></button><button type="button" data-ant="tab" data-value="ignored" class="${antUi.tab==='ignored'?'active':''}">Ignorados <b>${m.ignored.length}</b></button></div><button type="button" class="ant-export" data-ant="export">${icon('down')} CSV</button><label class="ant-sort-label">Ordenar por <select id="ant-sort"><option value="frequency" ${compare==='frequency'?'selected':''}>Frecuencia</option><option value="cost" ${compare==='cost'?'selected':''}>Gasto real</option><option value="projection" ${compare==='projection'?'selected':''}>Proyección</option><option value="share" ${compare==='share'?'selected':''}>Participación</option></select></label></div></div>
 <label class="ant-search-label">${icon('search')}<input type="search" id="ant-search" value="${sanitize(antUi.search)}" placeholder="Buscar comercio o hábito" aria-label="Buscar hábitos"></label>
 ${!count?`<div class="ant-empty"><span>${icon('chart')}</span><h4>${antUi.tab==='ignored'?'No has ignorado ningún hábito':'Todavía no se detectan hábitos recurrentes'}</h4><p>${antUi.tab==='ignored'?'Los hábitos excluidos aparecerán aquí y podrás restaurarlos.':'Registra varias compras identificables en diferentes días o revisa las reglas de detección. No se inventarán datos.'}</p></div>`:`<div class="ant-table-scroll ant-main-table"><table class="ant-table"><thead><tr><th>#</th><th>Hábito</th><th>Compras 90d</th><th>Frecuencia</th><th class="ant-num">Real del mes</th><th class="ant-num">Participación</th><th class="ant-num">Ritmo mensual</th><th class="ant-num">Anual estimado</th><th>Opciones</th></tr></thead><tbody>${antTableRows(list,m)}</tbody></table></div><div class="ant-mobile-list">${list.map((g,i)=>`<article class="ant-habit-card" data-ant-search="${sanitize((g.label+' '+g.origin).toLocaleLowerCase('es'))}"><div class="ant-habit-top"><span class="ant-habit-mark">${icon('chart')}</span><div><strong>${sanitize(g.label)}</strong><small>${g.number} compras · ${antFreq(g)}</small></div><span class="ant-habit-share">${antPct(g.share)}</span></div><div class="ant-habit-values"><div><small>REAL ESTE MES</small><b>${money(g.real)}</b></div><div><small>RITMO MENSUAL</small><b>${money(g.projected)}</b></div><div><small>ANUAL ESTIMADO</small><b>${money(g.annual)}</b></div></div><div class="ant-habit-actions"><button type="button" data-ant="detail" data-key="${sanitize(g.key)}">Ver compras</button><button type="button" data-ant="${g.ignored?'restore':'ignore'}" data-key="${sanitize(g.key)}">${g.ignored?'Restaurar':'No es hormiga'}</button></div></article>`).join('')}</div>`}
 <p class="ant-table-note">Real = egresos contabilizados en el mes, netos de devoluciones identificables. El ritmo se estima con hasta 90 días de compras observadas y puede variar. El anual no es un cargo futuro ni una deuda.</p></section>
 ${selected?antDetail(selected,m):''}
 <section class="ant-footer-info"><span>${icon('shield')}</span><p>Solo se analizan compras y consumos con tarjeta. Los pagos de tarjeta, préstamos, transferencias y entradas de dinero no se suman nuevamente. Excluir un hábito nunca borra sus movimientos.</p></section>
 </div>`;
}
